import{b as e}from"./chunk-GSPUEYRK.js";import"./chunk-WOT6VMZA.js";var a={"1 comp\xE1s":"1 bar","1.\xAA":"1st","12 variaciones sobre \xABAh, vous dirai-je, maman\xBB, K. 265 (hacia 1781\u20131782) \u2014 tema":"12 Variations on \u201CAh, vous dirai-je, maman\u201D, K. 265 (c. 1781\u20131782) \u2014 theme","1653\u20131706":"1653\u20131706","1732\u20131809":"1732\u20131809","1756\u20131791":"1756\u20131791","1770\u20131827":"1770\u20131827","1805\u20131847":"1805\u20131847","1843\u20131907":"1843\u20131907","1859\u20131916":"1859\u20131916","1861\u20131949":"1861\u20131949","2 \u2212 1 = 1.":"2 \u2212 1 = 1.","2.\xAA":"2nd","2.\xBA-3.\xBA y 5.\xBA-6.\xBA":"2nd-3rd and 5th-6th","2/4":"2/4","2/4 y 4/4":"2/4 and 4/4","3 \u2212 1 = 2 pulsos.":"3 \u2212 1 = 2 beats.","3.\xAA":"3rd","3.\xBA-4.\xBA y 7.\xBA-8.\xBA":"3rd-4th and 7th-8th","3/4":"3/4","3/4 y 4/4":"3/4 and 4/4","4/4":"4/4","A (compases 1-8: pregunta 1-4 / respuesta 5-8) + B (estribillo 9-16)":"A (bars 1-8: question 1-4 / answer 5-8) + B (chorus 9-16)","A (f) + A eco (p)":"A (f) + A echo (p)","A dos voces: la app (voz 1) mete un error en el ostinato y el alumno debe pararla sin dejar de o\xEDr su propia voz.":"In two parts: the app (part 1) slips a mistake into the ostinato and the student must stop it while still hearing their own part.","A ese bajo que se repite una y otra vez lo llamamos \xABbajo obstinado\xBB (porque es muy cabezota y no cambia).":"We call that bass that repeats over and over a \u201Cground bass\u201D (because it's very stubborn and never changes).","AB: dos partes distintas.":"AB: two different sections.","Abierta, esperando respuesta.":"Open, waiting for an answer.","Acaba en do: respuesta.":"Ends on C: answer.","Acaba en la y gira en torno a la-do-mi.":"Ends on A and circles around A-C-E.","Acaba en re: queda en el aire.":"Ends on D: left hanging in the air.","Accelerando: cada vez m\xE1s deprisa.":"Accelerando: faster and faster.","Acompa\xF1ar \xAB\xBFTe vienes?\xBB con C, G, Am y F (o C-G-Am en ukelele) entrando tras la anacrusa.":"Accompany \u201CAre You Coming?\u201D with C, G, Am and F (or C-G-Am on ukulele), coming in after the upbeat.","Acorde de toda la orquesta con timbal.":"A chord from the whole orchestra with timpani.","Acordes Am y C (y Em): acompa\xF1ar la saloma con rasgueo de 4.":"Chords Am and C (and Em): accompany the shanty with a 4-beat strum.","Acordes de La menor y Do mayor: misma mano, otro color; escala de la menor.":"A minor and C major chords: same hand, a different colour; A minor scale.","Afinar en acorde: sostener do sobre el acorde de Do.":"Tuning against a chord: hold C over the C chord.","Agrupar los pulsos de dos en dos y separarlos con la barra divisoria; reconocer la doble barra final.":"Group the beats in twos and separate them with a bar line; recognise the final double bar line.","Ahora toca MI":"Now play E","Al principio, \xBFqu\xE9 matiz pondr\xEDas?":"At the beginning, which dynamic would you use?","Alarga la nota sin contar.":"It holds the note without counting.","Alargar la nota a gusto del director":"To hold the note as long as the conductor likes",Alemania:"Germany","Alemania (Bonn) / Austria (Viena)":"Germany (Bonn) / Austria (Vienna)","Alemania (N\xFAremberg)":"Germany (Nuremberg)","Algunas de sus canciones se publicaron con el nombre de su hermano; la reina Victoria de Inglaterra eligi\xF3 como favorita una de ellas\u2026 \xA1que era de Fanny!":"Some of her songs were published under her brother's name; Queen Victoria of England chose one of them as her favourite\u2026 and it was Fanny's!","Algunas notas aparecen con \xAB\xBFDo M o La m?\xBB seg\xFAn d\xF3nde acabe la frase.":"Some notes appear with \u201CC major or A minor?\u201D depending on where the phrase ends.",Am:"Am","Anacrusa con arco arriba (para que el primer tiempo caiga con arco abajo); \xAB\xBFTe vienes?\xBB de memoria.":"Upbeat with an up-bow (so the first beat falls on a down-bow); \u201CAre You Coming?\u201D from memory.","Anacrusa con lengua suave y primer tiempo apoyado; d\xFAo pregunta (alumno) - respuesta (app).":"Upbeat with a soft tongue and a leaning first beat; question (student) - answer (app) duet.","Anacrusa de dos corcheas. Dominio p\xFAblico (melod\xEDa de 1893).":"Upbeat of two eighth notes. Public domain (melody from 1893).","Andar y correr":"Walking and running","Antes del golpe, la repetici\xF3n suena\u2026":"Before the big bang, the repeat sounds\u2026",An\u00F3nimo:"Anonymous","An\xF3nimo (tradicional franc\xE9s)":"Anonymous (traditional French)","An\xF3nimo (tradicional franc\xE9s) \u2014 Fr\xE8re Jacques / Martinillo (canon tradicional, documentado desde finales del siglo XVIII)":"Anonymous (traditional French) \u2014 Fr\xE8re Jacques / Brother John (traditional round, documented since the late 18th century)","Aparece una nota: toca su nombre (sol o mi) antes de que se acabe la mecha.":"A note appears: tap its name (G or E) before the fuse burns out.","Arriba = agudo; abajo = grave. La altura no cambia el volumen ni la duraci\xF3n.":"Up = high; down = low. Pitch doesn't change the volume or the length.","Audici\xF3n: An\xF3nimo (tradicional franc\xE9s)":"Listening: Anonymous (traditional French)","Audici\xF3n: Edvard Grieg":"Listening: Edvard Grieg","Audici\xF3n: Euphemia Allen":"Listening: Euphemia Allen","Audici\xF3n: Johann Pachelbel":"Listening: Johann Pachelbel","Audici\xF3n: Joseph Haydn":"Listening: Joseph Haydn","Audici\xF3n: Ludwig van Beethoven":"Listening: Ludwig van Beethoven","Audici\xF3n: Mildred J. Hill":"Listening: Mildred J. Hill","Audici\xF3n: Wolfgang Amadeus Mozart":"Listening: Wolfgang Amadeus Mozart","Aun as\xED compuso m\xE1s de 400 obras, y organizaba conciertos en su casa de Berl\xEDn los domingos.":"Even so, she composed more than 400 works, and held concerts at her home in Berlin on Sundays.",Austria:"Austria","Austria (Salzburgo)":"Austria (Salzburg)","B4-C5":"B4-C5","Baja casi todo el rato":"Goes down almost all the time","Baja paso a paso (fa\u266F, mi, re, do\u266F, si, la) y luego sube un poquito.":"It steps down (F\u266F, E, D, C\u266F, B, A) and then rises a little.","Baja poco a poco":"Goes down little by little","Baja un paso":"Goes down a step","Bajar sin tropezar":"Going down without tripping",Bajo:"Bass","Bajo obstinado y primera entrada del viol\xEDn 1 (ambos en negras). Dominio p\xFAblico.":"Ground bass and the first entry of violin 1 (both in quarter notes). Public domain.","Barra de repetici\xF3n: la segunda vuelta se canta con la estrofa 2.":"Repeat sign: the second time round is sung with verse 2.","Barras y doble barra":"Bar lines and double bar line",Barroco:"Baroque","Beethoven compuso esta sinfon\xEDa\u2026":"Beethoven composed this symphony\u2026","Beethoven empez\xF3 a perder el o\xEDdo cuando ten\xEDa unos 28 a\xF1os, pero sigui\xF3 componiendo: sent\xEDa la m\xFAsica por dentro.":"Beethoven began to lose his hearing when he was about 28, but he kept on composing: he felt the music inside him.",Blanca:"Half note","Blanca (2) + dos corcheas (1) = 3.":"Half note (2) + two eighth notes (1) = 3.",Blancas:"Half notes","Blancas con arco entero y negras con medio arco; mismo sonido de principio a fin.":"Half notes with a whole bow and quarter notes with half a bow; the same sound from start to finish.","Blancas dejando vibrar la cuerda; apagar en los silencios. Guitarra: primer punteo.":"Half notes letting the string ring; damp it in the rests. Guitar: first plucking.","Cada comp\xE1s es una vuelta de baile. El \xAB\xA1pum!\xBB de la segunda estrofa cae en el primer tiempo: el pie lo marca.":"Each bar is one turn of the dance. The \u201Cboom!\u201D in the second verse falls on the first beat: your foot marks it.","Cada frase descansa en una blanca: dos pulsos.":"Each phrase rests on a half note: two beats.","Cambia del todo":"Changes completely","Cambia todo el rato":"Changes all the time",Can:"Can","Canci\xF3n escolar":"School song","Canon en re mayor, para tres violines y bajo continuo (hacia 1680\u20131706)":"Canon in D major, for three violins and basso continuo (c. 1680\u20131706)","Canon infantil":"Children's round","Canon instrumental sobre bajo obstinado":"Instrumental canon over a ground bass","Cantar afinadas las notas sol y mi (la \xABllamada\xBB que todos los ni\xF1os usan para llamar a alguien).":"Sing the notes G and E in tune (the \u201Ccalling\u201D tune every child uses to call someone).","Cantar con el nombre de las notas (sol, mi) marcando el pulso en las rodillas, sin la voz gu\xEDa de la app.":"Sing with the note names (G, E) tapping the beat on your knees, without the app's guide voice.","Cantar con la app":"Sing with the app","Cantar con letra balance\xE1ndose (paso en el 1, puntillas en el 2 y el 3).":"Sing with the words while swaying (step on 1, tiptoe on 2 and 3).","Cantar con letra mientras la app marca el pulso; dar una palmada en cada \xAB\xA1ya!\xBB y \xAB\xA1ven!\xBB.":"Sing with the words while the app keeps the beat; clap on every \u201Cnow!\u201D and \u201Ccome!\u201D.","Cantar con letra moviendo los brazos en cada corchea y quieto en los silencios.":"Sing with the words, moving your arms on each eighth note and staying still in the rests.","Cantar con letra respetando p / f; la app colorea la barra de volumen de la voz.":"Sing with the words following p / f; the app colours the volume bar of your voice.","Cantar con letra subiendo la mano por pelda\xF1os imaginarios; en los compases de silencio, manos quietas y contar 1-2-3-4.":"Sing with the words, raising your hand up imaginary steps; in the bars of rest, hands still and count 1-2-3-4.","Cantar con letra y hacer el gesto de tirar de la cuerda en cada \xAB\xA1e-ho!\xBB.":"Sing with the words and mime pulling the rope on every \u201Cheave-ho!\u201D.","Cantar con letra y luego con nombre de notas la canci\xF3n de la unidad.":"Sing the unit's song with the words and then with the note names.","Cantar con letra; la app canta las preguntas y el alumno las respuestas.":"Sing with the words; the app sings the questions and the student sings the answers.","Cantar con nombre de notas":"Sing with note names","Cantar con nombre de notas dando palmas al ritmo y saltando en el primer tiempo de cada comp\xE1s.":"Sing with note names, clapping the rhythm and jumping on the first beat of each bar.","Cantar con nombre de notas y dar una palmada solo en los semitonos (mi-fa y si-do).":"Sing with note names and clap only on the semitones (E-F and B-C).","Cantar con nombre de notas, con crescendo y diminuendo graduales y los dos calderones dirigidos por la app.":"Sing with note names, with gradual crescendo and diminuendo and the two fermatas conducted by the app.","Cantar con nombre de notas, palmada en el 1.er tiempo y chasquidos en el 2 y 3, haciendo la repetici\xF3n sin ayuda visual.":"Sing with note names, clap on the 1st beat and click your fingers on 2 and 3, doing the repeat without visual help.","Cantar el octocorde de do mayor subiendo y bajando sin apoyo.":"Sing the C major octachord up and down without support.","Cantar el tricorde do-re-mi por imitaci\xF3n (re se canta de o\xEDdo antes de leerlo).":"Sing the C-D-E trichord by imitation (D is sung by ear before reading it).","Cantar melod\xEDas en la menor centradas en la, con su \xE1mbito mi4\u2013re5.":"Sing melodies in A minor centred on A, with their range E4\u2013D5.","Cantar mirando la partitura":"Sing while looking at the score","Cantar o palmear el motivo principal":"Sing or clap the main motif","Cantar sin la melod\xEDa de la app (solo acompa\xF1amiento)":"Sing without the app's melody (accompaniment only)","Cantar todo con nombre de notas, palmas en el comp\xE1s 12 y entrada en anacrusa sin cuenta.":"Sing everything with note names, clap in bar 12 and come in on the upbeat without a count-in.","Cantar y dar palmas con distintos matices, y cambiar de matiz sin cambiar el tempo.":"Sing and clap with different dynamics, and change dynamic without changing the tempo.","Caza el semitono":"Catch the semitone","Caza el semitono: la app canta una escala de 5 notas y el alumno toca entre qu\xE9 dos notas estaba el pelda\xF1o corto.":"Catch the semitone: the app sings a 5-note scale and the student taps which two notes had the short step between them.",Cinco:"Five","Cinco l\xEDneas y cuatro espacios, contados desde abajo.":"Five lines and four spaces, counted from the bottom.","Cinco notas del curso; acento de lengua suave en el 1.er tiempo.":"Five notes from the course; soft tongue accent on the 1st beat.",Clasicismo:"Classical","Clasicismo\u2013Romanticismo":"Classical\u2013Romantic","Coge esta melod\xEDa en do mayor y c\xE1mbiale SOLO el final para que acabe en la. Escucha c\xF3mo cambia el color.":"Take this melody in C major and change ONLY the ending so it finishes on A. Listen to how the colour changes.","Compases completos, termina en sol, una s\xEDlaba por nota.":"Complete bars, ends on G, one syllable per note.","Compases completos; al menos un silencio.":"Complete bars; at least one rest.","Completa el comp\xE1s con UNA figura":"Complete the bar with ONE note value","Completa el comp\xE1s de 3/4":"Complete the 3/4 bar","Completa el comp\xE1s de 4/4 con una sola figura":"Complete the 4/4 bar with a single note value","Completa la respuesta para que acabe en casa":"Complete the answer so it ends at home","Comp\xF3n 4 compases con mi, sol y la que suenen a robot y ponles una letra de 4 a 8 s\xEDlabas por frase. Termina en sol.":"Compose 4 bars with E, G and A that sound like a robot and give them words of 4 to 8 syllables per phrase. End on G.","Comp\xF3n 4 compases de 4/4 con al menos dos blancas y un silencio de blanca. Compases 1-2 = llamada (acaba en sol), 3-4 = respuesta (acaba en do).":"Compose 4 bars of 4/4 with at least two half notes and a half rest. Bars 1-2 = call (ends on G), 3-4 = answer (ends on C).","Comp\xF3n 4 compases en 3/4 con do-re-mi-sol-la y ponles barra de repetici\xF3n. Termina en do. \xA1Suena bien hagas lo que hagas!":"Compose 4 bars in 3/4 with C-D-E-G-A and add a repeat sign. End on C. It sounds good whatever you do!","Comp\xF3n 4 compases en f y rep\xEDtelos como eco en p (8 en total). Termina con un calder\xF3n y usa el re agudo al menos una vez.":"Compose 4 bars in f and repeat them as an echo in p (8 in total). End with a fermata and use high D at least once.","Comp\xF3n 4 compases en la menor con una llamada (2 compases) y un \xAB\xA1e-ho!\xBB de respuesta. Marca la respiraci\xF3n con una coma.":"Compose 4 bars in A minor with a call (2 bars) and a \u201Cheave-ho!\u201D in answer. Mark the breath with a comma.","Comp\xF3n 8 compases en do mayor con una redonda, un silencio de redonda y los dos semitonos (mi-fa y si-do) en alg\xFAn momento.":"Compose 8 bars in C major with a whole note, a whole rest and both semitones (E-F and B-C) somewhere.","Comp\xF3n una canci\xF3n de 8 compases con forma AB: A (4 compases, pregunta + respuesta) y B (4 compases distintos). Empieza en anacrusa, termina en do y escribe la letra. Se env\xEDa al profesor para el concierto de fin de nivel.":"Compose an 8-bar song in AB form: A (4 bars, question + answer) and B (4 different bars). Start with an upbeat, end on C and write the words. It is sent to the teacher for the end-of-level concert.","Con los a\xF1os, alguien le cambi\xF3 la letra\u2026 y se convirti\xF3 en la canci\xF3n m\xE1s cantada del mundo: \xABCumplea\xF1os feliz\xBB.":"Over the years, someone changed the words\u2026 and it became the most sung song in the world: \u201CHappy Birthday\u201D.","Con saltos grandes":"With big leaps","Con su hermana Patty, maestra de educaci\xF3n infantil, escribi\xF3 canciones f\xE1ciles para que los ni\xF1os peque\xF1os cantaran en clase.":"With her sister Patty, a nursery school teacher, she wrote easy songs for little children to sing in class.","Con un gran salto":"With one big leap","Construir, cantar y tocar la escala de do mayor y nombrar sus grados.":"Build, sing and play the C major scale and name its degrees.","Construye la escala de do mayor tocando las notas en orden":"Build the C major scale by tapping the notes in order","Construye la escala de la menor (de la a la)":"Build the A minor scale (from A to A)","Contar hasta tres":"Counting to three","Contesta a la llamada":"Answer the call","Contiene negra con puntillo: reservar a la variante media o aplicar filtro de c\xE9lulas.":"Contains a dotted quarter note: keep for the medium variant or apply a rhythm-cell filter.","Coral (himno a cuatro tiempos)":"Chorale (hymn in four beats)",Corchea:"Eighth note",Corcheas:"Eighth notes","Corcheas a manos alternas D-I-D-I sobre el pulso del pie.":"Eighth notes with alternating hands R-L-R-L over the foot's beat.","Corcheas a pares":"Eighth notes in pairs","Corcheas alternando \xEDndice-medio (i-m) en cuerdas al aire.":"Eighth notes alternating index-middle (i-m) on open strings.","Corcheas con lengua \xABtu-tu\xBB en la primera nota; luego alternando dos notas.":"Eighth notes tongued \u201Ctu-tu\u201D on the first note; then alternating two notes.","Corcheas con lengua \xABtu-tu\xBB sin cortar el aire; primeras tres notas del curso.":"Eighth notes tongued \u201Ctu-tu\u201D without cutting the air; the first three notes of the course.","Corcheas con medio arco cerca del tal\xF3n; la-mi-sol en la cuerda que toque el curso.":"Eighth notes with half a bow near the frog; A-E-G on the string the course uses.","Corcheas: do-do, mi-mi, sol-sol\u2026":"Eighth notes: C-C, E-E, G-G\u2026","Crece poco a poco (crescendo)":"Grows little by little (crescendo)","Crecer no es correr: el pulso no cambia.":"Growing louder isn't going faster: the beat doesn't change.",Crescendo:"Crescendo","Cuando entra el viol\xEDn, \xBFva m\xE1s deprisa o m\xE1s despacio que el bajo?":"When the violin comes in, is it faster or slower than the bass?","Cuando era ni\xF1o":"When he was a child","Cuando la primera llega a la segunda frase (comp\xE1s 5).":"When the first one reaches the second phrase (bar 5).","Cuando ya casi no o\xEDa":"When he could hardly hear any more",Cuatro:"Four","Cuatro frases cortas.":"Four short phrases.","Cuatro pulsos: UN-dos-TRES-cuatro.":"Four beats: ONE-two-THREE-four.","Cuatro, muy a menudo.":"Four, very often.","Cuatro: un comp\xE1s entero de 4/4.":"Four: a whole bar of 4/4.","Cuelga como un murci\xE9lago.":"It hangs like a bat.","Cuelga de la 4.\xAA l\xEDnea":"Hangs from the 4th line","Cuerdas al aire en negras con arco entero y silencio con el arco parado sobre la cuerda.":"Open strings in quarter notes with a whole bow, and rests with the bow still on the string.","Cumplea\xF1os feliz":"Happy Birthday","Da palmas con el bajo. \xBFCada nota del bajo dura\u2026?":"Clap along with the bass. Each bass note lasts\u2026","Da un salto grande":"Takes a big leap","De cuatro":"In four","De dos":"In two","De dos (2/4)":"In two (2/4)","De la Uni\xF3n Europea.":"Of the European Union.","De mayor a menor":"From major to minor","De sol a la, la melod\xEDa\u2026":"From G to A, the melody\u2026","De tres":"In three","De tres (3/4)":"In three (3/4)","Debajo, el bajo repite sin parar las mismas ocho notas, todas negras, como un coraz\xF3n que late durante toda la pieza.":"Underneath, the bass repeats the same eight notes non-stop, all quarter notes, like a heart beating through the whole piece.","Despu\xE9s de morir Mozart, en 1792":"After Mozart died, in 1792","Di el nombre de estas notas en orden":"Say the names of these notes in order","Dictado de la canci\xF3n":"Song dictation","Dictado de la canci\xF3n: escribir el ritmo de los compases 1-4 de \xABRobots en el patio\xBB (ya cantada).":"Song dictation: write the rhythm of bars 1-4 of \u201CRobots in the Playground\u201D (already sung).","Dictado de la canci\xF3n: primero el ritmo de los compases 1-2 de \xABEl faro\xBB; luego sus notas; por \xFAltimo ambas cosas juntas.":"Song dictation: first the rhythm of bars 1-2 of \u201CThe Lighthouse\u201D; then its notes; finally both together.","Dictado mel\xF3dico":"Melodic dictation","Dictado r\xEDtmico":"Rhythmic dictation","Diecis\xE9is.":"Sixteen.",Diminuendo:"Diminuendo","Dio clases al hermano mayor de Johann Sebastian Bach, que a su vez ense\xF1\xF3 m\xFAsica al peque\xF1o Johann Sebastian.":"He taught Johann Sebastian Bach's older brother, who in turn taught music to little Johann Sebastian.","Distinguir de o\xEDdo una negra de dos corcheas.":"Tell a quarter note from two eighth notes by ear.","Distinguir de o\xEDdo y con el cuerpo compases de dos, tres y cuatro pulsos.":"Tell bars of two, three and four beats apart by ear and with your body.","Distinguir una frase \xABpregunta\xBB (acaba abierta, en re o sol) de una \xABrespuesta\xBB (acaba en do).":"Tell a \u201Cquestion\u201D phrase (ends open, on D or G) from an \u201Canswer\u201D (ends on C).","Dividir el pulso en dos partes iguales: correr dentro del latido.":"Split the beat into two equal parts: running inside the heartbeat.","Dividir el pulso: corcheas \xABti-ti\xBB sobre la misma nota, y la nueva nota la.":"Split the beat: eighth notes \u201Cti-ti\u201D on the same note, and the new note A.",Do:"C","Do I, re II, mi III, fa IV, sol V.":"C I, D II, E III, F IV, G V.","Do M":"C major","Do M (do-mi-sol-la)":"C major (C-E-G-A)","Do M (mi-sol-la)":"C major (E-G-A)","Do M (original en Do M)":"C major (original in C major)","Do M (original en Re M)":"C major (original in D major)","Do M (pentat\xF3nica)":"C major (pentatonic)","Do M (sol-mi)":"C major (G-E)","Do M y La m":"C major and A minor","Do agudo":"High C","Do grave est\xE1 debajo del pentagrama, atravesado por una l\xEDnea adicional.":"Low C is below the staff, crossed by a ledger line.","Do mayor":"C major","Do, la nota casa":"C, the home note","Do, sol grave, do: como una campana grande.":"C, low G, C: like a big bell.","Do-do, mi-mi, sol-sol: esas tres notas del principio forman\u2026":"C-C, E-E, G-G: those three notes at the start form\u2026","Do-do, sol-sol, la-la\u2026: de dos en dos.":"C-C, G-G, A-A\u2026: in twos.","Do-mi-sol: el acorde de t\xF3nica, nota a nota.":"C-E-G: the tonic chord, note by note.","Do-mi-sol: mayor, luminoso.":"C-E-G: major, bright.","Do-re y sol-la":"C-D and G-A",Dos:"Two","Dos blancas = una redonda.":"Two half notes = one whole note.","Dos corcheas = una negra = un pulso.":"Two eighth notes = one quarter note = one beat.","Dos corcheas y una negra, \xBFcu\xE1ntos pulsos suman?":"Two eighth notes and a quarter note: how many beats do they add up to?","Dos hermanas":"Two sisters","Dos negras":"Two quarter notes","Dos negras = una blanca.":"Two quarter notes = one half note.","Dos pasitos en un latido":"Two little steps in one heartbeat","Dos pulsos":"Two beats","Dos pulsos \xD7 dos corcheas = cuatro.":"Two beats \xD7 two eighth notes = four.","Dos: el doble de una negra.":"Two: double a quarter note.","Dos: la segunda empieza cuando la primera va por la segunda frase.":"Two: the second starts when the first reaches the second phrase.","Dos: una por cada mano.":"Two: one for each hand.","Dura 4 pulsos y el comp\xE1s solo tiene 3.":"It lasts 4 beats and the bar only has 3.","E4-F4":"E4-F4","Edvard Grieg":"Edvard Grieg","Edvard Grieg \u2014 \xABEn la gruta del rey de la monta\xF1a\xBB, de \xABPeer Gynt\xBB, op. 23 (1875)":"Edvard Grieg \u2014 \u201CIn the Hall of the Mountain King\u201D, from \u201CPeer Gynt\u201D, Op. 23 (1875)","El 1.\xBA":"The 1st","El 2.\xBA":"The 2nd","El 4.\xBA":"The 4th","El alumno canta solo las respuestas (\xAB\xA1brilla, brilla! \xA1luz!\xBB y \xABduerme, duerme, mar\xBB), con letra.":"The student sings only the answers (\u201Ctwinkle, twinkle! light!\u201D and \u201Csleep, sleep, sea\u201D), with the words.","El alumno canta todo con nombre de notas, marcando el pulso y abriendo las manos en cada blanca.":"The student sings everything with note names, keeping the beat and opening their hands on each half note.","El bajo":"The bass","El bajo va todo en negras: un latido por nota.":"The bass is all quarter notes: one heartbeat per note.","El bajo, \xBFcambia o repite lo mismo?":"Does the bass change or repeat the same thing?","El calder\xF3n":"The fermata","El calder\xF3n sirve para\u2026":"The fermata is used to\u2026","El calder\xF3n y el re agudo (\xE1mbito completo do4\u2013re5)":"The fermata and high D (full range C4\u2013D5)","El comp\xE1s de 3/4 (ternario) y los signos de repetici\xF3n":"3/4 time (triple) and repeat signs","El comp\xE1s de 4/4":"4/4 time","El do grave (l\xEDnea adicional): la casa de la t\xF3nica":"Low C (ledger line): the tonic's home","El eco de la monta\xF1a":"The Mountain Echo","El famoso golpe fort\xEDsimo: \xA1la sorpresa!":"The famous fortissimo bang: the surprise!","El faro":"The Lighthouse","El faro (Espiritual de llamada y respuesta (g\xF3spel))":"The Lighthouse (Call-and-response spiritual (gospel))","El final de la obra":"The end of the piece","El golpe final se escribir\xEDa con\u2026":"The final bang would be written with\u2026","El golpe grave llega cada tres pulsos.":"The low thump comes every three beats.","El impulso antes del primer tiempo.":"The run-up before the first beat.","El latido":"The heartbeat","El nivel 3 puede salir en menor; incluye semicorcheas: solo variante media.":"Level 3 may come out in minor; includes sixteenth notes: medium variant only.","El n\xFAmero de arriba: 2.":"The top number: 2.","El n\xFAmero de arriba: 3.":"The top number: 3.","El pentagrama, la clave de sol y las notas sol y mi":"The staff, the treble clef and the notes G and E","El preg\xF3n de la frutera":"The Fruit Seller's Call","El preg\xF3n de la frutera (Preg\xF3n de mercado (canto de calle))":"The Fruit Seller's Call (Market cry (street song))","El primero":"The first","El pulso y la negra (con su silencio)":"The beat and the quarter note (with its rest)","El pulso y las negras pasan al instrumento: notas iguales, a tempo, con silencio de verdad (el sonido se corta).":"The beat and quarter notes move to the instrument: even notes, in tempo, with a real rest (the sound stops).","El robot canta":"The Robot Sings","El segundo":"The second","El silencio de blanca":"The half rest","El silencio de blanca\u2026":"The half rest\u2026","El silencio de negra":"The quarter rest","El silencio de redonda\u2026":"The whole rest\u2026","El silencio tambi\xE9n se cuenta: el pulso no se detiene.":"Rests are counted too: the beat doesn't stop.","El tempo de este vals es\u2026":"The tempo of this waltz is\u2026","El viol\xEDn":"The violin","El \xFAltimo comp\xE1s paga la deuda":"The last bar pays the debt","Elige tu melod\xEDa de la unidad 5 (o la lectura f\xE1cil) y a\xF1ade p, f, un crescendo, un diminuendo y un calder\xF3n al final. La app la tocar\xE1 como la has pintado.":"Choose your melody from unit 5 (or the easy reading) and add p, f, a crescendo, a diminuendo and a fermata at the end. The app will play it the way you painted it.","Empezar antes de empezar":"Starting before the start","Empieza en do.":"It starts on C.","Empieza en sol.":"It starts on G.","Empieza y acaba en la.":"It starts and ends on A.","En 1893 publicaron \xABGood Morning to All\xBB (\xABBuenos d\xEDas a todos\xBB): la melod\xEDa era de Mildred y la letra de Patty.":"In 1893 they published \u201CGood Morning to All\u201D: the melody was Mildred's and the words were Patty's.","En 2/4, \xBFcu\xE1ntos pulsos tiene cada comp\xE1s?":"In 2/4, how many beats does each bar have?","En 4/4, \xBFqu\xE9 pulso es el m\xE1s fuerte?":"In 4/4, which beat is the strongest?","En Par\xEDs oy\xF3 una canci\xF3n popular francesa muy sencilla y escribi\xF3 doce VARIACIONES sobre ella.":"In Paris he heard a very simple French folk song and wrote twelve VARIATIONS on it.","En do (casa)":"On C (home)","En do, la t\xF3nica.":"On C, the tonic.","En do: la nota casa.":"On C: the home note.","En el 3":"In bar 3","En el 5":"In bar 5","En el 9":"In bar 9","En el Barroco (siglo XVII).":"In the Baroque (17th century).","En el comp\xE1s de 3/4 hay TRES pulsos de negra: \xABUN-dos-tres\xBB. El primero pesa, los otros dos flotan. Es el comp\xE1s del vals: \xA1da una vuelta en cada comp\xE1s!":"A 3/4 bar has THREE quarter-note beats: \u201CONE-two-three\u201D. The first is heavy, the other two float. It's the waltz time: you turn once in every bar!","En el estreno, en 1824, Beethoven no o\xEDa los aplausos y una cantante le dio la vuelta para que viera al p\xFAblico aplaudir.":"At the premiere, in 1824, Beethoven couldn't hear the applause and a singer turned him round so he could see the audience clapping.","En esta primera entrada, viol\xEDn y bajo van ambos en negras.":"In this first entry, violin and bass are both in quarter notes.","En la 2.\xAA: por eso esa l\xEDnea se llama sol.":"On the 2nd: that's why that line is called G.","En la Sinfon\xEDa n.\xBA 94 hay un momento famoso: la melod\xEDa suena muy suave, se repite todav\xEDa m\xE1s suave\u2026 y de golpe toda la orquesta da un golpe fort\xEDsimo.":"In Symphony No. 94 there's a famous moment: the melody plays very softly, repeats even more softly\u2026 and suddenly the whole orchestra plays a fortissimo bang.","En la menor, \xBFentre qu\xE9 grados est\xE1n los semitonos?":"In A minor, between which degrees are the semitones?","En re o sol (abierta)":"On D or G (open)","En un silencio de negra, el pulso\u2026":"During a quarter rest, the beat\u2026","En una escena, Peer entra en la cueva del rey de los trolls. La m\xFAsica empieza muy suave y grave, de puntillas\u2026":"In one scene, Peer enters the cave of the troll king. The music starts very soft and low, on tiptoe\u2026","Entradas en anacrusa (redoble de entrada) y ritmo de la canci\xF3n en bater\xEDa sencilla.":"Upbeat entries (lead-in drum roll) and the song's rhythm on a simple drum kit.","Es an\xF3nima y tradicional.":"It's anonymous and traditional.","Es igual que la primera":"It's the same as the first","Es la t\xF3nica: la nota de reposo.":"It's the tonic: the resting note.","Es m\xFAsica nacionalista noruega.":"It's Norwegian nationalist music.","Es un canon: una voz empieza y, cuando llega a la segunda frase, otra voz empieza desde el principio. \xA1Encajan como piezas de puzle!":"It's a round: one voice starts and, when it reaches the second phrase, another voice starts from the beginning. They fit together like puzzle pieces!","Es un rayito":"It's a little lightning bolt","Es un vals: UN-dos-tres.":"It's a waltz: ONE-two-three.","Es una de las piezas de piano m\xE1s tocadas del mundo\u2026 \xA1y casi nadie sabe que la escribi\xF3 una adolescente!":"It's one of the most played piano pieces in the world\u2026 and hardly anyone knows a teenager wrote it!","Esa misma melod\xEDa la conocemos en Espa\xF1a como \xABEstrellita, \xBFd\xF3nde est\xE1s?\xBB.":"In English we know that same melody as \u201CTwinkle, Twinkle, Little Star\u201D.","Escala de do con paso del pulgar (1-2-3 / 1-2-3-4-5).":"C scale with the thumb passing under (1-2-3 / 1-2-3-4-5).","Escala de do en primera posici\xF3n, alternando i-m.":"C scale in first position, alternating i-m.","Escala de do mayor (viol\xEDn: dedo 2 bajo, fa y do naturales); redondas a arco entero.":"C major scale (violin: low 2nd finger, F and C natural); whole notes with a whole bow.","Escala de la banda (si\u266D de concierto en trompeta, que lee do) por mitades.":"The band scale (concert B\u266D on trumpet, which reads C) in halves.","Escala de la banda por mitades y notas tenidas de cuatro pulsos.":"The band scale in halves and long notes of four beats.","Escala de la menor (do, fa y sol naturales); frases de 4 compases con arco que \xABrespira\xBB al final.":"A minor scale (C, F and G natural); 4-bar phrases with a bow that \u201Cbreathes\u201D at the end.","Escala de la menor natural; respiraci\xF3n solo en las comas.":"Natural A minor scale; breathe only at the commas.","Escala menor relativa de la escala de la banda; frases de 4 compases sin cortar el aire.":"The relative minor scale of the band scale; 4-bar phrases without breaking the air.","Escalera con descansillo":"Stairs with a landing","Escocia (Reino Unido)":"Scotland (United Kingdom)","Escribe 2 compases de 2/4 con negras y silencios de negra: una negra por cada s\xEDlaba de tu nombre y apellido, y silencios donde respires.":"Write 2 bars of 2/4 with quarter notes and quarter rests: one quarter note for each syllable of your first name and surname, and rests where you breathe.","Escribe 4 compases de 2/4 con negras, corcheas y alg\xFAn silencio. Cada comp\xE1s debe tener al menos una pareja de corcheas.":"Write 4 bars of 2/4 with quarter notes, eighth notes and a rest or two. Each bar must have at least one pair of eighth notes.","Escribe 4 compases de 3/4 sin silencio en el primer tiempo (el baile no puede tropezar). Usa al menos una blanca.":"Write 4 bars of 3/4 with no rest on the first beat (the dance mustn't trip). Use at least one half note.","Escribe 4 compases de 4/4 que solo se muevan por grados conjuntos (sin saltos) y terminen con una redonda en do.":"Write 4 bars of 4/4 that move only by step (no leaps) and end with a whole note on C.","Escribi\xF3 la m\xFAsica para la obra de teatro \xABPeer Gynt\xBB, la historia de un joven fanfarr\xF3n que vive aventuras fant\xE1sticas.":"He wrote the music for the play \u201CPeer Gynt\u201D, the story of a boastful young man who has fantastic adventures.","Escribi\xF3 m\xE1s de cien sinfon\xEDas; por eso le llaman \xABel padre de la sinfon\xEDa\xBB.":"He wrote more than a hundred symphonies; that's why he's called \u201Cthe father of the symphony\u201D.","Escribi\xF3 m\xFAsica de todo tipo: \xF3peras, sinfon\xEDas, conciertos\u2026 y tambi\xE9n piezas para ense\xF1ar y divertirse.":"He wrote all kinds of music: operas, symphonies, concertos\u2026 and also pieces for teaching and for fun.","Escucha c\xF3mo las dos notas se van separando comp\xE1s a comp\xE1s, como un abanico que se abre.":"Listen to how the two notes move apart bar by bar, like a fan opening.","Escucha dos notas: \xBFtono o semitono?":"Listen to two notes: tone or semitone?","Escucha dos versiones: \xBFcu\xE1l es piano?":"Listen to two versions: which one is piano?","Escucha la canci\xF3n completa y elige su forma":"Listen to the whole song and choose its form","Escucha la melod\xEDa entera: \xBFmayor o menor?":"Listen to the whole melody: major or minor?","Escucha y elige el comp\xE1s":"Listen and choose the time signature","Escucha: \xBFde dos, de tres o de cuatro?":"Listen: in two, in three or in four?","Escucha: \xBFmayor o menor?":"Listen: major or minor?","Escucha: \xBFpregunta o respuesta?":"Listen: question or answer?","Escucha: \xBFqu\xE9 hace el sonido?":"Listen: what does the sound do?","Escuchar a la app (eco)":"Listen to the app (echo)","Escuchar el fragmento (2 veces)":"Listen to the excerpt (twice)","Escuchar marcando el pulso":"Listen while keeping the beat","Escuchar y localizar los dos semitonos de la escala (mi-fa, si-do).":"Listen and find the two semitones in the scale (E-F, B-C).",Espa\u00F1a:"Spain","Espiritual de llamada y respuesta (g\xF3spel)":"Call-and-response spiritual (gospel)","Esta naci\xF3 en Francia como \xABFr\xE8re Jacques\xBB y en Espa\xF1a la conocemos como \xABMartinillo\xBB.":"This one was born in France as \u201CFr\xE8re Jacques\u201D, and in English we know it as \u201CBrother John\u201D.","Estados Unidos (Kentucky)":"United States (Kentucky)",Estrellita:"Twinkle, Twinkle","Est\xE1 en modo menor: por eso suena misteriosa, como un secreto que se va haciendo enorme.":"It's in a minor key: that's why it sounds mysterious, like a secret that keeps growing bigger.","Euphemia Allen":"Euphemia Allen","Euphemia Allen ten\xEDa solo 16 a\xF1os cuando compuso este vals, en 1877.":"Euphemia Allen was only 16 when she composed this waltz, in 1877.","Euphemia Allen \u2014 \xABThe Celebrated Chop Waltz\xBB (1877)":"Euphemia Allen \u2014 \u201CThe Celebrated Chop Waltz\u201D (1877)","Fa-sol es un tono entero.":"F-G is a whole tone.","Falta un pulso: negra, silencio de negra o dos corcheas.":"One beat is missing: a quarter note, a quarter rest or two eighth notes.","Falta un pulso: vale una negra o un silencio de negra.":"One beat is missing: a quarter note or a quarter rest will do.","Faltan dos pulsos: blanca o silencio de blanca.":"Two beats are missing: a half note or a half rest.","Faltan mi (III) y la (VI).":"E (III) and A (VI) are missing.","Fanny Mendelssohn Hensel":"Fanny Mendelssohn Hensel","Fanny era tan buena pianista y compositora como su hermano Felix, pero a ella le dijeron que la m\xFAsica solo pod\xEDa ser \xABun adorno\xBB en su vida.":"Fanny was as good a pianist and composer as her brother Felix, but she was told that music could only be \u201Can ornament\u201D in her life.",Fin:"End","Finales del siglo XIX":"Late 19th century","Formas: AB y ABA":"Forms: AB and ABA","Forte: fuerte.":"Forte: loud.","Fort\xEDsimo.":"Fortissimo.",Francia:"France","Frases y respiraci\xF3n":"Phrases and breathing","Fr\xE8re Jacques / Martinillo (canon tradicional, documentado desde finales del siglo XVIII)":"Fr\xE8re Jacques / Brother John (traditional round, documented since the late 18th century)","Fue gran amigo de Mozart y profesor de un joven Beethoven.":"He was a great friend of Mozart and a teacher of the young Beethoven.",Fuerte:"Loud","Fuerte (f)":"Loud (f)","Fuerte y suave":"Loud and soft","Fuerte, d\xE9bil, semifuerte, d\xE9bil: cuatro.":"Strong, weak, half-strong, weak: four.",F\u00E1cil:"Easy","F\xEDjate: no empieza en el primer tiempo, \xA1empieza en anacrusa!":"Look: it doesn't start on the first beat, it starts on an upbeat!","Golpes fuertes y suaves con la altura de la baqueta; redoble en crescendo.":"Loud and soft strokes using the height of the stick; a crescendo roll.","Grieg fue un pianista y compositor noruego que quiso que su m\xFAsica sonara a los paisajes y leyendas de su pa\xEDs.":"Grieg was a Norwegian pianist and composer who wanted his music to sound like the landscapes and legends of his country.","Grieg quer\xEDa que su m\xFAsica sonara a\u2026":"Grieg wanted his music to sound like\u2026","Grupos de dos: el comp\xE1s de 2/4":"Groups of two: 2/4 time","Habanera (la app acompa\xF1a con el ritmo de habanera)":"Habanera (the app accompanies with a habanera rhythm)","Hacer crescendo y diminuendo graduales, sin saltos bruscos.":"Make gradual crescendos and diminuendos, without sudden jumps.","Hay melod\xEDas que nadie sabe qui\xE9n invent\xF3: pasan de abuelos a nietos cantando, y por eso las llamamos tradicionales.":"Some melodies nobody knows who invented: they pass from grandparents to grandchildren by singing, and that's why we call them traditional.","Haydn trabaj\xF3 casi treinta a\xF1os para una familia de pr\xEDncipes, con su propia orquesta: pod\xEDa probar cada idea nueva al d\xEDa siguiente.":"Haydn worked for almost thirty years for a family of princes, with his own orchestra: he could try out every new idea the next day.","Hoy es el himno de la Uni\xF3n Europea, as\xED que suena en actos oficiales de muchos pa\xEDses.":"Today it's the anthem of the European Union, so it's played at official events in many countries.","Hoy esta melod\xEDa es el himno de\u2026":"Today this melody is the anthem of\u2026",III:"III","Igual: negras":"The same: quarter notes",Iguales:"The same","Incluye la3 y si3 (l\xEDneas adicionales) solo para leer, no para cantar.":"Includes A3 and B3 (ledger lines) for reading only, not for singing.","Interpretar la barra de repetici\xF3n (|: :|) sin perderse.":"Play the repeat sign (|: :|) without getting lost.","Inventa el preg\xF3n de tu comida favorita: 4 compases con sol y mi, negras y silencios, que acabe en sol. Escribe la letra debajo.":"Make up a street call for your favourite food: 4 bars with G and E, quarter notes and rests, ending on G. Write the words underneath.",Jap\u00F3n:"Japan","Johann Pachelbel":"Johann Pachelbel","Johann Pachelbel fue organista en iglesias de varias ciudades alemanas y un maestro muy querido.":"Johann Pachelbel was a church organist in several German cities and a much-loved teacher.","Johann Pachelbel \u2014 Canon en re mayor, para tres violines y bajo continuo (hacia 1680\u20131706)":"Johann Pachelbel \u2014 Canon in D major, for three violins and basso continuo (c. 1680\u20131706)","Joseph Haydn":"Joseph Haydn","Joseph Haydn \u2014 Sinfon\xEDa n.\xBA 94 en sol mayor, \xABLa sorpresa\xBB (1791), 2.\xBA movimiento \u2014 comienzo":"Joseph Haydn \u2014 Symphony No. 94 in G major, \u201CSurprise\u201D (1791), 2nd movement \u2014 opening","Juego STOP":"STOP game","Juego del cangrejo: leer el ejercicio del final al principio.":"Crab game: read the exercise from the end to the beginning.",La:"A","La Uni\xF3n Europea":"The European Union","La anacrusa (empezar antes del primer tiempo)":"The upbeat (starting before the first beat)","La app canta 2 compases (llamada). Escribe 2 compases de respuesta con do, mi, sol y la que terminen en una blanca en do.":"The app sings 2 bars (the call). Write 2 bars of answer with C, E, G and A, ending on a half note on C.","La app canta una pregunta de 2 compases. Escribe la respuesta (2 compases) que empiece igual y termine en do.":"The app sings a 2-bar question. Write the answer (2 bars) so it starts the same and ends on C.","La app recita con el ritmo perfecto pero se equivoca de matiz (fuerte donde pone p) o no espera en el calder\xF3n. STOP.":"The app recites with perfect rhythm but gets the dynamic wrong (loud where it says p) or doesn't wait at the fermata. STOP.","La app recita el ejercicio medio con \xABta\xBB y cambia una negra por silencio o al rev\xE9s; el alumno pulsa STOP en el comp\xE1s exacto.":"The app recites the medium exercise on \u201Cta\u201D and swaps a quarter note for a rest or vice versa; the student presses STOP in the exact bar.","La app recita y en un comp\xE1s cambia \xABti-ti\xBB por \xABta\xBB (o al rev\xE9s). STOP en el comp\xE1s exacto.":"The app recites and in one bar changes \u201Cti-ti\u201D to \u201Cta\u201D (or vice versa). STOP in the exact bar.","La app recita y en un comp\xE1s mete un pulso de m\xE1s (como si fuera 4/4). STOP cuando el vals \xABcojea\xBB.":"The app recites and in one bar adds an extra beat (as if it were 4/4). STOP when the waltz \u201Climps\u201D.","La app suelta una blanca a la mitad (dura uno) o cambia corcheas. STOP en el comp\xE1s exacto.":"The app lets go of a half note halfway (it lasts one) or changes eighth notes. STOP in the exact bar.","La app \xABse come\xBB un comp\xE1s de silencio o corta una redonda. STOP.":"The app \u201Cswallows\u201D a bar of rest or cuts a whole note short. STOP.","La barra de repetici\xF3n :| significa\u2026":"The repeat sign :| means\u2026","La blanca y el silencio de blanca; el comp\xE1s de 4/4":"The half note and the half rest; 4/4 time","La blanca: dos latidos":"The half note: two heartbeats","La brisa y el mar":"The Breeze and the Sea","La brisa y el mar (Habanera (la app acompa\xF1a con el ritmo de habanera))":"The Breeze and the Sea (Habanera (the app accompanies with a habanera rhythm))","La canci\xF3n ES la teor\xEDa: sube y baja la escala y canta los dos semitonos \xABd\xE1ndose la mano\xBB. Los compases de silencio de redonda son el descansillo de la escalera.":"The song IS the theory: it goes up and down the scale and sings the two semitones \u201Cholding hands\u201D. The bars of whole rest are the landing on the stairs.","La canci\xF3n explica la unidad: la pregunta (\xAB\xBFTe vienes a cantar?\xBB) acaba arriba, en re; la respuesta (\xAB\xA1S\xED, vamos a bailar!\xBB) acaba en do. Empieza en anacrusa y el \xFAltimo comp\xE1s tiene solo 3 pulsos. En el silencio del comp\xE1s 12 todo el mundo da dos palmadas.":"The song explains the unit: the question (\u201CAre you coming to sing?\u201D) ends up high, on D; the answer (\u201CYes, let's go and dance!\u201D) ends on C. It starts with an upbeat and the last bar has only 3 beats. In the rest in bar 12 everyone claps twice.","La casa de las notas":"The notes' house","La doble barra final indica\u2026":"The final double bar line shows\u2026","La escala de do mayor en el instrumento: primera escala del gimnasio de t\xE9cnica.":"The C major scale on the instrument: the first scale in the technique gym.","La escala de do mayor: tonos y semitonos (mi-fa y si-do)":"The C major scale: tones and semitones (E-F and B-C)","La escala de la menor":"The A minor scale","La escala de la menor en el instrumento y la misma melod\xEDa tocada en do mayor y en la menor.":"The A minor scale on the instrument, and the same melody played in C major and in A minor.","La escalera":"The Staircase","La escalera (Coral (himno a cuatro tiempos))":"The Staircase (Chorale (hymn in four beats))","La escalera de do":"The C staircase","La est\xE1 en el 2.\xBA espacio.":"A is in the 2nd space.","La est\xE1 justo encima de sol.":"A is just above G.","La forma musical: frases pregunta-respuesta, AB y ABA":"Musical form: question-answer phrases, AB and ABA","La frase \xABdin, don, dan\xBB r\xE1pida usa\u2026":"The fast phrase \u201Cding, dong, dang\u201D uses\u2026","La hermana menor":"The younger sister","La llave: clave de sol":"The key: treble clef","La m":"A minor","La m (original en si menor)":"A minor (original in B minor)","La melod\xEDa de la \xABOda a la alegr\xEDa\xBB casi no salta: va paso a paso, por grados conjuntos, como quien sube y baja una escalera.":"The melody of the \u201COde to Joy\u201D hardly leaps at all: it moves step by step, by conjunct motion, like someone going up and down a staircase.","La melod\xEDa del viol\xEDn\u2026":"The violin's melody\u2026","La melod\xEDa m\xE1s aguda llega a\u2026":"The highest melody reaches\u2026","La melod\xEDa se mueve sobre todo\u2026":"The melody mostly moves\u2026","La melod\xEDa vuelve al principio: forma A\u2013B\u2013A.":"The melody returns to the beginning: A\u2013B\u2013A form.","La melod\xEDa, \xBFes siempre la misma o cambia?":"Is the melody always the same, or does it change?","La menor":"A minor","La menor: mismas notas, empieza en la.":"A minor: the same notes, starting on A.","La misma melod\xEDa transformada":"The same melody transformed","La m\xFAsica tambi\xE9n susurra y grita":"Music whispers and shouts too","La m\xFAsica tiene coraz\xF3n: el pulso":"Music has a heart: the beat","La negra":"The quarter note","La negra: un latido":"The quarter note: one heartbeat","La nota de reposo final decide la tonalidad.":"The final resting note decides the key.","La nota la (2.\xBA espacio)":"The note A (2nd space)","La nota re: la escala pentat\xF3nica do-re-mi-sol-la":"The note D: the C-D-E-G-A pentatonic scale","La primera":"The first","La primera (acaba en re)":"The first (ends on D)","La primera frase acaba en si y la segunda en do. La segunda suena a\u2026":"The first phrase ends on B and the second on C. The second sounds like\u2026","La primera frase vuelve al final: ABA.":"The first phrase comes back at the end: ABA.","La primera y la \xFAltima frase son\u2026":"The first and last phrases are\u2026","La reconoces aunque cambie de ropa.":"You recognise it even when it changes clothes.","La redonda y el silencio de redonda (silencio de comp\xE1s entero)":"The whole note and the whole rest (a whole bar's rest)","La redonda y su silencio":"The whole note and its rest","La respuesta acaba en do.":"The answer ends on C.","La segunda":"The second","La segunda (acaba en do)":"The second (ends on C)","La segunda es m\xE1s suave.":"The second one is softer.","La tercera frase\u2026":"The third phrase\u2026","La tercera la-do es\u2026":"The third A-C is\u2026","La tonalidad de la menor (natural), relativa de do mayor":"The key of A minor (natural), relative of C major","La-do tiene un semitono dentro (si-do): es menor.":"A-C has a semitone inside (B-C): it's minor.","La-do-mi: menor.":"A-C-E: minor.","Las corcheas (dos en un pulso) y el comp\xE1s de 2/4 con su barra divisoria":"Eighth notes (two in a beat) and 2/4 time with its bar line","Las corcheas corren: dos por pulso.":"Eighth notes run: two per beat.","Las corcheas son los movimientos r\xE1pidos del robot y las negras los pasos lentos. El alumno se mueve como un robot: brazos en las corcheas, pie en las negras.":"The eighth notes are the robot's quick movements and the quarter notes its slow steps. The student moves like a robot: arms on the eighth notes, feet on the quarter notes.","Las dos corcheas hacen un pulso y la negra otro.":"The two eighth notes make one beat and the quarter note another.","Las dos frases empiezan igual. \xBFCu\xE1l suena a final?":"Both phrases start the same. Which one sounds like an ending?","Las dos notas, comp\xE1s a comp\xE1s\u2026":"The two notes, bar by bar\u2026","Las dos primeras notas son anacrusa.":"The first two notes are an upbeat.","Las frases del medio terminan en re. \xBFSuenan a final?":"The middle phrases end on D. Do they sound like an ending?","Las melod\xEDas tambi\xE9n conversan":"Melodies have conversations too","Las mismas notas, otro color":"The same notes, another colour","Las notas de la melod\xEDa van de dos en dos y\u2026":"The notes of the melody go in twos and\u2026","Las primeras notas suben\u2026":"The first notes go up\u2026","Las salomas eran cantos de los marineros para tirar de los cabos todos a la vez: el \xAB\xA1e-ho!\xBB cae siempre en el mismo sitio. Toda la canci\xF3n usa solo las notas de do mayor, pero descansa en la: \xA1es la hermana menor!":"Shanties were songs sailors sang to pull the ropes all together: the \u201Cheave-ho!\u201D always falls in the same place. The whole song uses only the notes of C major, but it rests on A: it's the younger sister!","Lectura de notas a tempo":"Note reading in tempo","Lectura mel\xF3dica cantada":"Sung melodic reading","Lectura r\xEDtmica f\xE1cil":"Easy rhythm reading","Lectura r\xEDtmica media":"Medium rhythm reading","Leer fa (1.er espacio), si (3.\xAA l\xEDnea) y do agudo (3.er espacio).":"Read F (1st space), B (3rd line) and high C (3rd space).","Leer la ficha":"Read the card","Leer re agudo (4.\xAA l\xEDnea) y cantar todo el \xE1mbito do4\u2013re5.":"Read high D (4th line) and sing the whole range C4\u2013D5.","Leer y cantar do4 en su l\xEDnea adicional y sentirlo como \xABcasa\xBB: la nota donde la m\xFAsica descansa.":"Read and sing C4 on its ledger line and feel it as \u201Chome\u201D: the note where the music rests.","Leer y cantar la, sol y mi (la peque\xF1a \xABcanci\xF3n de corro\xBB de tres notas).":"Read and sing A, G and E (the little three-note \u201Cplayground song\u201D).","Leer y cantar re; cantar melod\xEDas pentat\xF3nicas (sin semitonos).":"Read and sing D; sing pentatonic melodies (no semitones).","Leer y escribir en 3/4; saber que en 3/4 no cabe una redonda ni dos blancas.":"Read and write in 3/4; know that a whole note or two half notes don't fit in 3/4.","Leer y escribir en 4/4 y reconocer el acento del 1.er tiempo y el semifuerte del 3.\xBA.":"Read and write in 4/4 and recognise the accent on the 1st beat and the half-strong 3rd.",Lento:"Slow","Llamada (solista, compases 1-2 y 5-6) y respuesta (coro, compases 3-4 y 7-8). La app canta la llamada y el alumno responde; en la variante media se cambian los papeles.":"Call (soloist, bars 1-2 and 5-6) and response (choir, bars 3-4 and 7-8). The app sings the call and the student answers; in the medium variant the roles swap.",Lle:"Lle","Llega a la nota m\xE1s aguda":"Reaches the highest note","Lo mismo, pero con retraso: se persiguen.":"The same, but delayed: they chase each other.","Lo public\xF3 con un nombre de chico inventado, \xABArthur de Lulli\xBB, porque en su \xE9poca a las chicas compositoras no se las tomaba en serio.":"She published it under a made-up boy's name, \u201CArthur de Lulli\u201D, because in her day girl composers weren't taken seriously.","Los Juegos Ol\xEDmpicos":"The Olympic Games","Los matices":"Dynamics","Los matices: pp, p, mf, f, ff, crescendo y diminuendo":"Dynamics: pp, p, mf, f, ff, crescendo and diminuendo","Los pregones (las llamadas de los vendedores en la calle) usan casi siempre dos notas: sol y mi. El ni\xF1o ya los conoce; aqu\xED descubre que tienen nombre.":"Street calls (the cries of sellers in the street) almost always use two notes: G and E. Children already know them; here they discover they have names.","Ludwig van Beethoven":"Ludwig van Beethoven","Ludwig van Beethoven \u2014 Sinfon\xEDa n.\xBA 9 en re menor, op. 125 (1824), 4.\xBA movimiento \u2014 tema de la \xABOda a la alegr\xEDa\xBB":"Ludwig van Beethoven \u2014 Symphony No. 9 in D minor, Op. 125 (1824), 4th movement \u2014 \u201COde to Joy\u201D theme","Mano derecha":"Right hand","Mano derecha en posici\xF3n de do: sol (dedo 5) y mi (dedo 3) en negras, levantando la mano en los silencios.":"Right hand in C position: G (finger 5) and E (finger 3) in quarter notes, lifting the hand in the rests.","Mano izquierda":"Left hand","Mantener un sonido durante dos pulsos sin acortarlo (contando por dentro).":"Hold a sound for two beats without cutting it short (counting inside).","Mantener una redonda cuatro pulsos y contar un comp\xE1s entero de silencio.":"Hold a whole note for four beats and count a whole bar of rest.",Mar:"Mar","Marcha rob\xF3tica (canci\xF3n de movimiento)":"Robot march (movement song)",Martinillo:"Brother John","Matices en el instrumento: m\xE1s/menos arco, aire, peso del brazo o altura de la baqueta, sin desafinar ni cambiar el tempo.":"Dynamics on the instrument: more/less bow, air, arm weight or stick height, without going out of tune or changing the tempo.",Mayor:"Major","Mayor (m\xE1s grande)":"Major (bigger)",Medio:"Medium","Medio pulso":"Half a beat",Melod\u00EDa:"Melody","Melod\xEDa con mano derecha y bajo do-sol con la izquierda; \xABPara Elisa\xBB empieza en anacrusa.":"Melody in the right hand and a C-G bass in the left; \u201CF\xFCr Elise\u201D starts on an upbeat.","Melod\xEDa de cinco notas del curso en 3/4; respiraci\xF3n en la barra de repetici\xF3n.":"Five-note melody from the course in 3/4; breathe at the repeat sign.","Melod\xEDa tradicional, dominio p\xFAblico.":"Traditional melody, public domain.","Melod\xEDas de tres dedos en 3/4: arco abajo en el 1 de cada comp\xE1s (la \xABregla del arco\xBB del vals).":"Three-finger melodies in 3/4: down-bow on 1 in every bar (the waltz \u201Cbow rule\u201D).",Menor:"Minor","Menor (m\xE1s peque\xF1a)":"Minor (smaller)","Menor: misteriosa.":"Minor: mysterious.","Mezzoforte: medio fuerte.":"Mezzoforte: medium loud.",Mi:"E","Mi canci\xF3n AB":"My AB song","Mi espiritual":"My spiritual","Mi est\xE1 en la 1.\xAA l\xEDnea, justo debajo de sol.":"E is on the 1st line, just below G."};var o={"Mi menor":"E minor","Mi saloma":"My shanty","Mi, sol, la con dedos 3-5 y 5 extendido; corcheas con dedos alternos sobre la misma tecla.":"E, G, A with fingers 3-5 and 5 stretched; eighth notes with alternating fingers on the same key.","Mi-fa es un semitono: casi se tocan.":"E-F is a semitone: they almost touch.","Mi-fa y si-do":"E-F and B-C","Mi-fa y si-do: los pelda\xF1os cortos.":"E-F and B-C: the short steps.","Mi-mi-fa-sol\u2026":"E-E-F-G\u2026","Mildred Hill":"Mildred Hill","Mildred Hill era maestra de m\xFAsica, pianista y compositora en Louisville (Kentucky).":"Mildred Hill was a music teacher, pianist and composer in Louisville (Kentucky).","Mildred J. Hill":"Mildred J. Hill","Mildred J. Hill \u2014 \xABGood Morning to All\xBB, en \xABSong Stories for the Kindergarten\xBB (1893)":"Mildred J. Hill \u2014 \u201CGood Morning to All\u201D, in \u201CSong Stories for the Kindergarten\u201D (1893)","Mildred; su hermana Patty escribi\xF3 la letra.":"Mildred; her sister Patty wrote the words.","Modo mayor y menor de o\xEDdo; la frase musical y la respiraci\xF3n (coma)":"Major and minor by ear; the musical phrase and breathing (comma)","Mozart tocaba el piano y el viol\xEDn ante reyes cuando ten\xEDa seis a\xF1os, y viaj\xF3 por media Europa con su hermana Nannerl, que tambi\xE9n era una pianista excelente.":"Mozart played the piano and the violin for kings when he was six, and travelled across half of Europe with his sister Nannerl, who was also an excellent pianist.","Muchas compositoras de su \xE9poca tuvieron que hacer lo mismo.":"Many women composers of her time had to do the same.","M\xE1s aguda":"Higher","M\xE1s deprisa":"Faster","M\xE1s despacio":"Slower","M\xE1s fuerte":"Louder","M\xE1s larga":"Longer","M\xE9todo Pro: primera pieza del temario asignable equivalente al final de nivel 1":"Pro Method: first assignable syllabus piece, equivalent to the end of level 1","M\xFAsica para teatro":"Music for the theatre","M\xFAsica tradicional":"Traditional music","Negra y silencio de negra duran un pulso cada uno.":"A quarter note and a quarter rest last one beat each.","Negras con manos alternas (D-I) y silencio con la baqueta quieta; xil\xF3fono: sol y mi.":"Quarter notes with alternating hands (R-L) and rests with the stick still; xylophone: G and E.",Ninguna:"None","Ninguna, igual que do mayor.":"None, just like C major.",Ninguno:"None","Nivel 1 incluye blanca y redonda: usar solo como reto de la variante media.":"Level 1 includes half and whole notes: use only as a challenge in the medium variant.","Nivel 2 puede salir en 3/4; incluye puntillo: solo en variante media.":"Level 2 may come out in 3/4; includes dots: medium variant only.",No:"No","No cambia":"It doesn't change","No tiene":"It hasn't got one","No, a \xABcontinuar\xE1\xBB":"No, like \u201Cto be continued\u201D","No, en anacrusa":"No, on an upbeat","No, es tradicional":"No, it's traditional","No, solo la fuerza":"No, only the volume","Nombra la nota":"Name the note","Nombra las notas":"Name the notes",Noruega:"Norway","Notas antes del primer tiempo fuerte":"Notes before the first strong beat","Notas que se quedan a vivir dos latidos":"Notes that stay for two heartbeats","Notas tenidas con buzzing y negras con lengua \xABtu\xBB sobre la primera nota del curso.":"Long notes with buzzing and quarter notes tongued \u201Ctu\u201D on the course's first note.","Notas tenidas con regulador: necesita el par\xE1metro de din\xE1mica.":"Long notes with a hairpin: needs the dynamics parameter.","Notas tenidas de 2 y 4 pulsos con columna de aire; blancas en la melod\xEDa del curso.":"Long notes of 2 and 4 beats with a column of air; half notes in the course melody.","Notas tenidas en crescendo y diminuendo manteniendo la afinaci\xF3n (vigilar que no suba al apretar).":"Long notes with crescendo and diminuendo while staying in tune (watch that it doesn't go sharp when you push).","Notas tenidas p < f > p sin que se abra el sonido; ecos f/p en la escala.":"Long notes p < f > p without the sound spreading; f/p echoes on the scale.","Notas tenidas y blancas con aire constante; primera melod\xEDa de cinco notas.":"Long notes and half notes with steady air; first five-note melody.","Nueva nota: la":"New note: A","Ocho pelda\xF1os y dos escalones cortitos":"Eight steps and two short ones","Ordena de m\xE1s corta a m\xE1s larga":"Order from shortest to longest","Ordena de m\xE1s suave a m\xE1s fuerte":"Order from softest to loudest","Ordena del m\xE1s grave al m\xE1s agudo":"Order from lowest to highest","Ordena la escala pentat\xF3nica de grave a agudo":"Order the pentatonic scale from low to high","Ordenamiento: bicorde":"Ordering: two-note set","Ordenamiento: heptacorde":"Ordering: seven-note set","Ordenamiento: hexacorde":"Ordering: six-note set","Ordenamiento: octocorde":"Ordering: octachord","Ordenamiento: pentacorde":"Ordering: five-note set","Ordenamiento: tetracorde":"Ordering: tetrachord","Ordenamiento: tetracorde \xB7 Tetracordes en la menor (mi4\u2013re5)":"Ordering: tetrachord \xB7 Tetrachords in A minor (E4\u2013D5)","Ordenamiento: tricorde":"Ordering: trichord","Ordenamiento: tricorde \xB7 Tricordes en la menor (mi4\u2013re5)":"Ordering: trichord \xB7 Trichords in A minor (E4\u2013D5)","Original (Band Flow), letra y m\xFAsica":"Original (Band Flow), words and music","Palmas con el 1.er tiempo m\xE1s fuerte; la app mide si el acento cae en el 1":"Clapping with the 1st beat louder; the app checks the accent falls on 1","Palmas con matices: la app mide el volumen de cada palmada (dedos en la palma = p; mano entera = f)":"Clapping with dynamics: the app measures the volume of each clap (fingers on palm = p; whole hand = f)","Palmas con metr\xF3nomo en todos los pulsos y voz \xABta / sh\xBB de apoyo":"Clapping with the metronome on every beat and a \u201Cta / sh\u201D support voice","Palmas diciendo en voz alta los n\xFAmeros de los pulsos (1-2-3-4), sin vocablos":"Clapping while saying the beat numbers out loud (1-2-3-4), no vocables","Palmas diciendo los vocablos; metr\xF3nomo en cada pulso":"Clapping while saying the vocables; metronome on each beat","Palmas en silencio y pie en el primer tiempo (la app escucha solo las palmas)":"Silent clapping and foot on the first beat (the app only listens to the claps)","Palmas en silencio; durante el comp\xE1s de silencio la app no da ninguna pista":"Silent clapping; during the bar of rest the app gives no clues","Palmas sin decir nada (audici\xF3n interior); el metr\xF3nomo solo marca el 1.er tiempo":"Clapping without saying anything (inner hearing); the metronome only marks the 1st beat","Palmas sin vocablos, con barra de repetici\xF3n: se toca dos veces y la segunda sin metr\xF3nomo":"Clapping without vocables, with a repeat sign: it's played twice, the second time without metronome","Palmas sin vocablos, entrando sin cuenta previa (solo un \xABclic\xBB de entrada)":"Clapping without vocables, coming in without a count-in (just one starting \u201Cclick\u201D)","Palmas sin vocablos; el calder\xF3n se mantiene hasta que la app levanta la mano":"Clapping without vocables; the fermata is held until the app raises its hand","Palmas; en la blanca, abrir las manos despacio para \xABdibujar\xBB los dos pulsos":"Clapping; on the half note, open your hands slowly to \u201Cdraw\u201D the two beats","Palmas; en la redonda, una palmada y las manos dibujan un c\xEDrculo de cuatro pulsos":"Clapping; on the whole note, one clap and your hands draw a four-beat circle","Palmas; la app cuenta \xAB1, 2, y\u2026\xBB para que entres en la anacrusa":"Clapping; the app counts \u201C1, 2, and\u2026\u201D so you come in on the upbeat","Palmea el pulso: \xBFagrupa mejor de dos en dos o de tres en tres?":"Clap the beat: does it group better in twos or in threes?","Parece un rayo":"It looks like a lightning bolt","Paso a paso, como una escala menor.":"Step by step, like a minor scale.","Pasos de robot":"Robot steps","Patty Hill":"Patty Hill",Pausa:"Pause","Pelda\xF1os largos y cortos":"Long and short steps","Pentat\xF3nica viajera":"Travelling pentatonic","Peso del brazo: misma melod\xEDa en p y en f; calder\xF3n final con pedal opcional.":"Arm weight: the same melody in p and in f; final fermata with optional pedal.","Piano (piezas de car\xE1cter)":"Piano (character pieces)","Piano, casi de puntillas.":"Piano, almost on tiptoe.","Piano: suave.":"Piano: soft.","Pian\xEDsimo: as\xED el golpe asusta m\xE1s.":"Pianissimo: that way the bang is scarier.","Pian\xEDsimo: de puntillas.":"Pianissimo: on tiptoe.","Pinta con matices":"Paint with dynamics","Poco a poco":"Little by little","Pop (balada con estribillo)":"Pop (ballad with chorus)","Por esa broma la sinfon\xEDa se conoce como \xABLa sorpresa\xBB. Se cuenta que quer\xEDa despertar a quien se durmiera en el concierto.":"Because of that joke the symphony is known as the \u201CSurprise\u201D. They say he wanted to wake up anyone who fell asleep at the concert.","Por grados conjuntos (la-si-do-re-mi)":"By step (A-B-C-D-E)","Por pasos (grados conjuntos)":"In steps (conjunct motion)","Por un concurso":"For a competition","Porque a las mujeres compositoras no se las tomaba en serio":"Because women composers weren't taken seriously","Porque dura m\xE1s":"Because it lasts longer","Porque es la m\xE1s aguda":"Because it's the highest","Porque la melod\xEDa descansa y termina en ella":"Because the melody rests and ends on it","Porque le gustaba":"Because she liked it","Posici\xF3n de do: do-mi-sol con dedos 1-3-5; blancas con la tecla hundida hasta el final.":"C position: C-E-G with fingers 1-3-5; half notes with the key held down to the end.",Pregunta:"Question","Pregunta y respuesta":"Question and answer","Pregunta y respuesta: solo cambian los dos \xFAltimos compases.":"Question and answer: only the last two bars change.","Preguntar y responder":"Asking and answering","Preg\xF3n de mercado (canto de calle)":"Market cry (street song)","Primeras notas tenidas y luego negras con golpe de lengua \xABtu\xBB; en el silencio se respira.":"First long notes and then quarter notes tongued \u201Ctu\u201D; breathe in the rest.","Primero est\xE1n pegadas y luego se van abriendo como un abanico.":"At first they're close together and then they open out like a fan.","Primero suena el bajo; el viol\xEDn entra despu\xE9s.":"The bass plays first; the violin comes in later.","Primeros 6 compases (intervalos que se abren: 2.\xAA, 3.\xAA, 6.\xAA). Dominio p\xFAblico.":"First 6 bars (widening intervals: 2nd, 3rd, 6th). Public domain.","Pulgar sobre cuerdas al aire en negras; apagar la cuerda con la palma en cada silencio.":"Thumb on open strings in quarter notes; damp the string with your palm in each rest.","Pulsaci\xF3n cerca del puente (f) y sobre la boca (p); arpegios en crescendo.":"Plucking near the bridge (f) and over the sound hole (p); arpeggios in crescendo.",Pulso:"Beat","Que la obra termina":"That the piece ends","Que se repite":"That it repeats","RE AGUDO vive en la 4.\xAA l\xEDnea. Con \xE9l ya cantas desde do grave hasta re agudo: \xA1nueve notas!":"HIGH D lives on the 4th line. With it you can sing from low C up to high D: nine notes!","Rasgueo de vals: bajo en el 1 y dos rasgueos suaves; acordes Do y Sol.":"Waltz strum: bass on 1 and two soft strums; C and G chords.","Re M":"D major","Re agudo":"High D","Re agudo est\xE1 en la 4.\xAA l\xEDnea.":"High D is on the 4th line.","Re cuelga justo debajo de la 1.\xAA l\xEDnea.":"D hangs just below the 1st line.","Re deja la frase abierta; do la cierra.":"D leaves the phrase open; C closes it.","Re deja la pregunta en el aire; do la responde.":"D leaves the question hanging; C answers it.","Re menor":"D minor","Re y la pentat\xF3nica":"D and the pentatonic","Re-mi y la-si":"D-E and A-B","Reconocer de o\xEDdo formas AB y ABA.":"Recognise AB and ABA forms by ear.","Reconocer de o\xEDdo si una melod\xEDa es mayor (luminosa) o menor (misteriosa).":"Recognise by ear whether a melody is major (bright) or minor (mysterious).","Reconocer la negra como \xABun latido\xBB y su silencio como \xABun latido callado\xBB.":"Recognise the quarter note as \u201Cone heartbeat\u201D and its rest as \u201Cone silent heartbeat\u201D.","Reconocer y leer melod\xEDas que empiezan en anacrusa; saber que el \xFAltimo comp\xE1s completa al primero.":"Recognise and read melodies that start on an upbeat; know that the last bar completes the first.","Redondas y silencios de comp\xE1s contados en caja; xil\xF3fono: escala de do con baquetas alternas.":"Whole notes and whole-bar rests counted on the snare; xylophone: C scale with alternating mallets.","Repaso de la unidad 1":"Unit 1 review","Repaso de la unidad 2":"Unit 2 review","Repaso de la unidad 3":"Unit 3 review","Repaso de la unidad 4":"Unit 4 review","Repaso de la unidad 5":"Unit 5 review","Repaso de la unidad 6":"Unit 6 review","Repaso de la unidad 7":"Unit 7 review","Repaso de la unidad 8":"Unit 8 review","Repaso del nivel: une cada figura con su duraci\xF3n":"Level review: match each note value to its length",Repetir:"Repeat","Repetir sin escribir dos veces":"Repeating without writing it twice","Repite corcheas":"It repeats eighth notes","Repite las mismas notas":"It repeats the same notes","Repite ocho notas sin parar: es un bajo obstinado.":"It repeats eight notes non-stop: it's a ground bass.","Respetar el calder\xF3n: alargar la nota hasta que la app (el \xABdirector\xBB) indique seguir.":"Respect the fermata: hold the note until the app (the \u201Cconductor\u201D) says to go on.","Respiraci\xF3n ANTES de la anacrusa; frases pregunta-respuesta en el ritmo de banda.":"Breathe BEFORE the upbeat; question-answer phrases in the band rhythm.","Respirar al final de cada frase (coma de respiraci\xF3n) y sentir la frase de 4 compases.":"Breathe at the end of each phrase (breath comma) and feel the 4-bar phrase.","Responde a la pregunta":"Answer the question",Responder:"Answer","Responder sin volver a escuchar m\xE1s de 1 vez":"Answer without listening again more than once",Respuesta:"Answer","Respuesta tocada con el instrumento.":"Answer played on the instrument.","Reto final: lectura con anacrusa y matices.":"Final challenge: reading with an upbeat and dynamics.","Ritmo a dos voces: la app toca la voz 1 (ostinato) y el alumno la voz 2 con palmas":"Rhythm in two parts: the app plays part 1 (ostinato) and the student claps part 2","Ritmo de marcha a dos voces (bombo-caja) para la saloma; xil\xF3fono: escala de la menor.":"March rhythm in two parts (bass drum-snare) for the shanty; xylophone: A minor scale.","Ritmo de vals":"Waltz rhythm","Ritmo de vals: bombo en el 1, platillo en 2 y 3 (curso de ritmos de banda).":"Waltz rhythm: bass drum on 1, cymbal on 2 and 3 (band rhythms course).","Robots en el patio":"Robots in the Playground","Robots en el patio (Marcha rob\xF3tica (canci\xF3n de movimiento))":"Robots in the Playground (Robot march (movement song))",Romanticismo:"Romantic","Romanticismo (nacionalismo)":"Romantic (nationalism)","Romanticismo tard\xEDo (m\xFAsica de sal\xF3n)":"Late Romantic (salon music)",R\u00E1pido:"Fast","R\xE1pido y saltar\xEDn.":"Fast and bouncy.","STOP final del nivel: la app puede equivocarse en cualquier cosa aprendida (figura, silencio, comp\xE1s, anacrusa).":"End-of-level STOP: the app may get anything you've learned wrong (note value, rest, time signature, upbeat).","Saber que la menor usa las mismas notas que do mayor pero descansa en la.":"Know that A minor uses the same notes as C major but rests on A.","Saloma del barco fantasma":"The Ghost Ship Shanty","Saloma del barco fantasma (Saloma marinera (canci\xF3n de trabajo con llamada \xAB\xA1e-ho!\xBB))":"The Ghost Ship Shanty (Sea shanty (work song with a \u201Cheave-ho!\u201D call))","Saloma marinera (canci\xF3n de trabajo con llamada \xAB\xA1e-ho!\xBB)":"Sea shanty (work song with a \u201Cheave-ho!\u201D call)","Salta abajo y vuelve a do":"Leaps down and comes back to C","Salta hasta sol agudo: es el punto culminante.":"It leaps up to high G: that's the climax.","Se acelera":"It speeds up","Se calla":"It goes quiet","Se canta en todo el mundo, en decenas de idiomas.":"It's sung all over the world, in dozens of languages.","Se env\xEDa al profesor (Aula) con audio sintetizado; nota del profesor 1-10. La app solo comprueba las restricciones.":"Sent to the teacher (Classroom) with synthesised audio; teacher's mark 1-10. The app only checks the rules.","Se escribe desde la3 (2 l\xEDneas adicionales) pero se canta desde mi4.":"It's written from A3 (2 ledger lines) but sung from E4.","Se frena":"It slows down","Se juntan":"They come together","Se para":"It stops","Se queda en una nota":"It stays on one note","Se quedan iguales":"They stay the same","Se repite casi igual":"It repeats almost the same","Se repite; lo que cambia es la fuerza y el tempo.":"It repeats; what changes is the volume and the tempo.","Se separan cada vez m\xE1s":"They move further and further apart","Se sienta como un sombrero; el de redonda (que ver\xE1s pronto) cuelga.":"It sits like a hat; the whole rest (which you'll see soon) hangs.","Se sienta sobre la 3.\xAA l\xEDnea":"It sits on the 3rd line","Se toca dos veces: 4 + 4.":"It's played twice: 4 + 4.",Seis:"Six","Seis veces: dos compases de 3.":"Six times: two bars of 3.","Seis: cada negra y cada silencio de negra valen un pulso.":"Six: each quarter note and each quarter rest is worth one beat.","Semillas fijas: toda la clase hace el mismo repaso y el profesor puede compararlo.":"Fixed seeds: the whole class does the same review and the teacher can compare it.",Semitono:"Semitone","Sentir y mantener un pulso regular con el cuerpo antes de verlo escrito.":"Feel and keep a steady beat with your body before seeing it written.",Si:"B","Si est\xE1 en la 3.\xAA l\xEDnea.":"B is on the 3rd line.","Si la anacrusa dura 1 pulso en 3/4, el \xFAltimo comp\xE1s dura\u2026":"If the upbeat lasts 1 beat in 3/4, the last bar lasts\u2026","Si una melod\xEDa con las notas de do mayor termina en la, probablemente est\xE1 en\u2026":"If a melody using the notes of C major ends on A, it's probably in\u2026","Si una nota est\xE1 m\xE1s arriba en el pentagrama, suena\u2026":"If a note is higher up on the staff, it sounds\u2026","Si una parte de 4 compases lleva |: :|, \xBFcu\xE1ntos compases suenan en total?":"If a 4-bar section has |: :|, how many bars are played in total?","Si-do (2.\xBA-3.\xBA) y mi-fa (5.\xBA-6.\xBA).":"B-C (2nd-3rd) and E-F (5th-6th).","Siempre igual":"Always the same","Siglo XX":"20th century","Sigue latiendo":"It keeps beating",Silencio:"Rest",Silencios:"Rests","Silencios activos: la mano se queda quieta; blancas en l\xE1mina o redoble suave en caja.":"Active rests: the hand stays still; half notes on the bars or a soft roll on the snare.","Simplificaci\xF3n did\xE1ctica: se presenta la primera semifrase (4 compases) en p y su repetici\xF3n en pp, rematada con el golpe ff. En la partitura la frase completa tiene 8 compases. Dominio p\xFAblico.":"Teaching simplification: the first half-phrase (4 bars) is presented in p and its repeat in pp, finished off with the ff bang. In the score the full phrase is 8 bars long. Public domain.",Sinfon\u00EDa:"Symphony","Sinfon\xEDa con coro":"Choral symphony","Sinfon\xEDa n.\xBA 9 en re menor, op. 125 (1824), 4.\xBA movimiento \u2014 tema de la \xABOda a la alegr\xEDa\xBB":"Symphony No. 9 in D minor, Op. 125 (1824), 4th movement \u2014 \u201COde to Joy\u201D theme","Sinfon\xEDa n.\xBA 94 en sol mayor, \xABLa sorpresa\xBB (1791), 2.\xBA movimiento \u2014 comienzo":"Symphony No. 94 in G major, \u201CSurprise\u201D (1791), 2nd movement \u2014 opening","Situar la clave de sol en la 2.\xAA l\xEDnea y leer sol (2.\xAA l\xEDnea) y mi (1.\xAA l\xEDnea).":"Place the treble clef on the 2nd line and read G (2nd line) and E (1st line).",So:"So",Sol:"G","Sol est\xE1 en la 2.\xAA l\xEDnea, donde se enrosca la clave.":"G is on the 2nd line, where the clef curls round.","Sol: es una melod\xEDa de solo cinco notas (do-sol).":"G: it's a melody of only five notes (C-G).","Son corcheas repetidas":"They're repeated eighth notes","Son redondas":"They're whole notes","Sonidos largos":"Long sounds","Sostener el sonido dos pulsos sin que se caiga (arco largo, aire constante, tecla hundida).":"Hold the sound for two beats without letting it drop (long bow, steady air, key held down).","Su Novena sinfon\xEDa fue la primera gran sinfon\xEDa con coro y solistas cantando en el \xFAltimo movimiento.":"His Ninth Symphony was the first great symphony with a choir and soloists singing in the last movement.","Su ciclo para piano \xABDas Jahr\xBB (\xABEl a\xF1o\xBB) tiene una pieza para cada mes, con dibujos de su marido, el pintor Wilhelm Hensel.":"Her piano cycle \u201CDas Jahr\u201D (\u201CThe Year\u201D) has a piece for every month, with drawings by her husband, the painter Wilhelm Hensel.","Su obra m\xE1s famosa es un canon: los violines tocan la misma melod\xEDa, pero cada uno empieza un poco despu\xE9s que el anterior.":"His most famous work is a canon: the violins play the same melody, but each one starts a little after the one before.","Su vals se puede tocar con dos dedos, uno de cada mano, golpeando las teclas como si fueran palillos chinos; en ingl\xE9s se conoce como \xABChopsticks\xBB (\xABpalillos\xBB).":"Her waltz can be played with two fingers, one from each hand, striking the keys like chopsticks; in English it's known as \u201CChopsticks\u201D.",Suave:"Soft","Suave (p)":"Soft (p)","Sube hasta lo m\xE1s agudo":"Goes up to the very top","Sube todo el rato":"Goes up all the time","Sube un paso":"Goes up a step",S\u00ED:"Yes","S\xED, Mozart":"Yes, Mozart","S\xED, Pachelbel":"Yes, Pachelbel","S\xED, a final":"Yes, like an ending","S\xED, acelera":"Yes, it speeds up",Tema:"Theme","Tema (mano derecha)":"Theme (right hand)","Tema (violonchelos y fagotes)":"Theme (cellos and bassoons)","Tema con variaciones para piano":"Theme and variations for piano","Tema de la obra (melod\xEDa popular francesa armonizada por Mozart). Dominio p\xFAblico.":"Theme of the work (French folk melody harmonised by Mozart). Public domain.","Teor\xEDa \xB7 Corcheas a pares":"Theory \xB7 Eighth notes in pairs","Teor\xEDa \xB7 El latido":"Theory \xB7 The heartbeat","Teor\xEDa \xB7 Fuerte y suave":"Theory \xB7 Loud and soft","Teor\xEDa \xB7 La escalera de do":"Theory \xB7 The C staircase","Teor\xEDa \xB7 La hermana menor":"Theory \xB7 The younger sister","Teor\xEDa \xB7 Pregunta y respuesta":"Theory \xB7 Question and answer","Teor\xEDa \xB7 Sonidos largos":"Theory \xB7 Long sounds","Teor\xEDa \xB7 Vals en tres":"Theory \xB7 Waltz in three",Tic:"Tick","Tiene negras, blancas y una frase entera de corcheas que suena como campanas que corren.":"It has quarter notes, half notes and a whole phrase of eighth notes that sounds like bells running.","Toca DO (con su l\xEDnea adicional)":"Play C (with its ledger line)","Toca RE":"Play D","Toca RE AGUDO":"Play HIGH D","Toca SI (justo en el centro del pentagrama)":"Play B (right in the middle of the staff)","Toca en el pentagrama la nota SOL":"Tap the note G on the staff","Toca la nota LA":"Play the note A","Tocar con anacrusa y frasear pregunta-respuesta; primera pieza \xABde concierto\xBB de memoria.":"Play with an upbeat and phrase question-answer; first \u201Cconcert\u201D piece from memory.","Tocar en 3/4 marcando el primer tiempo; primera melod\xEDa de cinco notas y su repetici\xF3n.":"Play in 3/4 marking the first beat; first five-note melody and its repeat.","Tocar m\xE1s fuerte":"Play louder","Todav\xEDa m\xE1s suave":"Even softer",Tono:"Tone","Totalmente distintas":"Totally different","Transportado a do mayor para relacionarlo con la escala de la unidad. Lleva negra con puntillo (se estudiar\xE1 en el nivel 2): aqu\xED solo se escucha. Dominio p\xFAblico.":"Transposed to C major to link it to the unit's scale. It has a dotted quarter note (studied in level 2): here it's only for listening. Public domain.","Transportado a la menor. Cada repetici\xF3n sube de tempo y de volumen (accelerando y crescendo). Dominio p\xFAblico.":"Transposed to A minor. Each repeat gets faster and louder (accelerando and crescendo). Public domain.","Traza las barras (3/4) y pon una coma al final de cada frase de 2 compases":"Draw the bar lines (3/4) and put a comma at the end of each 2-bar phrase","Traza las barras (4/4)":"Draw the bar lines (4/4)","Traza las barras de comp\xE1s (2/4)":"Draw the bar lines (2/4)","Traza las barras de comp\xE1s (3/4)":"Draw the bar lines (3/4)","Traza las barras de comp\xE1s (4/4)":"Draw the bar lines (4/4)","Traza las barras: empieza en anacrusa de una negra (4/4)":"Draw the bar lines: it starts with a one-quarter-note upbeat (4/4)",Tres:"Three","Tres notas nuevas":"Three new notes","Tres veces: es la base sobre la que se construye todo el canon.":"Three times: it's the foundation the whole canon is built on.","Tu coraz\xF3n ya sabe m\xFAsica":"Your heart already knows music","Tu nombre late":"Your name has a beat","Tu propio preg\xF3n":"Your own street call","UN-dos, UN-dos: es binario.":"ONE-two, ONE-two: it's duple.","UN-dos-TRES-cuatro.":"ONE-two-THREE-four.","UN-dos-tres, UN-dos-tres.":"ONE-two-three, ONE-two-three.","UN-dos-tres: 3/4.":"ONE-two-three: 3/4.","UN-dos-tres: la m\xFAsica que gira":"ONE-two-three: music that spins","Un acorde desplegado (do-mi-sol)":"A broken chord (C-E-G)","Un canon es\u2026":"A canon is\u2026","Un crescendo gigantesco.":"A gigantic crescendo.","Un crescendo \xBFcambia el tempo?":"Does a crescendo change the tempo?","Un di\xE1logo de matices: la brisa canta piano, el mar responde forte, la ola crece (crescendo) y se retira (diminuendo). El acompa\xF1amiento de habanera es de la app; el alumno canta solo figuras conocidas.":"A dialogue of dynamics: the breeze sings piano, the sea answers forte, the wave grows (crescendo) and draws back (diminuendo). The habanera accompaniment is the app's; the student only sings note values they know.","Un equipo de f\xFAtbol":"A football team","Un golpe muy fuerte":"A very loud bang","Un pulso (negra)":"One beat (quarter note)","Un silencio":"A rest","Un silencio largo":"A long rest",Una:"One","Una ESCALA son notas seguidas, subiendo o bajando, como pelda\xF1os: do-re-mi-fa-sol-la-si-do. La de DO MAYOR empieza y acaba en do. Cada pelda\xF1o es un GRADO (I, II, III\u2026).":"A SCALE is notes in a row, going up or down, like steps: C-D-E-F-G-A-B-C. The C MAJOR scale starts and ends on C. Each step is a DEGREE (I, II, III\u2026).","Una blanca y dos corcheas, \xBFcu\xE1ntos pulsos suman?":"A half note and two eighth notes: how many beats do they add up to?","Una canci\xF3n con dos partes distintas tiene forma\u2026":"A song with two different sections has the form\u2026","Una canci\xF3n muy lenta":"A very slow song","Una canci\xF3n para una sola voz":"A song for a single voice","Una escala":"A scale","Una escalera de sonidos":"A staircase of sounds","Una flauta":"A flute","Una frase pregunta suele acabar\u2026":"A question phrase usually ends\u2026","Una l\xEDnea fina y otra gruesa: fin de la obra.":"One thin line and one thick line: the end of the piece.","Una melod\xEDa nueva sin relaci\xF3n":"A new, unrelated melody","Una negra = un latido.":"One quarter note = one heartbeat.","Una variaci\xF3n es como disfrazar una melod\xEDa: la reconoces, pero cambia de ropa (m\xE1s r\xE1pida, m\xE1s adornada, en otro modo\u2026).":"A variation is like dressing up a melody: you recognise it, but it changes clothes (faster, more decorated, in another mode\u2026).","Una variaci\xF3n es\u2026":"A variation is\u2026","Une cada signo con su nombre":"Match each sign to its name",Uno:"One",VII:"VII","Va creciendo poco a poco.":"It grows little by little.","Va m\xE1s r\xE1pido":"It goes faster","Va pelda\xF1o a pelda\xF1o, como la escala.":"It goes step by step, like the scale.",Vals:"Waltz","Vals con mano izquierda: do (1) \u2013 sol-sol (2 y 3) mientras la derecha toca la pentat\xF3nica.":"Waltz with the left hand: C (1) \u2013 G-G (2 and 3) while the right hand plays the pentatonic.","Vals de los relojes":"The Clock Waltz","Vals de los relojes (Vals)":"The Clock Waltz (Waltz)","Vals en tres":"Waltz in three","Vals para piano":"Piano waltz","Varias voces que cantan lo mismo empezando en momentos distintos":"Several voices singing the same thing, starting at different times",Veinte:"Twenty",Violines:"Violins","Viol\xEDn 1":"Violin 1","Voz 1":"Voice 1","Voz 2 (entra en el comp\xE1s 5)":"Voice 2 (comes in at bar 5)","Vuelve y repite":"Go back and repeat","Vuelves a |: (o al principio) y repites.":"You go back to |: (or to the beginning) and repeat.","Wolfgang Amadeus Mozart":"Wolfgang Amadeus Mozart","Wolfgang Amadeus Mozart \u2014 12 variaciones sobre \xABAh, vous dirai-je, maman\xBB, K. 265 (hacia 1781\u20131782) \u2014 tema":"Wolfgang Amadeus Mozart \u2014 12 Variations on \u201CAh, vous dirai-je, maman\u201D, K. 265 (c. 1781\u20131782) \u2014 theme","Y ahora, \xBFtono o semitono?":"And now, tone or semitone?","Ya estaba pr\xE1cticamente sordo.":"He was almost completely deaf by then.","a capela":"a cappella","a capela (solo la primera nota)":"a cappella (first note only)","a lo largo de las 4 repeticiones":"over the 4 repeats",acompa\u00F1amiento:"accompaniment","acordes + melod\xEDa doblada":"chords + doubled melody",al:"al","anacrusa en tiempo fuerte":"upbeat on a strong beat",aprobado:"pass",arpeggio:"arpeggio",audicion:"listening",bar:"bar",blanca:"half note","blanca acortada":"half note cut short","ca el":"ca el",calderon:"fermata",calder\u00F3n:"fermata","calder\xF3n ignorado":"fermata ignored",com:"com","comp\xE1s completo":"complete bar","comp\xE1s de 4 en lugar de 3":"bar of 4 instead of 3","con letra y voz gu\xEDa de la app":"with words and the app's guide voice","con nombre de notas, sin voz gu\xEDa":"with note names, no guide voice",corchea:"eighth note",corcheas:"eighth notes","corcheas\u2194negra":"eighth notes\u2194quarter note",cresc:"cresc",crescendo:"crescendo","cualquier figura":"any note value",dictado:"dictation",dim:"dim",diminuendo:"diminuendo",do:"C","do grave":"low C",do4:"C4","do4\u2013do5":"C4\u2013C5","do4\u2013la4":"C4\u2013A4","do4\u2013re5":"C4\u2013D5",do5:"C5",dos:"two","en cada comp\xE1s":"in every bar",entonacion:"singing in tune","escala de do":"C scale","f y ff":"f and ff",fa4:"F4",ff:"ff",ga:"ga","ho!":"ho!",la:"A","la app canta contigo":"the app sings with you","la app canta contigo (\xABsu-bien-do\xBB)":"the app sings with you (\u201Cgo-ing up\u201D)",la4:"A4",las:"las",lectura:"reading","leer-a-tempo":"read-in-tempo","libre (ta, ti-ti, taa-a)":"free (ta, ti-ti, taa-a)",matices:"dynamics","matiz equivocado":"wrong dynamic",mayor:"major",memoria:"memory","menor natural":"natural minor",mezzoforte:"mezzoforte",mf:"mf","mf y f":"mf and f",mi:"E",mi4:"E4","mi4\u2013la4":"E4\u2013A4","mi4\u2013re5":"E4\u2013D5","mi4\u2013sol4":"E4\u2013G4",natural:"natural",negra:"quarter note","negra y silencio":"quarter note and rest","negra\u2194silencio":"quarter note\u2194rest","no,":"no,",nombrar:"naming","p cerca del diapas\xF3n con poco arco; f cerca del puente con m\xE1s peso. Crescendo en una nota tenida.":"p near the fingerboard with little bow; f near the bridge with more weight. Crescendo on a long note.","p y luego pp.":"p and then pp.","p y pp":"p and pp","p<f>p":"p<f>p","palmas al micr\xF3fono o toques en pantalla":"claps into the microphone or taps on the screen",pe:"pe",pentat\u00F3nica:"pentatonic",pian\u00EDsimo:"pianissimo",pla:"pla",pp:"pp","primer tiempo con nota":"first beat with a note",pulso:"beat","pulso exacto":"exact beat",p\u00E1s:"p\xE1s",qui:"qui",re:"D",re4:"D4",re5:"D5",redonda:"whole note","redonda acortada":"whole note cut short",repetici\u00F3n:"repeat",ritmo:"rhythm",rq:"rq","rra a":"rra a",scale:"scale",si4:"B4","siglo XVIII":"18th century","silencio de comp\xE1s saltado":"skipped bar of rest",sol:"G","sol y mi":"G and E","sol-mi-la":"G-E-A",sol4:"G4","solo acompa\xF1amiento":"accompaniment only","solo acompa\xF1amiento I\u2013V":"accompaniment only I\u2013V","solo acordes (I\u2013IV\u2013V)":"chords only (I\u2013IV\u2013V)","subir en crescendo, bajar en diminuendo":"go up in crescendo, go down in diminuendo","sur,":"sur,","ta = negra \xB7 (sh) = silencio":"ta = quarter note \xB7 (sh) = rest","ta = negra \xB7 ti-ti = dos corcheas \xB7 (sh) = silencio":"ta = quarter note \xB7 ti-ti = two eighth notes \xB7 (sh) = rest","ta a em":"ta a em","ta \xB7 ti-ti \xB7 taa-a":"ta \xB7 ti-ti \xB7 taa-a","ta \xB7 ti-ti \xB7 taa-a (blanca) \xB7 sh-sh (silencio de blanca)":"ta \xB7 ti-ti \xB7 taa-a (half note) \xB7 sh-sh (half rest)","ta \xB7 ti-ti \xB7 taa-a \xB7 sh":"ta \xB7 ti-ti \xB7 taa-a \xB7 sh","ta \xB7 ti-ti \xB7 taa-a \xB7 taa-a-a-a (redonda)":"ta \xB7 ti-ti \xB7 taa-a \xB7 taa-a-a-a (whole note)","ta.":"ta.",tac:"tac",tan:"tan",tas:"tas",teoria:"theory",tercera:"third",tic:"tic",tie:"tie",to:"to","to,":"to,","todo el nivel: figuras, compases, escala de do, la menor, matices":"the whole level: note values, time signatures, C scale, A minor, dynamics","tres,":"tres,",t\u00F3nica:"tonic","va el":"va el",ver:"ver",vien:"vien",vio:"vio",vis:"vis","voz cambiada":"wrong voice",vuel:"vuel",zar:"zar","\xA1Es la de \xABCumplea\xF1os feliz\xBB!":"It's the \u201CHappy Birthday\u201D one!","\xA1e":"heave","\xA1pum!":"boom!","\xABDas Jahr\xBB (El a\xF1o), ciclo para piano (1841) \u2014 elegir un mes en modo menor":"\u201CDas Jahr\u201D (The Year), piano cycle (1841) \u2014 choose a month in a minor key","\xABEn la gruta del rey de la monta\xF1a\xBB, de \xABPeer Gynt\xBB, op. 23 (1875)":"\u201CIn the Hall of the Mountain King\u201D, from \u201CPeer Gynt\u201D, Op. 23 (1875)","\xABEstrellita\xBB de Mozart (unidad 3) ten\xEDa forma\u2026":"Mozart's \u201CTwinkle, Twinkle\u201D (unit 3) had the form\u2026","\xABGood Morning to All\xBB, en \xABSong Stories for the Kindergarten\xBB (1893)":"\u201CGood Morning to All\u201D, in \u201CSong Stories for the Kindergarten\u201D (1893)","\xABLa escalera\xBB: A (subir y bajar) + B (los semitonos).":"\u201CThe Staircase\u201D: A (going up and down) + B (the semitones).","\xABThe Celebrated Chop Waltz\xBB (1877)":"\u201CThe Celebrated Chop Waltz\u201D (1877)","\xABTodos somos do\xBB: solo se dice en voz alta la nota nueva; las dem\xE1s se piensan.":"\u201CWe are all C\u201D: only the new note is said out loud; the others are thought.","\xABUN-dos\xBB: el primer pulso lleva el acento.":"\u201CONE-two\u201D: the first beat carries the accent.","\xABf\xBB significa\u2026":"\u201Cf\u201D means\u2026","\xABp\xBB significa\u2026":"\u201Cp\u201D means\u2026","\xBD pulso":"\xBD beat","\xBFBinario o ternario?":"Duple or triple?","\xBFBinario o ternario? La app toca 8 fragmentos cortos y el alumno elige 2, 3 o 4 pulsos.":"Duple or triple? The app plays 8 short excerpts and the student chooses 2, 3 or 4 beats.","\xBFCabe una redonda en 3/4?":"Does a whole note fit in 3/4?","\xBFCon qu\xE9 figura termina cada frase?":"Which note value ends each phrase?","\xBFConoces esta melod\xEDa con otra letra?":"Do you know this melody with other words?","\xBFCu\xE1l es la relativa menor de do mayor?":"What is the relative minor of C major?","\xBFCu\xE1ntas alteraciones tiene la menor natural?":"How many sharps or flats does natural A minor have?","\xBFCu\xE1ntas blancas caben en una redonda?":"How many half notes fit in a whole note?","\xBFCu\xE1ntas corcheas caben en un pulso?":"How many eighth notes fit in one beat?","\xBFCu\xE1ntas corcheas necesitas para llenar un comp\xE1s de 2/4?":"How many eighth notes do you need to fill a bar of 2/4?","\xBFCu\xE1ntas frases tiene el fragmento?":"How many phrases does the excerpt have?","\xBFCu\xE1ntas l\xEDneas tiene el pentagrama?":"How many lines does the staff have?","\xBFCu\xE1ntas negras caben en una blanca?":"How many quarter notes fit in a half note?","\xBFCu\xE1ntas veces se repite cada nota antes de cambiar (al principio)?":"How many times is each note repeated before it changes (at the start)?","\xBFCu\xE1ntas veces se repite cada pareja de notas antes de cambiar?":"How many times is each pair of notes repeated before it changes?","\xBFCu\xE1ntas veces suena el dibujo del bajo en el fragmento?":"How many times does the bass pattern sound in the excerpt?","\xBFCu\xE1ntas voces cantan al final del fragmento?":"How many voices are singing at the end of the excerpt?","\xBFCu\xE1ntos a\xF1os ten\xEDa Euphemia cuando lo compuso?":"How old was Euphemia when she composed it?","\xBFCu\xE1ntos compases suele durar una frase?":"How many bars does a phrase usually last?","\xBFCu\xE1ntos pulsos dura una blanca?":"How many beats does a half note last?","\xBFCu\xE1ntos pulsos dura una negra?":"How many beats does a quarter note last?","\xBFCu\xE1ntos pulsos dura una redonda?":"How many beats does a whole note last?","\xBFCu\xE1ntos pulsos hay aqu\xED, contando los silencios?":"How many beats are there here, counting the rests?","\xBFCu\xE1ntos pulsos tiene el \xFAltimo comp\xE1s si en 2/4 la anacrusa dura una negra?":"How many beats does the last bar have if, in 2/4, the upbeat lasts one quarter note?","\xBFCu\xE1ntos pulsos tiene un comp\xE1s de 3/4?":"How many beats does a 3/4 bar have?","\xBFC\xF3mo empieza la m\xFAsica?":"How does the music begin?","\xBFDe cu\xE1ntos pulsos es cada comp\xE1s?":"How many beats are in each bar?","\xBFEmpieza en el primer tiempo fuerte?":"Does it start on the first strong beat?","\xBFEn qu\xE9 comp\xE1s empieza la segunda voz?":"In which bar does the second voice start?","\xBFEn qu\xE9 comp\xE1s est\xE1?":"What time signature is it in?","\xBFEn qu\xE9 l\xEDnea se enrosca la clave de sol?":"Which line does the treble clef curl around?","\xBFEn qu\xE9 nota acaba el fragmento?":"Which note does the excerpt end on?","\xBFEn qu\xE9 nota termina?":"Which note does it end on?","\xBFEn qu\xE9 \xE9poca vivi\xF3 Pachelbel?":"In which period did Pachelbel live?","\xBFEntre qu\xE9 notas hay un semitono en do mayor?":"Between which notes is there a semitone in C major?","\xBFMayor o menor?":"Major or minor?","\xBFMayor o menor? La app toca 10 frases cortas (unas en do M, otras en la m) y el alumno elige.":"Major or minor? The app plays 10 short phrases (some in C major, some in A minor) and the student chooses.","\xBFPor qu\xE9 decimos que do es la \xABnota casa\xBB en esta unidad?":"Why do we say C is the \u201Chome note\u201D in this unit?","\xBFPor qu\xE9 firm\xF3 con un nombre de hombre?":"Why did she sign with a man's name?","\xBFQui\xE9n escribi\xF3 la melod\xEDa?":"Who wrote the melody?","\xBFQu\xE9 cabe en 3/4?":"What fits in 3/4?","\xBFQu\xE9 canci\xF3n es?":"Which song is it?","\xBFQu\xE9 canci\xF3n es? La app palmea el ritmo de una canci\xF3n del nivel (sin notas) y el alumno elige entre las 8.":"Which song is it? The app claps the rhythm of a song from the level (without notes) and the student chooses from the 8.","\xBFQu\xE9 comp\xE1s usa el vals?":"What time signature does the waltz use?","\xBFQu\xE9 es una anacrusa?":"What is an upbeat?","\xBFQu\xE9 figura dura lo mismo que el silencio de negra?":"Which note value lasts the same as the quarter rest?","\xBFQu\xE9 grado es sol en la escala de do?":"Which degree is G in the C scale?","\xBFQu\xE9 hace la \xFAltima frase de la voz 1?":"What does voice 1's last phrase do?","\xBFQu\xE9 instrumento empieza solo?":"Which instrument starts on its own?","\xBFQu\xE9 le pasa al volumen?":"What happens to the volume?","\xBFQu\xE9 matiz va entre p y f?":"Which dynamic comes between p and f?","\xBFQu\xE9 nota se repite al principio de cada frase?":"Which note is repeated at the start of each phrase?","\xBFQu\xE9 pasa al final del fragmento?":"What happens at the end of the excerpt?","\xBFQu\xE9 pulso del 2/4 es m\xE1s fuerte?":"Which beat of 2/4 is stronger?","\xBFQu\xE9 signos escribir\xEDas al principio y en la repetici\xF3n?":"Which signs would you write at the start and at the repeat?","\xBFSe sabe qui\xE9n compuso esta melod\xEDa?":"Do we know who composed this melody?","\xBFSuena mayor (luminosa) o menor (misteriosa)?":"Does it sound major (bright) or minor (mysterious)?","\xBFSuenan una o dos notas a la vez?":"Do you hear one note at a time or two?","\xBFTe vienes?":"Are You Coming?","\xBFTe vienes? (Pop (balada con estribillo))":"Are You Coming? (Pop (ballad with chorus))","\xBFY a la velocidad?":"And the speed?","\xFAltimo comp\xE1s":"last bar","\u2026y la misma melod\xEDa se repite una y otra vez, cada vez m\xE1s fuerte y m\xE1s r\xE1pida, hasta que todo explota.":"\u2026and the same melody repeats over and over, louder and faster each time, until everything explodes.","\u2265 80 %":"\u2265 80 %","\u2265 90 % y ninguna competencia por debajo de 70 %":"\u2265 90 % and no skill below 70 %","\u{1D110}":"\u{1D110}","Pon la mano en el pecho: tum, tum, tum\u2026 Ese latido, siempre igual de separado, es el PULSO. La m\xFAsica tambi\xE9n tiene uno: cuando bailas o das palmas sin pensar, lo est\xE1s siguiendo.":"Put your hand on your chest: thump, thump, thump\u2026 That heartbeat, always evenly spaced, is the PULSE. Music has one too: when you dance or clap without thinking, you're following it.","La NEGRA dura exactamente un pulso. Tiene cabeza rellena y una plica (el palito). Cuatro negras = cuatro latidos: ta, ta, ta, ta. Cada negra, una palmada.":"The QUARTER NOTE lasts exactly one beat. It has a filled-in head and a stem (the little stick). Four quarter notes = four heartbeats: ta, ta, ta, ta. One clap for each quarter note.","Tambi\xE9n hay latidos en los que NO suena nada. Ese hueco se escribe con el SILENCIO DE NEGRA (parece un rayo peque\xF1o). Dura un pulso, igual que la negra: el coraz\xF3n sigue latiendo aunque t\xFA calles. En el silencio no se canta, pero se cuenta.":"There are also heartbeats where NOTHING sounds. That gap is written with the QUARTER REST (it looks like a little lightning bolt). It lasts one beat, just like the quarter note: the heart keeps beating even when you're quiet. In a rest you don't sing, but you do count.","Las notas viven en el PENTAGRAMA: 5 l\xEDneas y 4 espacios que se cuentan de abajo arriba. Una nota puede estar EN UNA L\xCDNEA (la raya la cruza por el medio) o EN UN ESPACIO (entre dos rayas). Cuanto m\xE1s arriba, m\xE1s aguda suena.":"Notes live on the STAFF: 5 lines and 4 spaces, counted from the bottom up. A note can sit ON A LINE (the line goes right through its middle) or IN A SPACE (between two lines). The higher up, the higher it sounds.","Al principio va la CLAVE DE SOL. Se enrosca en la 2.\xAA l\xEDnea y le pone nombre: la nota de esa l\xEDnea es SOL. Dos escalones m\xE1s abajo, en la 1.\xAA l\xEDnea, vive MI.":"At the start goes the TREBLE CLEF. It curls around the 2nd line and gives it a name: the note on that line is G. Two steps further down, on the 1st line, lives E.","Si andas, das un paso en cada latido: negra. Si corres, das DOS pasos en el mismo latido: son dos CORCHEAS. Se escriben unidas por una barra, como dos amigos de la mano: \xABco-rre\xBB. F\xEDjate: los pasos cambian, pero el latido no. Lo que hacen las notas encima del pulso se llama RITMO.":"When you walk, you take one step on each heartbeat: a quarter note. When you run, you take TWO steps in the same heartbeat: two EIGHTH NOTES. They're written joined by a beam, like two friends holding hands: \u201Crun-ning\u201D. Notice: the steps change, but the heartbeat doesn't. What the notes do on top of the pulse is called RHYTHM.","Los pulsos se agrupan. En el comp\xE1s de 2/4 contamos \xABUN-dos, UN-dos\xBB: el primero es m\xE1s fuerte. Arriba el 2 dice cu\xE1ntos pulsos hay; abajo el 4 dice que cada pulso es una negra. Agrupar ayuda a no perderse, como contar \xABun-dos\xBB al marchar.":"Beats come in groups. In 2/4 time we count \u201CONE-two, ONE-two\u201D: the first is stronger. The 2 on top says how many beats there are; the 4 underneath says each beat is a quarter note. Grouping helps you not to get lost, like counting \u201Cone-two\u201D when you march.","La BARRA DIVISORIA es una raya vertical que cierra cada comp\xE1s. Un comp\xE1s es el espacio entre dos barras. Al terminar la obra se pone la DOBLE BARRA FINAL (una fina y otra gruesa): \xA1fin!":"The BAR LINE is a vertical line that closes each bar. A bar is the space between two bar lines. At the end of the piece comes the FINAL DOUBLE BAR LINE (one thin and one thick): the end!","LA vive en el 2.\xBA espacio, justo encima de sol. Sol-la es un PASO: de l\xEDnea a espacio vecino, sin saltarse nada. La-mi es un SALTO: se salta notas por el camino (sol).":"A lives in the 2nd space, just above G. G-A is a STEP: from a line to the space next to it, without skipping anything. A-E is a LEAP: it skips notes on the way (G).","La BLANCA tiene la cabeza hueca y plica. Dura DOS pulsos: \xABtaa-a\xBB. Una blanca vale lo mismo que dos negras. Mientras suena, cuenta por dentro \xABuno-dos\xBB y no la sueltes antes.":"The HALF NOTE has a hollow head and a stem. It lasts TWO beats: \u201Ctaa-a\u201D. One half note is worth the same as two quarter notes. While it sounds, count \u201Cone-two\u201D inside and don't let go early.","Es un rectangulito SENTADO encima de la 3.\xAA l\xEDnea, como un sombrero puesto. Dura dos pulsos de silencio. (Pronto conocer\xE1s a su primo, que en vez de sentarse, cuelga.)":"It's a little rectangle SITTING on top of the 3rd line, like a hat on a head. It lasts two beats of silence. (Soon you'll meet its cousin, which hangs instead of sitting.)","Cuatro pulsos por comp\xE1s: \xABUN-dos-TRES-cuatro\xBB. El 1.\xBA es el m\xE1s fuerte y el 3.\xBA, medio fuerte. A veces se escribe con una C grande. Prueba: palmada fuerte en el 1, media en el 3 y suave en el 2 y el 4.":"Four beats in a bar: \u201CONE-two-THREE-four\u201D. The 1st is the strongest and the 3rd is half strong. Sometimes it is written with a big C. Try it: a loud clap on 1, a medium one on 3 and soft ones on 2 and 4.","DO grave se escribe por debajo del pentagrama, atravesado por una rayita solo para \xE9l, la L\xCDNEA ADICIONAL. Muchas melod\xEDas terminan en do: suena a \xABya he llegado a casa\xBB.":"Low C is written below the staff, crossed by a little line just for it, the LEDGER LINE. Many melodies end on C: it sounds like \u201CI'm home\u201D.","Los dos puntos pegados a una barra doble (|: y :|) son la BARRA DE REPETICI\xD3N. Al llegar a :| vuelves a |: y lo tocas otra vez. Si no hay |:, vuelves al principio.":"The two dots stuck to a double bar line (|: and :|) are the REPEAT SIGN. When you reach :| you go back to |: and play it again. If there is no |:, you go back to the beginning.","RE vive justo debajo de la 1.\xAA l\xEDnea, colgado del pentagrama. Con do-re-mi-sol-la tienes la escala PENTAT\xD3NICA: cinco notas que suenan bien juntas en cualquier orden, porque entre ellas no hay pasos cortitos (en la unidad 5 ver\xE1s por qu\xE9 es tan importante). \xA1La usan m\xFAsicas de todo el mundo!":"D lives just below the 1st line, hanging from the staff. With C-D-E-G-A you have the PENTATONIC scale: five notes that sound good together in any order, because there are no tiny steps between them (in unit 5 you'll see why that matters so much). Music all over the world uses it!","Casi todos los pelda\xF1os son TONOS (pasos grandes). Pero hay dos m\xE1s cortitos, de medio tono: los SEMITONOS. En do mayor est\xE1n entre MI-FA y entre SI-DO. \xA1Mi y fa se dan la mano; si y do, tambi\xE9n! En el piano lo ver\xE1s: entre mi y fa, y entre si y do, no hay tecla negra en medio.":"Almost all the steps are TONES (big steps). But there are two shorter ones, of half a tone: the SEMITONES. In C major they are between E-F and between B-C. E and F hold hands; so do B and C! You can see it on the piano: between E and F, and between B and C, there is no black key in the middle.","FA vive en el 1.er espacio, SI en la 3.\xAA l\xEDnea (justo en el centro) y DO AGUDO en el 3.er espacio. Ya tienes la escala completa. Desde el si hacia arriba, la plica va hacia abajo y a la izquierda.":"F lives in the 1st space, B on the 3rd line (right in the middle) and HIGH C in the 3rd space. Now you have the whole scale. From B upwards, the stem goes down, on the left.","La REDONDA no tiene plica y dura CUATRO pulsos: llena un comp\xE1s de 4/4. 1 redonda = 2 blancas = 4 negras = 8 corcheas. Su silencio CUELGA de la 4.\xAA l\xEDnea como un murci\xE9lago (el de blanca, en cambio, se sienta). Adem\xE1s, sirve para callar un comp\xE1s entero en cualquier comp\xE1s: 2/4, 3/4 o 4/4.":"The WHOLE NOTE has no stem and lasts FOUR beats: it fills a bar of 4/4. 1 whole note = 2 half notes = 4 quarter notes = 8 eighth notes. Its rest HANGS from the 4th line like a bat (the half rest, instead, sits). It is also used to stay silent for a whole bar in any time signature: 2/4, 3/4 or 4/4.","Los MATICES dicen con cu\xE1nta fuerza suena la m\xFAsica. Son palabras italianas: piano (p) = suave, forte (f) = fuerte. Con \xAB-issimo\xBB se exagera: pp pian\xEDsimo, ff fort\xEDsimo. En medio, mf (mezzoforte), medio fuerte; tambi\xE9n existe mp, mezzopiano, medio suave. Ojo: m\xE1s fuerte no es m\xE1s r\xE1pido, ni gritar. El pulso no cambia: solo la fuerza.":"DYNAMICS tell you how strongly the music sounds. They're Italian words: piano (p) = soft, forte (f) = loud. Adding \u201C-issimo\u201D exaggerates them: pp pianissimo, ff fortissimo. In between, mf (mezzoforte), medium loud; there is also mp, mezzopiano, medium soft. Careful: louder doesn't mean faster, or shouting. The pulse doesn't change: only the strength.","El CRESCENDO (<) hace que el sonido crezca poco a poco, como una ola que llega. El DIMINUENDO (>) lo hace menguar, como la ola que se va. Se dibujan como un \xABabrazo\xBB que se abre o se cierra. A veces, en lugar del dibujo, se escribe cresc. o dim.":"CRESCENDO (<) makes the sound grow little by little, like a wave coming in. DIMINUENDO (>) makes it fade, like the wave going out. They're drawn like a \u201Chug\u201D opening or closing. Sometimes, instead of the drawing, cresc. or dim. is written.","El CALDER\xD3N es un ojito con una ceja encima de una nota o de un silencio: lo alarga todo lo que quiera el director. \xA1No cuentes, mira y escucha!":"The FERMATA is a little eye with an eyebrow above a note or a rest: it holds it as long as the conductor wants. Don't count, watch and listen!","DO MAYOR y LA MENOR usan exactamente las mismas notas, sin ninguna alteraci\xF3n. Pero una descansa en do y suele sonar luminosa; la otra descansa en la y suele sonar misteriosa, nost\xE1lgica. Por eso decimos que son RELATIVAS. Truco: desde do, baja tres notas (do-si-la) y encontrar\xE1s a su hermana menor.":"C MAJOR and A MINOR use exactly the same notes, with no sharps or flats. But one rests on C and usually sounds bright; the other rests on A and usually sounds mysterious, wistful. That's why we call them RELATIVES. Trick: from C, go down three notes (C-B-A) and you'll find its minor sister.","Truco de o\xEDdo: canta la t\xF3nica y la 3.\xAA nota contando desde ella (do-re-MI; la-si-DO). Do-mi suena abierto: hay dos tonos. La-do suena m\xE1s cerrado: hay tono y medio. Esa nota, la TERCERA, decide si el modo es mayor o menor.":"Ear trick: sing the tonic and the 3rd note counting from it (C-D-E; A-B-C). C-E sounds open: there are two tones (a major third). A-C sounds more closed: there is a tone and a half (a minor third). That note, the THIRD, decides whether the mode is major or minor.","Algunas melod\xEDas arrancan con una o dos notas ANTES del primer tiempo fuerte, como quien coge impulso para saltar. Esas notas se llaman ANACRUSA. Ejemplo: \xAB\xBFTe / VIE-nes\u2026\xBB: \xABte\xBB es la anacrusa. La anacrusa se cuenta con el \xFAltimo n\xFAmero del comp\xE1s: en 4/4, \xAB4 | UN-dos-tres-cuatro\xBB.":"Some melodies start with one or two notes BEFORE the first strong beat, like taking a run-up before a jump. Those notes are called the UPBEAT (anacrusis). Example: \u201Cthe / SUN comes up\u2026\u201D: \u201Cthe\u201D is the upbeat. The upbeat is counted with the last number of the bar: in 4/4, \u201C4 | ONE-two-three-four\u201D.","Si la anacrusa dura un pulso en 4/4, al \xFAltimo comp\xE1s normalmente le falta ese pulso: tendr\xE1 solo tres. Entre los dos suman un comp\xE1s completo.":"If the upbeat lasts one beat in 4/4, the last bar is normally missing that beat: it will only have three. Together they add up to one complete bar.","Las FRASES conversan. Una frase PREGUNTA termina en el aire (en re, en sol\u2026). La frase RESPUESTA termina en casa: do (o la, si estamos en la menor). (Los m\xFAsicos dicen frase suspensiva y frase conclusiva.)":"PHRASES have conversations. A QUESTION phrase ends up in the air (on D, on G\u2026). An ANSWER phrase ends at home: C (or A, if we're in A minor). (Musicians call them a suspended phrase and a concluding phrase.)","Si una canci\xF3n tiene dos partes distintas, su forma es AB. Si la primera vuelve al final, es ABA, como un bocadillo: pan, relleno, pan. \xABEstrellita, \xBFd\xF3nde est\xE1s?\xBB es ABA: la primera melod\xEDa vuelve al final.":"If a song has two different sections, its form is AB. If the first comes back at the end, it's ABA, like a sandwich: bread, filling, bread. \u201CTwinkle, Twinkle, Little Star\u201D is ABA: the first tune comes back at the end.","Ordena los pelda\xF1os de la escala de la menor, de la t\xF3nica hacia arriba":"Put the steps of the A minor scale in order, from the tonic upwards","La-si-do-re-mi-fa-sol (y otra vez la): las mismas notas que do mayor, empezando en la.":"A-B-C-D-E-F-G (and A again): the same notes as C major, starting on A.","Traza las barras (3/4). Es una frase de 4 compases hecha de dos mitades (semifrases) de 2 compases; cada mitad acaba en una blanca":"Draw the bar lines (3/4). It is a 4-bar phrase made of two 2-bar halves (half-phrases); each half ends on a half note","Piano: suave":"Piano: soft","Forte: fuerte":"Forte: loud","Mezzoforte: medio fuerte":"Mezzoforte: medium loud","Pian\xEDsimo: muy suave":"Pianissimo: very soft","f = forte: fuerte. (p = piano, suave; mf = mezzoforte, medio fuerte.)":"f = forte: loud. (p = piano, soft; mf = mezzoforte, medium loud.)","p = piano: suave. Con dos (pp) es pian\xEDsimo, muy suave.":"p = piano: soft. With two (pp) it is pianissimo, very soft.","Fin de la obra":"End of the piece","Vuelve a |: (o al principio) y repite":"Go back to |: (or to the beginning) and repeat","Respira antes de seguir":"Breathe before going on",Ocho:"Eight","Tres negras, una blanca y una negra, seis corcheas\u2026 Pero NO cabe una redonda (4) ni dos blancas (4): se saldr\xEDan del comp\xE1s. Si lo que quieres escribir no cabe, se escribe otra figura que s\xED quepa (o se une con una ligadura al comp\xE1s siguiente: la ver\xE1s m\xE1s adelante).":"Three quarter notes, a half note and a quarter note, six eighth notes\u2026 But a whole note (4) or two half notes (4) do NOT fit: they'd spill out of the bar. If what you want to write doesn't fit, you write another note value that does (or join it to the next bar with a tie: you'll see that later).","Mayor o menor: escucha la tercera":"Major or minor: listen to the third","\xBFTe vienes a cantar? \xBFTe vienes a bailar? \xA1S\xED, vamos a cantar! \xA1S\xED, vamos a bailar! Con mis amigos suena mejor, con mis amigos suena mejor, \xA1s\xED, s\xED!":"Are you coming to sing? Are you coming to dance? Yes, let's sing! Yes, let's dance! With my friends it sounds better, with my friends it sounds better, yes, yes!","\xBFCu\xE1ntas l\xEDneas tiene el pentagrama? Escribe el n\xFAmero":"How many lines does the staff have? Type the number","Cinco l\xEDneas (y cuatro espacios), contadas de abajo arriba.":"Five lines (and four spaces), counted from the bottom up.","Toca la l\xEDnea donde se enrosca la clave de sol (la nota que vive en ella)":"Tap the line the treble clef curls around (the note that lives on it)","La clave de sol se enrosca en la 2.\xAA l\xEDnea: ah\xED vive sol.":"The treble clef curls around the 2nd line: G lives there.","Completa el comp\xE1s con algo que dure lo mismo que el silencio de negra":"Complete the bar with something that lasts as long as the quarter rest","Un pulso: una negra o el propio silencio de negra.":"One beat: a quarter note or the quarter rest itself.","Dos corcheas: \xABco-rre\xBB en un solo latido.":"Two eighth notes: \u201Crun-ning\u201D in a single heartbeat.","\xBFCu\xE1ntos pulsos suman estas figuras?":"How many beats do these notes add up to?","Dos corcheas (un pulso) + una negra (otro pulso) = dos.":"Two eighth notes (one beat) + a quarter note (another beat) = two.","Desde sol, sube un paso: toca la nota a la que llegas":"From G, go up one step: tap the note you reach","De sol (2.\xAA l\xEDnea) al 2.\xBA espacio: la.":"From G (2nd line) to the 2nd space: A.","Toca el comp\xE1s que acaba con la doble barra final":"Tap the bar that ends with the final double bar line","La doble barra (fina y gruesa) cierra el \xFAltimo comp\xE1s: \xA1fin!":"The double bar line (thin and thick) closes the last bar: the end!","\xBFCu\xE1ntos pulsos dura esta nota?":"How many beats does this note last?","La blanca dura dos pulsos: \xABtaa-a\xBB.":"The half note lasts two beats: \u201Ctaa-a\u201D.","Completa el comp\xE1s de 4/4 con lo que vale una blanca":"Complete the 4/4 bar with what a half note is worth","Faltan dos pulsos: dos negras o un silencio de blanca valen lo mismo que una blanca.":"Two beats are missing: two quarter notes or a half rest are worth the same as a half note.","\xBFCu\xE1ntos pulsos suman?":"How many beats do they add up to?","Toca el comp\xE1s que tiene un silencio de blanca":"Tap the bar that has a half rest","El silencio de blanca es el rectangulito sentado encima de la 3.\xAA l\xEDnea.":"The half rest is the little rectangle sitting on top of the 3rd line.","\xBFCu\xE1ntos pulsos tiene cada comp\xE1s de 3/4? Cu\xE9ntalos en el ejemplo":"How many beats does each 3/4 bar have? Count them in the example","Tres pulsos: \xABUN-dos-tres\xBB.":"Three beats: \u201CONE-two-three\u201D.","Uno de estos compases de 3/4 est\xE1 mal: no le cabe lo que lleva. T\xF3calo":"One of these 3/4 bars is wrong: what it holds doesn't fit. Tap it","Dos blancas son 4 pulsos: no caben en un comp\xE1s de 3.":"Two half notes are 4 beats: they don't fit in a bar of 3.","Una parte de 4 compases lleva |: al principio y :| al final. \xBFCu\xE1ntos compases suenan en total?":"A 4-bar section has |: at the start and :| at the end. How many bars are played in total?","La redonda dura cuatro pulsos: llena un comp\xE1s de 4/4.":"The whole note lasts four beats: it fills a 4/4 bar.","En do mayor, mi y fa forman un semitono. Toca la nota que va justo encima de mi":"In C major, E and F make a semitone. Tap the note just above E","Fa, en el 1.er espacio: entre mi y fa no hay tecla negra.":"F, in the 1st space: there is no black key between E and F.","Toca el grado V de la escala de do mayor":"Tap degree V of the C major scale","Do (I), re (II), mi (III), fa (IV), sol (V).":"C (I), D (II), E (III), F (IV), G (V).","Dos blancas: 2 + 2 = 4 pulsos.":"Two half notes: 2 + 2 = 4 beats.","Toca el comp\xE1s que calla entero con el silencio de redonda":"Tap the bar that is silent all the way through with the whole rest","El silencio de redonda cuelga de la 4.\xAA l\xEDnea y calla el comp\xE1s entero.":"The whole rest hangs from the 4th line and silences the whole bar.","Toca el comp\xE1s donde la nota se alarga a gusto del director":"Tap the bar where the note is held as long as the conductor wants","El calder\xF3n (ojito con ceja) est\xE1 sobre la \xFAltima nota: dura lo que quiera el director.":"The fermata (little eye with an eyebrow) is over the last note: it lasts as long as the conductor wants.","Toca la t\xF3nica de la relativa menor de do mayor (baja tres notas desde do agudo)":"Tap the tonic of the relative minor of C major (go down three notes from high C)","Do-si-la: la menor. Su t\xF3nica es la, en el 2.\xBA espacio.":"C-B-A: A minor. Its tonic is A, in the 2nd space.","En la menor, si y do forman un semitono (pelda\xF1os 2.\xBA y 3.\xBA). Toca la nota de encima de si":"In A minor, B and C make a semitone (steps 2 and 3). Tap the note above B","Do agudo, en el 3.er espacio.":"High C, in the 3rd space.","\xBFCu\xE1ntos medios pasos (semitonos) hay de la a do? Cuenta tambi\xE9n las teclas negras":"How many half steps (semitones) are there from A to C? Count the black keys too","La, la\u266F, si, do: tres medios pasos (tono y medio). Por eso la-do es una tercera menor.":"A, A\u266F, B, C: three half steps (a tone and a half). That is why A-C is a minor third.","Cuatro compases, como una oraci\xF3n de un cuento.":"Four bars, like a sentence in a story.","Toca la anacrusa: lo que va antes del primer tiempo fuerte":"Tap the upbeat: what comes before the first strong beat","La negra suelta antes de la primera barra: \xAB\xBFTe / VIE-nes\u2026\xBB.":"The single quarter note before the first bar line: \u201Cthe / SUN comes\u2026\u201D.","La anacrusa dura 1 pulso en 3/4. \xBFCu\xE1ntos pulsos tiene el \xFAltimo comp\xE1s?":"The upbeat lasts 1 beat in 3/4. How many beats does the last bar have?","Escucha y mira: toca el comp\xE1s donde termina la pregunta (en el aire)":"Listen and look: tap the bar where the question ends (up in the air)","La pregunta acaba en re (comp\xE1s 2): queda en el aire. La respuesta acaba en do.":"The question ends on D (bar 2): it stays up in the air. The answer ends on C.","Antes de que naciera Mozart":"Before Mozart was born","S\xED, de o\xEDdo":"Yes, by ear","Cantar con nombre de notas, respirando solo en las comas (final de los compases 4 y 8); en la 2.\xAA vuelta, la letra de la 2.\xAA estrofa, sin la voz gu\xEDa.":"Sing with the note names, breathing only at the commas (end of bars 4 and 8); on the 2nd time round, the words of the 2nd verse, without the guide voice.","Completa la escala: elige la nota de cada hueco, uno tras otro":"Complete the scale: choose the note for each gap, one after the other","La-si-do-re-mi-fa-sol-la. Los semitonos siguen entre si-do y mi-fa, pero ahora caen en otros pelda\xF1os (2.\xBA-3.\xBA y 5.\xBA-6.\xBA). Eso le cambia el color. Mira las dos escaleras del dibujo: mismos pelda\xF1os, distinto orden. La cantamos desde el mi grave (1.\xAA l\xEDnea) hasta el re agudo, las notas que ya sabes leer; debajo la tienes escrita entera, solo para mirarla (las notas de arriba del re las leer\xE1s m\xE1s adelante).":"A-B-C-D-E-F-G-A. The semitones are still between B-C and E-F, but now they fall on different steps (2nd-3rd and 5th-6th). That changes its colour. Look at the two staircases in the drawing: the same steps, in a different order. We sing it from low E (1st line) up to high D, the notes you can already read; below, it is written out in full, just to look at (you will read the notes above D later on).","Subo yo la escalera, \xA1do! Bajo yo la escalera, \xA1do! Mi fa son vecinas, \xA1s\xED! si do son vecinas, \xA1s\xED! \xA1Ya lo sabes! \xA1Do!":"I climb up the staircase, C! I climb down the staircase, C! E and F are neighbours, yes! B and C are neighbours, yes! Now you know! C!","\xA1Vamos, barco, al mar! \xA1Eho! \xA1Tira del tim\xF3n! \xA1Eho! Densa niebla, todo est\xE1 gris; rumbo al puerto, \xA1ya!":"Come on, ship, out to sea! Heave-ho! Pull the helm! Heave-ho! Thick fog, everything is grey; set course for the harbour, now!","Tic tac tic tac Marca el comp\xE1s Uno, dos, tres, \xA1pum! vuelta a comenzar":"Tick tock tick tock, it keeps the time. One, two, three, boom! Back to the start.","Palmas; respira en la coma, al final de la primera frase (comp\xE1s 4). Cada frase tiene 4 compases: dos semifrases de 2":"Clap; breathe at the comma, at the end of the first phrase (bar 4). Each phrase has 4 bars: two half-phrases of 2","Nombra las notas al ritmo del metr\xF3nomo con los botones; el tempo sube si aciertas.":"Name the notes with the buttons in time with the metronome; the tempo goes up when you get them right.","La escala entera, a tempo y cada vez m\xE1s deprisa.":"The whole scale, in time and faster and faster.","Las nueve notas, de do grave a re agudo, a tempo.":"The nine notes, from low C to high D, in time.","\xBFCu\xE1ntos pulsos suenan en total en estos dos compases?":"How many beats sound in total in these two bars?","Tres en cada comp\xE1s de 3/4: 3 + 3 = 6.":"Three in each 3/4 bar: 3 + 3 = 6.","De las dos notas que conoces, toca la m\xE1s grave":"Of the two notes you know, tap the lower one","Mi, en la 1.\xAA l\xEDnea: est\xE1 m\xE1s abajo que sol, as\xED que suena m\xE1s grave.":"E, on the 1st line: it is lower down than G, so it sounds lower.","Fresas \xA1ya! Rojas \xA1ya! Dulces, frescas, buenas, grandes, Venga, \xA1ven! venga, \xA1ven! \xA1Lleva todas! \xA1Ven! \xA1Ya!":"Strawberries, now! Red ones, now! Sweet, fresh, good, big ones. Come on, come! Come on, come! Take them all! Come! Now!","Pipip\xED, \xA1bip, bip! dame la luz, Pipip\xED, \xA1bip, bop! mueve el pie, \xA1clac! Gira la cabeza, gira sin parar Mueve, mueve, y se par\xF3, \xA1clic!":"Beep-beep, bip, bip! Give me light. Beep-beep, bip, bop! Move your foot, clack! Turn your head, keep on turning. Move, move, and it stopped, click!","Luce el faro sobre el mar, \xA1brilla, brilla! \xA1luz! Barcos que vuelven, s\xED, llegan ya Duerme, duerme, mar":"The lighthouse shines over the sea, shine, shine! Light! Boats coming back, yes, they are arriving now. Sleep, sleep, sea.","Tic tac tic tac Baila el reloj Vamos a girar vuelta y vuelta, \xA1ya!":"Tick tock tick tock, the clock is dancing. Let's turn around, round and round, done!","Canta la brisa del mar, canci\xF3n de paz; Mar que contesta: \xA1s\xED! \xA1Fuerte, fuerte! \xA1Bum! Olas que suenan m\xE1s, m\xE1s y m\xE1s y \xA1m\xE1s! Ola que se va, se va, se va.":"The sea breeze sings a song of peace; the sea answers: yes! Loud, loud! Boom! Waves that sound more, more and more and more! A wave that goes away, away, away.","Sopla viento sur. \xA1Eho! Lleva el barco al sol. \xA1Eho! Cantan las gaviotas: \xA1mira, tierra, tierra! \xA1S\xED!":"The south wind blows. Heave-ho! It takes the ship to the sun. Heave-ho! The seagulls sing: look, land, land! Yes!","Cantar de o\xEDdo, con los nombres (a\xFAn no se leen todas estas notas)":"Sing by ear, with the names (not all these notes can be read yet)","La m\xFAsica se organiza en FRASES, como las oraciones de un cuento. Suelen durar 4 compases, y cada una tiene dos mitades de 2 compases: las SEMIFRASES. Al final de cada frase se respira; a veces se marca con una coma (\u2019), la RESPIRACI\xD3N, sobre el pentagrama. En el ejemplo, dos frases y la coma entre ellas.":"Music is organised in PHRASES, like the sentences in a story. They usually last 4 bars, and each one has two halves of 2 bars: the HALF-PHRASES. At the end of each phrase you breathe; sometimes it is marked with a comma (\u2019), the BREATH MARK, above the staff. In the example, two phrases and the comma between them.","Faltan los grados III y VI de la escala.":"Degrees III and VI of the scale are missing."};var n={"\xA19 notas, de do grave a re agudo!":"9 notes, from low C to high D!","\xA1en casa!":"home!","\xBFTe":"the","\xBFun rayo?":"a lightning bolt?","\u2026y esa l\xEDnea se llama SOL":"\u2026so that line is called G (sol)","\u2019 = respira aqu\xED, como la coma de un cuento":"\u2019 = breathe here, like a comma in a story","(colgado de la 1.\xAA l\xEDnea)":"(hanging under line 1)","1 latido":"1 beat","1 latido sin sonar":"1 silent beat","1 redonda":"1 whole note","1 vuelta = 1 comp\xE1s":"1 turn = 1 bar","1.\xAA l\xEDnea":"line 1","1.\xAA vez":"1st time","1.er tiempo fuerte":"first strong beat","2 blancas":"2 half notes","2 pulsos en cada comp\xE1s":"2 beats in every bar","2.\xAA l\xEDnea":"line 2","2.\xAA vez\u2026 y sigue":"2nd time\u2026 and go on","2.\xBA espacio":"space 2","3 + 1 = 4: \xA1un comp\xE1s completo!":"3 + 1 = 4: one whole bar!","3 medios pasos (tono y \xBD)":"3 half steps (1\xBD tones)","3.\xAA l\xEDnea":"line 3","4 compases":"4 bars","4 medios pasos (2 tonos)":"4 half steps (2 tones)","4 negras":"4 quarter notes","4 pulsos de negra":"4 quarter note beats","8 corcheas":"8 eighth notes","A \xB7 pan":"A \xB7 bread","A la izquierda, forma AB: un bloque A y un bloque B distintos. A la derecha, forma ABA como un bocadillo: pan A arriba, relleno B en medio y pan A abajo. Debajo, la l\xEDnea del tiempo A, B, A.":"Left: AB form, two different blocks A and B. Right: ABA form like a sandwich: bread A on top, filling B in the middle and bread A at the bottom. Below, the timeline A, B, A.",agudo:"higher","al empezar":"at the start","al terminar":"at the end",anacrusa:"upbeat","anacrusa: 1":"upbeat: 1",Andar:"Walk","\xC1rbol de las figuras sobre cuatro latidos: una redonda dura los cuatro; dos blancas, dos cada una; cuatro negras, uno cada una; ocho corcheas, dos por latido. Debajo, los silencios: el de redonda cuelga de la 4.\xAA l\xEDnea y el de blanca se sienta en la 3.\xAA.":"Note-value tree over four beats: one whole note lasts all four; two half notes, two each; four quarter notes, one each; eight eighth notes, two per beat. Below, the rests: the whole note rest hangs from line 4 and the half note rest sits on line 3.","Arriba, el regulador de crescendo, dos l\xEDneas que se abren hacia la derecha, con una ola que va creciendo. Abajo, el de diminuendo, que se cierra, con una ola que se va haciendo peque\xF1a.":"Top: the crescendo hairpin, two lines opening to the right, with a wave that grows. Bottom: the diminuendo hairpin, closing, with a wave that shrinks.","Arriba, la anacrusa del principio (una casilla de un pulso) y el \xFAltimo comp\xE1s (tres casillas). Abajo, las dos piezas encajan como un puzle: 3 + 1 = 4, un comp\xE1s completo.":"Top: the upbeat at the start (one one-beat box) and the last bar (three boxes). Bottom: the two pieces fit together like a puzzle: 3 + 1 = 4, one whole bar.","B \xB7 relleno":"B \xB7 filling","barra divisoria":"bar line","blanca + negra":"half + quarter","cabeza hueca":"hollow head","cabeza rellena":"filled-in head","cada pulso vale una negra":"each beat is a quarter note",ceja:"eyebrow","Cinco escalones de volumen de menor a mayor: pp (pian\xEDsimo, muy suave), p (piano, suave), mf (mezzoforte, medio fuerte), f (forte, fuerte) y ff (fort\xEDsimo, muy fuerte). Sobre cada uno, un c\xEDrculo de sonido cada vez m\xE1s grande.":"Five volume steps from smallest to largest: pp (pianissimo, very soft), p (piano, soft), mf (mezzo forte, medium loud), f (forte, loud) and ff (fortissimo, very loud). Above each, a sound circle that gets bigger.","como la ola que llega":"like a wave rolling in","como la ola que se va":"like a wave rolling out","como un sombrero":"like a hat","comp\xE1s 1":"bar 1","comp\xE1s 2":"bar 2","con calder\xF3n: \xA1m\xE1s larga!":"with a fermata: longer!",corcheas:"eighths",Correr:"Run","crescendo (cresc.): crece":"crescendo (cresc.): grows","cua-tro":"four","Cuatro corazones en fila sobre una flecha del tiempo, separados siempre por la misma distancia; debajo de cada uno, \xABtum\xBB. El pulso es un latido regular.":"Four hearts in a row above a time arrow, always the same distance apart, each labelled \u201Ctum\u201D. The beat is a steady heartbeat.","cuelga de la 4.\xAA":"hangs from line 4","diminuendo (dim.): mengua":"diminuendo (dim.): fades",distintas:"parts","do \u2192 si \u2192 la: 3 notas m\xE1s abajo":"C \u2192 B \u2192 A: 3 notes down","Do mayor":"C major","Do mayor: \xBD entre 3-4 y 7-8":"C major: \xBD at 3-4 and 7-8","do: 3.er espacio":"C: space 3","doble barra final: \xA1fin!":"final double bar: the end!",dos:"2","dos blancas":"two half notes","Dos bocadillos de di\xE1logo con el dibujo de la melod\xEDa. La pregunta sube mi, fa, sol, la y acaba en re, en el aire, con un signo de interrogaci\xF3n. La respuesta hace mi, fa, sol, re y acaba en do, junto a una casita y un punto final.":"Two speech bubbles with the shape of the melody. The question goes up E, F, G, A and ends on D, up in the air, with a question mark. The answer goes E, F, G, D and ends on C, next to a little house and a full stop.","Dos escaleras de ocho pelda\xF1os. Do mayor tiene los pelda\xF1os cortos (\xBD) entre el 3.\xBA y 4.\xBA y entre el 7.\xBA y 8.\xBA. La menor, con las mismas notas, los tiene entre el 2.\xBA y 3.\xBA y entre el 5.\xBA y 6.\xBA.":"Two eight-step staircases. C major has its short steps (\xBD) between steps 3-4 and 7-8. A minor, with the same notes, has them between steps 2-3 and 5-6.","Dos filas sobre cuatro latidos. Andar: una huella por latido y una negra (\xABta\xBB). Correr: dos huellas por latido y dos corcheas unidas por una barra (\xABco-rre\xBB). Los latidos de abajo no cambian.":"Two rows over four beats. Walking: one footprint per beat and a quarter note (\u201Cta\u201D). Running: two footprints per beat and two beamed eighth notes (\u201Cco-rre\u201D). The beats below stay the same.","Dos frases de cuatro compases cada una, como dos partes de una oraci\xF3n: \xABHab\xEDa una vez un gato, que cantaba al despertar\xBB. Un arco cubre cada frase y al final de cada una hay una coma de respiraci\xF3n con un soplo de aire.":"Two phrases of four bars each, like two parts of a sentence: \u201COnce upon a time a cat, sang as soon as it woke\u201D. An arc covers each phrase and at the end of each there is a breath mark with a puff of air.","dos negras juntas":"two quarter notes together","dos partes":"two different","Dos trozos de teclado. De do a mi hay cuatro saltitos de medio tono: tercera mayor, suena abierta. De la a do hay tres: tercera menor, suena cerrada. La tercera nota desde la t\xF3nica decide si el modo es mayor o menor.":"Two pieces of keyboard. From C to E there are four half-step hops: a major third, sounds open. From A to C there are three: a minor third, sounds closed. The third note above the tonic decides whether the mode is major or minor.",dura:"lasts","El calder\xF3n dibujado grande sobre una negra: un arco (la ceja) y un punto (el ojo). Al lado, una negra normal dura un latido; con calder\xF3n, su barra de duraci\xF3n se alarga m\xE1s all\xE1 de los latidos, hasta que lo diga el director.":"A large fermata over a quarter note: an arc (the eyebrow) and a dot (the eye). Beside it, a normal quarter note lasts one beat; with a fermata, its duration bar stretches beyond the beats, until the conductor says so.","El comp\xE1s 2/4: el 2 de arriba indica 2 pulsos por comp\xE1s y el 4 de abajo que cada pulso es una negra. Debajo, pulsos agrupados de dos en dos, uno grande y fuerte (\xABUN\xBB) y uno peque\xF1o (\xABdos\xBB), separados por barras.":"The 2/4 time signature: the top 2 means 2 beats per bar and the bottom 4 means each beat is a quarter note. Below, beats grouped in twos, one big and strong (\u201CONE\u201D) and one small (\u201Ctwo\u201D), separated by bar lines.","El comp\xE1s 4/4, que tambi\xE9n se escribe con una C. Una pelota bota en los cuatro pulsos: en el 1 (\xABUN\xBB) cae m\xE1s fuerte, en el 3 (\xABTRES\xBB) medio fuerte, y en el 2 y el 4 suave.":"The 4/4 time signature, also written as a C. A ball bounces on the four beats: it lands hardest on 1 (\u201CONE\u201D), medium on 3 (\u201CTHREE\u201D) and softly on 2 and 4.","El silencio de negra, en zigzag como un rayo. Debajo, negra, silencio, negra, silencio sobre cuatro corazones: en los silencios la barra de duraci\xF3n es punteada y no se canta, pero el coraz\xF3n sigue latiendo.":"The quarter note rest, zigzag like a lightning bolt. Below, quarter note, rest, quarter note, rest over four hearts: under the rests the duration bar is dotted and nothing is sung, but the heart keeps beating.","en cada comp\xE1s.":"in every bar.","en el tiempo: A \u2192 B \u2192 A":"over time: A \u2192 B \u2192 A","en espacio:":"in a space:","en l\xEDnea:":"on a line:","entre dos rayas":"between lines","Escuchar andar: negras":"Listen to walking: quarter notes","Escuchar correr: corcheas":"Listen to running: eighth notes","Escuchar do mayor":"Listen to C major","Escuchar el ejemplo":"Listen to the example","Escuchar el pulso":"Listen to the beat","Escuchar fuerte-d\xE9bil en 2/4":"Listen to strong-weak in 2/4","Escuchar la escala":"Listen to the scale","Escuchar la menor":"Listen to A minor","Escuchar la pregunta":"Listen to the question","Escuchar la respuesta":"Listen to the answer","Escuchar las nueve notas":"Listen to the nine notes","Escuchar los dos compases":"Listen to the two bars","Escuchar una nota con calder\xF3n":"Listen to a note with a fermata",espacios:"spaces","fa: 1.er espacio":"F: space 1",fort\u00EDsimo:"fortissimo","frase 1":"phrase 1","frase 2":"phrase 2",fuerte:"loud",grado:"degree","grados: I, II, III\u2026":"degrees: I, II, III\u2026",grave:"lower","Hab\xEDa una vez un gato":"Once upon a time a cat","La 3.\xAA nota desde la t\xF3nica decide el modo":"The 3rd note from the tonic decides the mode","la A vuelve al final":"A comes back at the end","la caja de un comp\xE1s de 3/4":"the box of one 3/4 bar","La menor":"A minor","La menor: \xBD entre 2-3 y 5-6":"A minor: \xBD at 2-3 and 5-6","la raya la cruza":"line through it","Las mismas notas: solo teclas blancas, sin \u266F ni \u266D":"Same notes: white keys only, no \u266F or \u266D",latido:"beat","l\xEDnea adicional:":"ledger line:",l\u00EDneas:"lines",luminosa:"bright","MAYOR: abierta":"MAJOR: open",medio:"medium","medio fuerte":"medium loud","menor: cerrada":"minor: closed",mezzoforte:"mezzo forte",misteriosa:"mysterious","muy fuerte":"very loud","muy suave":"very soft","negra: 1 latido":"quarter note: 1 beat",negras:"quarters","nes\u2026":"comes\u2026","no cuentes: mira al director":"don't count: watch the conductor","nota en espacio":"note in a space","nota en l\xEDnea":"note on a line",ojo:"eye","paso \u2191":"step \u2191","Pentagrama con barra de inicio de repetici\xF3n y barra de final de repetici\xF3n, cada una con dos puntos. Flechas: primera pasada hacia la derecha, vuelta hacia atr\xE1s hasta los puntos del principio y segunda pasada. Si no hay barra de inicio, se vuelve al principio.":"A staff with a start-repeat and an end-repeat bar, each with two dots. Arrows: first time through to the right, back to the start dots, and second time through. If there is no start sign, go back to the beginning.","Pentagrama con dos compases coloreados como dos habitaciones. La barra divisoria los separa y la doble barra final, una fina y otra gruesa, marca el fin.":"A staff with two bars shaded like two rooms. The bar line separates them and the final double bar, one thin and one thick line, marks the end.","Pentagrama con la clave de sol; su espiral se enrosca en la 2.\xAA l\xEDnea, resaltada. En esa l\xEDnea est\xE1 la nota sol y en la 1.\xAA l\xEDnea, la nota mi.":"A staff with the treble clef; its curl wraps around the highlighted second line. The note G (sol) sits on that line and E (mi) on the first line.","Pentagrama con la escala de do. Las notas nuevas est\xE1n resaltadas: fa en el 1.er espacio, si en la 3.\xAA l\xEDnea (la del centro) y do agudo en el 3.er espacio.":"A staff with the C scale. The new notes are highlighted: F in space 1, B on line 3 (the middle one) and high C in space 3.","Pentagrama con la melod\xEDa mi, sol, mi, do y un do largo al final. El do grave est\xE1 debajo del pentagrama, atravesado por una l\xEDnea adicional resaltada. Junto al \xFAltimo do, una casita: \xAB\xA1en casa!\xBB.":"A staff with the melody E, G, E, C and a long C at the end. Low C sits below the staff, crossed by a highlighted ledger line. Next to the last C, a little house: \u201Chome!\u201D.","Pentagrama con las 5 l\xEDneas numeradas de abajo arriba a la izquierda y los 4 espacios numerados a la derecha. Una nota en la 2.\xAA l\xEDnea (la raya la cruza) y otra en el 3.er espacio (entre dos rayas). Una flecha indica que hacia arriba es m\xE1s agudo.":"A staff with its 5 lines numbered from the bottom up on the left and its 4 spaces numbered on the right. One note on line 2 (the line goes through it) and one in space 3 (between two lines). An arrow shows that higher up means higher pitch.","Pentagrama con nueve notas que suben de do grave a re agudo, numeradas del 1 al 9. Re agudo, en la 4.\xAA l\xEDnea resaltada.":"A staff with nine notes rising from low C to high D, numbered 1 to 9. High D sits on the highlighted fourth line.","Pentagrama con sol en la 2.\xAA l\xEDnea, la en el 2.\xBA espacio (resaltada) y mi en la 1.\xAA l\xEDnea. Una flecha corta sube de sol a la: un paso. Una flecha larga baja de la a mi: un salto.":"A staff with G (sol) on line 2, A (la) in space 2 (highlighted) and E (mi) on line 1. A short arrow goes up from G to A: a step. A long arrow goes down from A to E: a leap.","Pentagrama en 4/4. Antes de la primera barra hay una sola nota, resaltada en una zona punteada: la anacrusa (cuenta 4). Una flecha salta por encima de la barra hasta el primer tiempo fuerte (1). Debajo, la letra: \xAB\xBFTe | VIE-nes\u2026\xBB.":"A staff in 4/4. Before the first bar line there is a single highlighted note in a dotted zone: the upbeat (counted 4). An arrow jumps over the bar line to the first strong beat (1). Below, the words: \u201Cthe | SUN comes\u2026\u201D.",pian\u00EDsimo:"pianissimo",plica:"stem","plica (el palito)":"stem (the stick)","Pregunta: termina en el aire":"Question: ends up in the air","que cantaba al despertar":"sang as soon as it woke","re: 4.\xAA l\xEDnea":"D: line 4","Respuesta: termina en casa":"Answer: ends at home","salto \u2193":"leap \u2193","se enrosca en la 2.\xAA l\xEDnea\u2026":"it curls around line 2\u2026","se sienta en la 3.\xAA":"sits on line 3","seis corcheas":"six eighth notes","sentado encima,":"sitting on top,","si: 3.\xAA l\xEDnea (centro)":"B: line 3 (middle)","siempre a la misma distancia: eso es el pulso":"always the same distance apart: that is the beat","silencio de blanca:":"half rest:","silencio de redonda:":"whole rest:","Sin |: vuelve al principio":"No |: means from the start","Sin tecla negra en medio = medio tono":"No black key in between = half step",suave:"soft","T = tono (paso grande) \xB7 \xBD = semitono (paso corto)":"T = tone (big step) \xB7 \xBD = semitone (short step)","Tambi\xE9n se escribe C":"Also written as C","Teclado de do a do. Entre teclas blancas vecinas hay un tono (T) salvo entre mi-fa y si-do, resaltadas, que es medio tono (\xBD) porque no hay tecla negra en medio. Debajo, una escalera con pelda\xF1os altos (tonos) y dos pelda\xF1os bajos (semitonos) en mi-fa y si-do.":"A keyboard from C to C. Between neighbouring white keys there is a whole step (T) except E-F and B-C, highlighted, which are half steps (\xBD) because there is no black key between them. Below, a staircase with tall steps (tones) and two short steps (semitones) at E-F and B-C.","Teclado de do a si con cinco teclas resaltadas y numeradas: do, re, mi, sol y la; fa y si quedan tachadas. Debajo, las mismas cinco notas en el pentagrama; re cuelga justo debajo de la 1.\xAA l\xEDnea.":"A keyboard from C to B with five highlighted, numbered keys: C, D, E, G and A; F and B are crossed out. Below, the same five notes on the staff; D hangs just under line 1.",tiempo:"time","Toca el dibujo para o\xEDrlo":"Tap the drawing to hear it",tres:"3",TRES:"THREE","tres negras":"three quarters","\xFAltimo comp\xE1s: 3":"last bar: 3",UN:"1","Un c\xEDrculo dividido en tres porciones: \xABUN\xBB (resaltada), \xABdos\xBB y \xABtres\xBB; una vuelta completa es un comp\xE1s de 3/4, como un paso de vals. Al lado, un comp\xE1s 3/4 con tres negras y otro con blanca y negra.":"A circle split into three slices: \u201CONE\u201D (highlighted), \u201Ctwo\u201D and \u201Cthree\u201D; one full turn is one 3/4 bar, like a waltz step. Beside it, a 3/4 bar with three quarter notes and another with a half note and a quarter note.","Un teclado de do a do solo con teclas blancas. Sobre do, una casita con un sol: do mayor, luminosa. Sobre la, una casita con una luna: la menor, misteriosa. Una flecha baja de do a la: tres notas m\xE1s abajo (do, si, la).":"A keyboard from C to C using only white keys. Above C, a little house with a sun: C major, bright. Above A, a little house with a moon: A minor, mysterious. An arrow goes down from C to A: three notes lower (C, B, A).","Un trozo de pentagrama con la 3.\xAA l\xEDnea resaltada y el silencio de blanca sentado encima, como un sombrero. Debajo: negra, silencio de blanca de dos latidos y negra.":"A piece of staff with line 3 highlighted and the half note rest sitting on top of it, like a hat. Below: quarter note, two-beat half note rest, quarter note.","Una blanca grande: cabeza hueca y plica. Una blanca vale lo mismo que dos negras juntas. Debajo, una blanca cuya barra de duraci\xF3n ocupa dos latidos (\xABtaa-a\xBB) seguida de dos negras de un latido.":"A large half note: hollow head and stem. One half note equals two quarter notes together. Below, a half note whose duration bar spans two beats (\u201Ctaa-a\u201D) followed by two one-beat quarter notes.","Una caja del ancho de tres latidos. Caben tres negras, blanca y negra, o seis corcheas (\u2713). Una redonda y dos blancas se salen por la derecha, en rojo (\u2715).":"A box three beats wide. Three quarter notes, a half note and a quarter note, or six eighth notes fit (\u2713). A whole note and two half notes stick out on the right in red (\u2715).","Una escalera de ocho pelda\xF1os que sube de izquierda a derecha: do, re, mi, fa, sol, la, si, do, cada uno con su grado en n\xFAmeros romanos (I a VIII). El primer y el \xFAltimo do est\xE1n resaltados.":"An eight-step staircase rising left to right: C, D, E, F, G, A, B, C, each with its degree in Roman numerals (I to VIII). The first and last C are highlighted.","Una negra grande con sus partes: cabeza rellena y plica. Dura un latido. Debajo, cuatro negras sobre cuatro corazones, cada una con una barra de duraci\xF3n del ancho de un latido y la s\xEDlaba \xABta\xBB.":"A large quarter note with its parts: filled-in head and stem. It lasts one beat. Below, four quarter notes over four hearts, each with a one-beat duration bar and the syllable \u201Cta\u201D.","una rayita solo para esa nota":"a little line just for that note","una redonda":"a whole note","VIE-":"SUN","vuelve a los puntos":"go back to the dots"};var u={...a,...o,...e,...n,"Primeros sonidos":"First sounds","Las cuatro cuerdas al aire":"The four open strings","Conoce tu viol\xEDn":"Get to know your violin","Cuatro cuerdas":"Four strings","De grave a aguda: Sol, Re, La y Mi. Mirando el viol\xEDn desde tu barbilla, la cuerda Sol queda a la izquierda y la Mi a la derecha.":"From low to high: G, D, A and E. Looking at the violin from your chin, the G string is on the left and the E string on the right.","El arco":"The bow","Pulgar doblado entre la nuez y el cuero, dedos relajados y me\xF1ique curvo sobre la vara. Toca a medio camino entre el puente y el diapas\xF3n.":"Thumb bent between the frog and the grip, relaxed fingers and a curved little finger on the stick. Play halfway between the bridge and the fingerboard.","C\xF3mo te escucha la app":"How the app listens to you","Deja el m\xF3vil a medio metro, en un sitio silencioso. Haz notas largas: cuando suene afinada, la nota se pondr\xE1 verde y pasar\xE1s a la siguiente.":"Put the phone about half a metre away, somewhere quiet. Play long notes: when a note is in tune it turns green and you move on to the next.","Tu instrumento y la afinaci\xF3n":"Your instrument and tuning","Afinas por quintas":"Tuning in fifths","Sol, Re, La y Mi: cada cuerda est\xE1 una quinta por encima de la anterior. Se afina primero el La (440 Hz, o 442 en muchas orquestas) y las dem\xE1s compar\xE1ndolas con ella.":"G, D, A and E: each string is a fifth above the one before. Tune the A first (440 Hz, or 442 in many orchestras) and then the others against it.","Clavijas y tensores":"Pegs and fine tuners","Las clavijas hacen cambios grandes; los tensores finos del cordal, los peque\xF1os. Las cuerdas se destensan con el calor y la humedad: afina cada vez que abras el estuche.":"The pegs make big changes; the fine tuners on the tailpiece, small ones. Strings go slack with heat and humidity: tune every time you open the case.","Instrumento en Do":"An instrument in C","El viol\xEDn suena exactamente lo que lees. La banda afina al Si\u266D de concierto: es la nota natural de la mayor\xEDa de sus instrumentos. La orquesta afina al La (todas las cuerdas tienen un La y el oboe lo da con un sonido estable). Algunas bandas usan La = 442 Hz en vez de 440.":"The violin sounds exactly what you read. A band tunes to concert B\u266D: it is the natural note of most of its instruments. An orchestra tunes to A (every string instrument has an A and the oboe gives it with a steady sound). Some bands use A = 442 Hz instead of 440.","\xBFA qu\xE9 nota afina la orquesta?":"Which note does the orchestra tune to?","Al La: todas las cuerdas tienen un La y el oboe lo da con un sonido estable.":"To A: every string instrument has an A and the oboe gives it with a steady sound.","Las notas tienen dos nombres":"Notes have two names","Do, Re, Mi\u2026 o C, D, E\u2026":"Do, Re, Mi\u2026 or C, D, E\u2026","En Espa\xF1a decimos Do, Re, Mi, Fa, Sol, La, Si. En ingl\xE9s usan letras: C, D, E, F, G, A, B. El n\xFAmero (C4, A4) dice la octava: el Do central es C4.":"In Spain we say Do, Re, Mi, Fa, Sol, La, Si. In English letters are used: C, D, E, F, G, A, B. The number (C4, A4) gives the octave: middle C is C4.","Siete nombres, doce sonidos":"Seven names, twelve sounds","Entre casi todas las notas hay una tecla negra (un semitono). Entre Mi y Fa y entre Si y Do no: ah\xED ya est\xE1n a un semitono.":"Between almost every pair of notes there is a black key (a semitone). Between E and F and between B and C there isn't: they are already a semitone apart.","\xBFC\xF3mo se llama el La en notaci\xF3n americana?":"What is La called in letter notation?","A. C es Do, D Re, E Mi, F Fa, G Sol, A La y B Si.":"A. Do is C, Re D, Mi E, Fa F, Sol G, La A and Si B.","Arcos largos":"Long bows","Calentamiento opcional":"Optional warm-up","Las dos cuerdas agudas":"The two high strings","Las dos cuerdas graves":"The two low strings","Cruzar cuerdas":"Crossing strings","Sol, Re, La, Mi y vuelta":"G, D, A, E and back","Primer ritmo":"First rhythm","Negra con puntillo":"Dotted quarter note","El puntillo alarga la nota la mitad: una negra con puntillo dura un pulso y medio y suele ir seguida de una corchea. Lo ver\xE1s en el Himno de la alegr\xEDa.":"The dot makes a note half as long again: a dotted quarter lasts one and a half beats and is usually followed by an eighth note. You will see it in the Ode to Joy.","Dos notas por pulso":"Two notes per beat","Las corcheas duran medio pulso y van de dos en dos: cuenta \xABun-y, dos-y\xBB y toca una en cada s\xEDlaba. Martinillo las usa al final.":'Eighth notes last half a beat and come in pairs: count "one-and, two-and" and play one on each syllable. Fr\xE8re Jacques uses them at the end.',"Fa natural en la cuerda Re":"F natural on the D string","En la cuerda Re, el dedo 2 bajo (pegado al 1) da Fa natural. Lo necesitas para la escala de Do mayor.":"On the D string, low 2nd finger (next to the 1st) gives F natural. You need it for the C major scale.","Sol\u266F en la cuerda Re":"G\u266F on the D string","El dedo 3 alto (pegado al 4) en la cuerda Re da Sol\u266F. En La menor aparece para volver a La.":"High 3rd finger (next to the 4th) on the D string gives G\u266F. In A minor it appears to lead back to A.","Negras y blancas a tempo":"Quarter and half notes in time","Dedos en La":"Fingers on A","Primer, segundo y tercer dedo":"First, second and third finger","Tus primeros dedos":"Your first fingers","Cuerda La":"A string","Sobre la cuerda La: el dedo 1 da Si, el 2 (alto, pegado al 3) da Do\u266F y el 3 da Re. Apoya la yema y mant\xE9n el codo debajo del viol\xEDn.":"On the A string: finger 1 gives B, finger 2 (high, next to 3) gives C\u266F and finger 3 gives D. Use the fingertip and keep your elbow under the violin.",Afinaci\u00F3n:"Tuning","Si una nota sale baja, acerca el dedo al puente; si sale alta, ac\xE9rcalo a la voluta. El indicador te dir\xE1 hacia d\xF3nde moverte.":"If a note comes out flat, move your finger towards the bridge; if it is sharp, towards the scroll. The meter shows you which way to move.","Pulso y figuras":"Pulse and note values","El pulso":"The pulse","Es el latido regular de la m\xFAsica, lo que marcas con el pie. Las figuras dicen cu\xE1ntos pulsos dura cada nota.":"It is the steady heartbeat of the music, what you tap with your foot. Note values tell you how many beats each note lasts.","Cu\xE1nto dura cada una":"How long each one lasts","Redonda: 4 pulsos. Blanca: 2. Negra: 1. Corchea: medio. Cada silencio tiene su figura equivalente.":"Whole note: 4 beats. Half note: 2. Quarter note: 1. Eighth note: half a beat. Every rest has a matching value.","\xBFCu\xE1ntas negras caben en una blanca?":"How many quarter notes fit in a half note?","Dos: la blanca dura 2 pulsos y la negra 1.":"Two: the half note lasts 2 beats and the quarter note 1.","Patr\xF3n 0-1-2-3":"Pattern 0-1-2-3","Subir y bajar":"Up and down",Saltos:"Leaps","Combinaciones en la cuerda La":"Combinations on the A string","Primera melod\xEDa":"First melody","Solo cuerda La, a tempo":"Only the A string, in time","Cuerda Re":"D string","La cuerda Re":"The D string","Mismos dedos, otra cuerda":"Same fingers, another string","Sobre la cuerda Re los dedos 1, 2 alto y 3 dan Mi, Fa\u266F y Sol. Con la cuerda La ya tienes la escala de Re mayor.":"On the D string fingers 1, high 2 and 3 give E, F\u266F and G. Together with the A string you have the D major scale.","El comp\xE1s":"The bar","Grupos de pulsos":"Groups of beats","El comp\xE1s agrupa los pulsos. El n\xFAmero de arriba dice cu\xE1ntos hay en cada comp\xE1s: 4/4 (cuatro), 3/4 (tres, como un vals), 2/4 (dos, como un pasodoble).":"The bar groups the beats. The top number says how many there are in each bar: 4/4 (four), 3/4 (three, like a waltz), 2/4 (two, like a march).","El primer tiempo manda":"The first beat rules","El primer pulso de cada comp\xE1s es el m\xE1s fuerte. Contar \xABUNO-dos-tres\xBB te ayuda a no perderte.":"The first beat of each bar is the strongest. Counting \u201CONE-two-three\u201D helps you not to get lost.","Un vals va en\u2026":"A waltz is in\u2026","En 3/4: tres pulsos por comp\xE1s, el primero fuerte.":"In 3/4: three beats per bar, the first one strong.","Cruces Re-La":"D-A crossings","Dedos en la cuerda Re":"Fingers on the D string","Una octava":"One octave","Tu primera canci\xF3n":"Your first song","Beethoven en Re mayor":"Beethoven in D major","Cuerda Mi":"E string","La cuerda Mi":"The E string","La cuerda m\xE1s aguda":"The highest string","Dedo 1 Fa\u266F, dedo 2 alto Sol\u266F y dedo 3 La. Con la cuerda La forman la escala de La mayor.":"Finger 1 F\u266F, high finger 2 G\u266F and finger 3 A. With the A string they make the A major scale.","Sostenidos y bemoles":"Sharps and flats","Medio tono arriba o abajo":"Half a step up or down","El sostenido (\u266F) sube la nota medio tono; el bemol (\u266D) la baja medio tono; el becuadro (\u266E) la devuelve a natural.":"The sharp (\u266F) raises a note by a semitone; the flat (\u266D) lowers it by a semitone; the natural (\u266E) returns it to natural.","Dos nombres para un sonido":"Two names for one sound","Do\u266F y Re\u266D suenan igual en el piano: se escribe uno u otro seg\xFAn la tonalidad.":"C\u266F and D\u266D sound the same on the piano: you write one or the other depending on the key.","Escucha: \xBFla segunda nota est\xE1 m\xE1s alta o m\xE1s baja?":"Listen: is the second note higher or lower?","M\xE1s alta: es un sostenido":"Higher: it is a sharp","M\xE1s baja: es un bemol":"Lower: it is a flat","Es la misma nota":"It is the same note","Sube medio tono: Fa y luego Fa\u266F.":"It goes up a semitone: F and then F\u266F.","Dedos en la cuerda Mi":"Fingers on the E string","La canci\xF3n de siempre":"The classic song","Cuerda Sol":"G string","La cuerda Sol":"The G string","La cuerda m\xE1s grave":"The lowest string","Dedo 1 La, dedo 2 alto Si y dedo 3 Do. Sube a la cuerda Re y tendr\xE1s la escala de Sol mayor.":"Finger 1 A, high finger 2 B and finger 3 C. Go up to the D string and you have the G major scale.","La armadura":"The key signature","Alteraciones fijas":"Fixed accidentals","Los sostenidos o bemoles del principio de cada l\xEDnea valen para toda la obra: si hay un Fa\u266F, todos los Fa son sostenidos.":"The sharps or flats at the start of each line apply to the whole piece: if there is an F\u266F, every F is sharp.","Te dice la tonalidad":"It tells you the key","Sin alteraciones: Do mayor. Un sostenido (Fa\u266F): Sol mayor. Dos (Fa\u266F y Do\u266F): Re mayor. Un bemol (Si\u266D): Fa mayor. Dos (Si\u266D y Mi\u266D): Si\u266D mayor, la favorita de la banda.":"No accidentals: C major. One sharp (F\u266F): G major. Two (F\u266F and C\u266F): D major. One flat (B\u266D): F major. Two (B\u266D and E\u266D): B\u266D major, the band's favourite.","La armadura tiene un solo sostenido, Fa\u266F. \xBFQu\xE9 tonalidad mayor es?":"The key signature has a single sharp, F\u266F. Which major key is it?","Sol mayor: su escala tiene un Fa\u266F.":"G major: its scale has an F\u266F.","Dedos en la cuerda Sol":"Fingers on the G string","Baja hasta la cuerda Sol":"Down to the G string","Corcheas y puntillos":"Eighth notes and dots","Las figuras":"Note values","Cu\xE1nto dura cada nota":"How long each note lasts","Redonda: 4 pulsos. Blanca: 2. Negra: 1. Corchea: medio pulso, van de dos en dos. Un puntillo suma la mitad: negra con puntillo = 1 pulso y medio.":"Whole note: 4 beats. Half note: 2. Quarter note: 1. Eighth note: half a beat, they come in pairs. A dot adds half: dotted quarter note = 1 and a half beats.","Toca a tempo":"Play in time","En el modo a tempo la partitura avanza sola tras una cuenta de un comp\xE1s. Sigue la l\xEDnea vertical y toca cada nota cuando llegue.":"In timed mode the score moves on its own after a one-bar count-in. Follow the vertical line and play each note as it arrives.","La escala mayor":"The major scale","Tono, tono, semitono\u2026":"Tone, tone, semitone\u2026","Toda escala mayor sigue el mismo patr\xF3n: tono, tono, semitono, tono, tono, tono, semitono. Empieces donde empieces, suena \xABa escala mayor\xBB.":"Every major scale follows the same pattern: tone, tone, semitone, tone, tone, tone, semitone. Wherever you start, it sounds \u201Clike a major scale\u201D.","Mayor y menor":"Major and minor","La escala menor cambia algunos pasos y suena m\xE1s triste. Escucha la diferencia en los acordes: el mayor suena luminoso; el menor, melanc\xF3lico.":"The minor scale changes some steps and sounds sadder. Listen to the difference in the chords: major sounds bright; minor, melancholic.","Escucha el acorde. \xBFEs mayor o menor?":"Listen to the chord. Is it major or minor?",Menor:"Minor","El mayor tiene la tercera mayor (4 semitonos); el menor, la tercera menor (3).":"A major chord has a major third (4 semitones); a minor chord, a minor third (3).","Notas repetidas":"Repeated notes",Corcheas:"Eighth notes","Dos notas por pulso":"Two notes per beat","Segundo dedo bajo":"Low second finger","Do natural y Sol natural":"C natural and G natural","Dedo 2 bajo":"Low finger 2","Junto al primero":"Next to the first","Si pegas el dedo 2 al 1 suena medio tono m\xE1s bajo: en la cuerda La da Do natural y en la cuerda Mi, Sol natural.":"If you put finger 2 right next to finger 1 it sounds a semitone lower: on the A string it gives C natural and on the E string, G natural.","Dedo 1 bajo":"Low finger 1","En la cuerda Mi, el dedo 1 pegado a la cejuela da Fa natural. Lo usar\xE1s en las tonalidades menores.":"On the E string, finger 1 right by the nut gives F natural. You will use it in minor keys.","Intervalos y acordes":"Intervals and chords","La distancia entre dos notas":"The distance between two notes","Se cuenta en notas: de Do a Mi hay una tercera (Do-Re-Mi); de Do a Sol, una quinta. La octava es la misma nota m\xE1s aguda.":"It is counted in notes: from C to E is a third (C-D-E); from C to G, a fifth. The octave is the same note, higher.","Un acorde son terceras apiladas":"A chord is stacked thirds","Do-Mi-Sol: una tercera y otra tercera. En la banda cada secci\xF3n toca una nota del acorde: por eso es tan importante afinar en conjunto.":"C-E-G: a third and another third. In a band each section plays one note of the chord: that is why tuning together matters so much.","\xBFQu\xE9 intervalo hay de Do a Sol?":"What interval is there from C to G?",Tercera:"Third",Cuarta:"Fourth",Quinta:"Fifth",Octava:"Octave","Una quinta: Do-Re-Mi-Fa-Sol son cinco notas.":"A fifth: C-D-E-F-G is five notes.","Dedo 2 alto y bajo":"High and low finger 2","Do natural":"C natural","Dedo 2 bajo en La y Mi":"Low finger 2 on A and E","Desde la cuerda Sol":"From the G string","Bach para viol\xEDn":"Bach for violin","Menores y expresi\xF3n":"Minor keys and expression","La menor y frases largas":"A minor and long phrases","Tonalidades menores":"Minor keys","Otro color":"Another colour","La escala de La menor usa Do natural, Fa natural y Sol natural. Suena m\xE1s melanc\xF3lica. En las melod\xEDas a veces aparece Sol\u266F para volver a La.":"The A minor scale uses C natural, F natural and G natural. It sounds more melancholic. In melodies G\u266F sometimes appears to lead back to A.","Din\xE1micas y expresi\xF3n":"Dynamics and expression","Fuerte y piano":"Loud and soft","pp (pian\xEDsimo), p (piano), mp, mf, f (forte), ff (fort\xEDsimo). Crescendo (<) sube poco a poco; diminuendo (>) baja.":"pp (pianissimo), p (piano), mp, mf, f (forte), ff (fortissimo). Crescendo (<) gets louder little by little; diminuendo (>) softer.","Tocar en grupo":"Playing in a group","En la banda, \xABpiano\xBB no es tocar flojo sin m\xE1s: es dejar que se oiga la melod\xEDa. Escucha a los dem\xE1s mientras tocas.":"In a band, \u201Cpiano\u201D doesn't just mean playing weakly: it means letting the melody be heard. Listen to the others while you play.","\xBFQu\xE9 significa \xABf\xBB en la partitura?":"What does \u201Cf\u201D mean in the score?","Forte: fuerte":"Forte: loud","Forte, fuerte. \xABp\xBB es piano, suave.":"Forte, loud. \u201Cp\u201D is piano, soft.","Natural, una octava":"Natural, one octave","Tradicional en La menor":"Traditional in A minor","Tus primeras notas, ritmos y canciones":"Your first notes, rhythms and songs","Teor\xEDa con preguntas":"Theory with questions","Cinco l\xEDneas y cuatro espacios":"Five lines and four spaces","La m\xFAsica se escribe en el pentagrama. Cuanto m\xE1s arriba est\xE1 una nota, m\xE1s aguda suena. Las l\xEDneas y los espacios se cuentan de abajo arriba.":"Music is written on the staff. The higher a note sits, the higher it sounds. Lines and spaces are counted from the bottom up.","La clave":"The clef","Al principio de cada l\xEDnea va la clave, que dice qu\xE9 nota es cada l\xEDnea. La clave de sol se enrosca en la segunda l\xEDnea: ah\xED est\xE1 el Sol. Los instrumentos graves usan la clave de fa, que marca el Fa en la cuarta l\xEDnea.":"At the start of each line there is the clef, which says which note each line is. The treble clef curls around the second line: that line is G. Low instruments use the bass clef, which marks F on the fourth line.","L\xEDneas adicionales":"Ledger lines","Las notas que no caben en el pentagrama se escriben con peque\xF1as l\xEDneas adicionales por encima o por debajo. El Do central, en clave de sol, va en la primera l\xEDnea adicional de abajo.":"Notes that don't fit on the staff are written with short ledger lines above or below. Middle C, in treble clef, sits on the first ledger line below.","\xBFEn qu\xE9 l\xEDnea se enrosca la clave de sol?":"Which line does the treble clef curl around?","En la primera":"The first","En la segunda":"The second","En la tercera":"The third","En la cuarta":"The fourth","En la segunda l\xEDnea, y por eso esa l\xEDnea es Sol.":"The second line, which is why that line is G.","Cuanto m\xE1s arriba est\xE1 una nota en el pentagrama\u2026":"The higher a note sits on the staff\u2026","M\xE1s grave suena":"The lower it sounds","M\xE1s fuerte suena":"The louder it sounds","M\xE1s aguda suena":"The higher it sounds","M\xE1s dura":"The harder it is","La altura en el papel es la altura del sonido: arriba, agudo; abajo, grave.":"Height on the page is the pitch of the sound: up is high; down is low.","Con las notas nuevas del cap\xEDtulo":"With the new notes of the chapter","Melod\xEDa nueva con las notas que ya sabes":"A new melody with the notes you already know","Las figuras dicen cu\xE1nto dura":"Note values tell you how long","La negra dura un pulso. La blanca, dos (es una negra hueca). La redonda, cuatro (hueca y sin plica).":"The quarter note lasts one beat. The half note, two (a hollow quarter note). The whole note, four (hollow, with no stem).","El pulso es el latido regular de la m\xFAsica, el que marcas con el pie. Las figuras se miden contando pulsos: \xABuno, dos, tres, cuatro\xBB.":"The pulse is the steady heartbeat of the music, the one you tap with your foot. Note values are measured by counting beats: \u201Cone, two, three, four\u201D.","\xBFCu\xE1ntos pulsos dura una blanca?":"How many beats does a half note last?",Uno:"One",Dos:"Two",Tres:"Three",Cuatro:"Four","Dos pulsos: lo mismo que dos negras.":"Two beats: the same as two quarter notes.","\xBFCu\xE1ntas negras caben en una redonda?":"How many quarter notes fit in a whole note?",Ocho:"Eight","Cuatro: la redonda dura cuatro pulsos.":"Four: the whole note lasts four beats.","Las barras verticales dividen la m\xFAsica en compases. Cada comp\xE1s tiene el mismo n\xFAmero de pulsos. La barra doble del final indica que la obra termina.":"Vertical bar lines divide music into bars. Each bar has the same number of beats. The double bar line at the end means the piece is over.","La indicaci\xF3n de comp\xE1s":"The time signature","Los dos n\xFAmeros del principio: el de arriba dice cu\xE1ntos pulsos hay en cada comp\xE1s; el de abajo, qu\xE9 figura vale un pulso (el 4 significa la negra). 4/4 son cuatro negras por comp\xE1s.":"The two numbers at the start: the top one says how many beats are in each bar; the bottom one, which note value gets one beat (4 means the quarter note). 4/4 is four quarter notes per bar.","Parte fuerte":"Downbeat","El primer pulso de cada comp\xE1s es el m\xE1s importante: la parte fuerte. Si marcas un poco el \xABuno\xBB, la m\xFAsica respira y los dem\xE1s te siguen.":"The first beat of each bar is the most important: the downbeat. If you lean a little on \u201Cone\u201D, the music breathes and the others follow you.","En un comp\xE1s de 3/4, \xBFcu\xE1ntas negras hay?":"In a 3/4 bar, how many quarter notes are there?",Seis:"Six","El n\xFAmero de arriba manda: tres pulsos de negra.":"The top number rules: three quarter-note beats.","Callar tambi\xE9n es m\xFAsica":"Silence is music too","Cada figura tiene su silencio, que dura lo mismo. El silencio de negra parece un rayo; el de blanca es un rect\xE1ngulo encima de la tercera l\xEDnea; el de redonda, colgado de la cuarta.":"Every note value has its rest, which lasts the same. The quarter rest looks like a lightning bolt; the half rest is a block sitting on the third line; the whole rest hangs from the fourth.","Cuenta durante el silencio":"Count through the rest","En un silencio el pulso sigue. Cuenta por dentro y prep\xE1rate para la nota siguiente: el error m\xE1s t\xEDpico es entrar antes de tiempo.":"During a rest the pulse carries on. Count inside and get ready for the next note: the most typical mistake is coming in early.","Un silencio de blanca dura\u2026":"A half rest lasts\u2026","Un pulso":"One beat","Dos pulsos":"Two beats","Medio pulso":"Half a beat","Cuatro pulsos":"Four beats","Lo mismo que la blanca: dos pulsos.":"The same as the half note: two beats.","La corchea":"The eighth note","Dura medio pulso: dos corcheas valen una negra. Sueltas llevan un corchete; juntas se unen con una barra. Cu\xE9ntalas \xABuno-y, dos-y\xBB.":"It lasts half a beat: two eighth notes make a quarter note. On their own they have a flag; together they are joined by a beam. Count them \u201Cone-and, two-and\u201D.","El puntillo":"The dot","Un puntillo a la derecha de una nota le suma la mitad de lo que vale. Blanca con puntillo: 2 + 1 = 3 pulsos. Negra con puntillo: 1 + \xBD = 1 y medio.":"A dot to the right of a note adds half of its value. Dotted half note: 2 + 1 = 3 beats. Dotted quarter note: 1 + \xBD = 1 and a half.","\xBFCu\xE1nto dura una blanca con puntillo?":"How long does a dotted half note last?","Dos y medio":"Two and a half","Tres pulsos":"Three beats","La blanca (2) m\xE1s la mitad (1): tres pulsos.":"The half note (2) plus half of it (1): three beats.","\xBFCu\xE1ntas corcheas caben en una negra?":"How many eighth notes fit in a quarter note?",Una:"One","Dos: cada corchea dura medio pulso.":"Two: each eighth note lasts half a beat.","Con las notas que ya sabes":"With the notes you already know",Alteraciones:"Accidentals","El sostenido (\u266F) sube la nota medio tono; el bemol (\u266D) la baja medio tono; el becuadro (\u266E) anula la alteraci\xF3n y deja la nota natural.":"The sharp (\u266F) raises a note by a semitone; the flat (\u266D) lowers it by a semitone; the natural (\u266E) cancels the accidental and leaves the note natural.","Valen todo el comp\xE1s":"They last the whole bar","Una alteraci\xF3n escrita junto a una nota afecta a esa nota durante el resto del comp\xE1s. En el comp\xE1s siguiente, la nota vuelve a ser natural.":"An accidental written next to a note affects that note for the rest of the bar. In the next bar the note is natural again.","\xBFQu\xE9 hace el sostenido?":"What does the sharp do?","Baja medio tono":"Lowers it a semitone","Sube medio tono":"Raises it a semitone","Alarga la nota":"Makes the note longer","La hace m\xE1s fuerte":"Makes it louder","Sube la nota medio tono (un semitono).":"It raises the note by a semitone.","Si en un comp\xE1s aparece Fa\u266F, \xBFc\xF3mo es el siguiente Fa del mismo comp\xE1s?":"If F\u266F appears in a bar, what is the next F in the same bar?",Sostenido:"Sharp",Bemol:"Flat","Depende del instrumento":"It depends on the instrument","Sostenido: la alteraci\xF3n vale hasta la barra de comp\xE1s.":"Sharp: the accidental lasts until the bar line.","Las alteraciones que van junto a la clave, al principio de cada l\xEDnea, son la armadura: valen para toda la obra y en todas las octavas.":"The accidentals next to the clef, at the start of each line, are the key signature: they apply to the whole piece and in every octave.","Un sostenido (Fa\u266F) suele ser Sol mayor; dos (Fa\u266F y Do\u266F), Re mayor; un bemol (Si\u266D), Fa mayor; dos bemoles, Si\u266D mayor. Sin nada: Do mayor o La menor.":"One sharp (F\u266F) is usually G major; two (F\u266F and C\u266F), D major; one flat (B\u266D), F major; two flats, B\u266D major. Nothing: C major or A minor.","Una armadura con Fa\u266F y Do\u266F suele ser\u2026":"A key signature with F\u266F and C\u266F is usually\u2026","Dos sostenidos: Re mayor (o su relativa, Si menor).":"Two sharps: D major (or its relative, B minor).","Las din\xE1micas":"Dynamics","pp (pianissimo, muy suave), p (piano, suave), mp y mf (medio), f (forte, fuerte) y ff (fortissimo, muy fuerte). Vienen del italiano.":"pp (pianissimo, very soft), p (piano, soft), mp and mf (medium), f (forte, loud) and ff (fortissimo, very loud). They come from Italian.",Reguladores:"Hairpins","El \xABabanico\xBB que se abre (<) es crescendo: cada vez m\xE1s fuerte. El que se cierra (>) es diminuendo: cada vez m\xE1s suave.":"The \u201Cfan\u201D that opens (<) is crescendo: louder and louder. The one that closes (>) is diminuendo: softer and softer.","\xBFQu\xE9 significa la \xABp\xBB bajo una nota?":"What does the \u201Cp\u201D under a note mean?",Pausa:"Pause",Suave:"Soft",Pulso:"Pulse",Picado:"Tongued","p es piano: tocar suave.":"p is piano: play softly.","Barras de repetici\xF3n":"Repeat bars","Dos puntos junto a una barra doble significan \xABvuelve a tocar desde la barra de repetici\xF3n anterior\xBB, o desde el principio si no hay ninguna.":"Two dots next to a double bar mean \u201Cplay again from the previous repeat bar\u201D, or from the beginning if there isn't one.","Casillas de 1.\xAA y 2.\xAA vez":"1st and 2nd endings","La primera vez tocas la casilla 1 y repites; la segunda vez te la saltas y tocas la casilla 2.":"The first time you play ending 1 and repeat; the second time you skip it and play ending 2.","D. C. y Fine":"D.C. and Fine","Da Capo (D. C.) es \xABdesde el principio\xBB. Al fine se termina en la palabra Fine. Al Coda manda saltar al signo de la coda (un c\xEDrculo con una cruz).":"Da Capo (D.C.) means \u201Cfrom the beginning\u201D. Al Fine means you finish at the word Fine. Al Coda sends you to the coda sign (a circle with a cross).","\xBFQu\xE9 significa D. C. al Fine?":"What does D.C. al Fine mean?","Termina aqu\xED":"It ends here","Repite desde el principio hasta \xABFine\xBB":"Repeat from the beginning to \u201CFine\u201D","M\xE1s despacio hasta el final":"Slower until the end","Salta a la coda":"Jump to the coda","Da Capo: desde el principio, y se termina donde pone Fine.":"Da Capo: from the beginning, ending where it says Fine.","Teor\xEDa, interpretaci\xF3n y glosario":"Theory, performance and glossary","Examen: lenguaje musical":"Exam: music theory","C\xF3mo es el examen":"How the exam works","Repasa las preguntas de todo el libro. Con el 70 % de aciertos apruebas y se abre el Libro 2. Puedes repetirlo las veces que quieras.":"Review the questions from the whole book. With 70 % correct you pass and Book 2 opens. You can retake it as many times as you like.","Examen: prueba de interpretaci\xF3n":"Exam: performance test","Una lectura nueva, de una sola vez":"A new reading, in a single take","Las palabras del libro":"The words of the book","Bemol \u2026 Piano / forte":"Flat \u2026 Piano / forte","Bemol: Baja la nota medio tono. \xB7 Becuadro: Anula una alteraci\xF3n. \xB7 Armadura: Alteraciones fijas junto a la clave. \xB7 Da Capo: Volver al principio. \xB7 Piano / forte: Suave / fuerte.":"Flat: Lowers the note a semitone. \xB7 Natural: Cancels an accidental. \xB7 Key signature: Fixed accidentals next to the clef. \xB7 Da Capo: Back to the beginning. \xB7 Piano / forte: Soft / loud.","Tonalidades, articulaci\xF3n, escalas y repertorio":"Keys, articulation, scales and repertoire","Compases de 2/4, 3/4 y 4/4":"2/4, 3/4 and 4/4 time","Binario, ternario y cuaternario":"Duple, triple and quadruple","2/4 tiene dos pulsos (marchas, pasodobles); 3/4, tres (valses, minuetos); 4/4, cuatro (casi todo el pop). La C en lugar de n\xFAmeros es 4/4.":"2/4 has two beats (marches, pasodobles); 3/4, three (waltzes, minuets); 4/4, four (almost all pop). A C instead of numbers means 4/4.","C\xF3mo se marca":"How it is conducted","Los directores marcan el 2 abajo-arriba; el 3 abajo-derecha-arriba; el 4 abajo-izquierda-derecha-arriba. Siempre el primero hacia abajo: la parte fuerte.":"Conductors beat 2 down-up; 3 down-right-up; 4 down-left-right-up. The first is always downwards: the downbeat.","\xBFQu\xE9 comp\xE1s indica una C al principio?":"Which time signature does a C at the start mean?","La C es el comp\xE1s de compasillo: 4/4.":"The C is common time: 4/4.","\xBFEn qu\xE9 comp\xE1s suele ir un vals?":"Which time signature is a waltz usually in?","En 3/4: un-dos-tres, con el uno fuerte.":"In 3/4: one-two-three, with a strong one.","Para tu instrumento":"For your instrument","Arco recto":"Straight bow","El arco paralelo al puente y a medio camino entre el puente y el diapas\xF3n. M\xEDralo en un espejo: un arco recto suena limpio.":"The bow parallel to the bridge, halfway between the bridge and the fingerboard. Check it in a mirror: a straight bow sounds clean.","Primero lento y ligado; despu\xE9s picado y a tempo":"First slow and slurred; then tongued and in time",Semicorcheas:"Sixteenth notes","Cuatro por pulso":"Four per beat","La semicorchea dura un cuarto de pulso: cuatro valen una negra. Lleva dos corchetes o dos barras. Cu\xE9ntalas \xAB1-e-y-a\xBB.":"The sixteenth note lasts a quarter of a beat: four make a quarter note. It has two flags or two beams. Count them \u201C1-e-and-a\u201D.",Combinaciones:"Combinations","Corchea y dos semicorcheas (\xABta-ti-ti\xBB), dos semicorcheas y corchea (\xABti-ti-ta\xBB) y corchea con puntillo y semicorchea (el ritmo \xABsaltado\xBB de las marchas).":"An eighth and two sixteenths (\u201Cta-ti-ti\u201D), two sixteenths and an eighth (\u201Cti-ti-ta\u201D) and a dotted eighth with a sixteenth (the \u201Cskipping\u201D rhythm of marches).","\xBFCu\xE1ntas semicorcheas caben en una blanca?":"How many sixteenth notes fit in a half note?","Una blanca son dos negras y cada negra cuatro semicorcheas: ocho.":"A half note is two quarter notes and each quarter note four sixteenths: eight.","Distribuci\xF3n del arco":"Bow distribution","Una blanca con todo el arco, dos negras con la mitad cada una. Planifica cu\xE1nto arco gastas para no quedarte sin \xE9l.":"A half note with the whole bow, two quarter notes with half each. Plan how much bow you use so you don't run out.",Ligaduras:"Ties and slurs","Ligadura de uni\xF3n":"Tie","Une dos notas iguales: se toca una sola nota que dura lo que suman las dos. Sirve para alargar una nota m\xE1s all\xE1 de la barra de comp\xE1s.":"It joins two identical notes: you play a single note lasting as long as both together. It is used to hold a note over the bar line.","Ligadura de expresi\xF3n":"Slur","Abarca notas distintas y significa \xABtocar ligado\xBB: sin cortar entre ellas (en viento, sin volver a picar; en cuerda, en el mismo arco).":"It covers different notes and means \u201Cplay legato\u201D: without breaks between them (on wind, without tonguing again; on strings, in the same bow).","Una ligadura entre dos notas iguales\u2026":"A tie between two identical notes\u2026","Se tocan dos veces":"They are played twice","Suman su duraci\xF3n en una sola nota":"Their lengths add up into a single note","Se tocan m\xE1s fuerte":"They are played louder","Se tocan m\xE1s r\xE1pido":"They are played faster","Es una ligadura de uni\xF3n: una sola nota con la duraci\xF3n de las dos.":"It is a tie: a single note lasting as long as both.","Detach\xE9 y legato":"D\xE9tach\xE9 and legato","Detach\xE9: una nota por arco, sin cortes. Legato: varias notas en el mismo arco, cambiando los dedos justo a tiempo.":"D\xE9tach\xE9: one note per bow, without breaks. Legato: several notes in the same bow, changing fingers right on time.",Articulaci\u00F3n:"Articulation","C\xF3mo empieza y acaba cada nota":"How each note starts and ends","Picado: cada nota con su ataque. Ligado: sin cortes. Staccato (un punto encima): corta y separada. Tenuto (una rayita): larga y apoyada. Acento (>): con m\xE1s fuerza al empezar.":"Tongued: each note with its attack. Slurred: no breaks. Staccato (a dot above): short and separated. Tenuto (a small line): long and leaned on. Accent (>): stronger at the start.","Por qu\xE9 importa":"Why it matters","Las mismas notas suenan a marcha o a nana seg\xFAn la articulaci\xF3n. Leerla y respetarla es la diferencia entre tocar notas y hacer m\xFAsica.":"The same notes sound like a march or a lullaby depending on the articulation. Reading it and respecting it is the difference between playing notes and making music.","Un punto encima o debajo de una nota indica\u2026":"A dot above or below a note means\u2026","Que se alarga":"It is held longer","Staccato: corta y separada":"Staccato: short and separated","Que se repite":"It is repeated","Que es m\xE1s grave":"It is lower","Es staccato: la nota se toca corta.":"It is staccato: the note is played short.","Segundo dedo alto y bajo":"High and low second finger","El segundo dedo pegado al primero o al tercero cambia la tonalidad. Escucha la diferencia entre Do natural y Do\u266F en la cuerda La.":"The second finger next to the first or the third changes the key. Listen to the difference between C natural and C\u266F on the A string.","Escalas mayores y el c\xEDrculo de quintas":"Major scales and the circle of fifths","Toda escala mayor sigue el mismo patr\xF3n de distancias: tono, tono, semitono, tono, tono, tono, semitono. Por eso, empezando en otra nota, hacen falta alteraciones.":"Every major scale follows the same pattern of steps: tone, tone, semitone, tone, tone, tone, semitone. That is why accidentals are needed when you start on another note.","El c\xEDrculo de quintas":"The circle of fifths","Sube de quinta en quinta y cada tonalidad suma un sostenido: Do (0), Sol (1), Re (2), La (3), Mi (4). Bajando de quinta en quinta se suman bemoles: Fa (1), Si\u266D (2), Mi\u266D (3), La\u266D (4).":"Go up fifth by fifth and each key adds a sharp: C (0), G (1), D (2), A (3), E (4). Going down by fifths you add flats: F (1), B\u266D (2), E\u266D (3), A\u266D (4).","Orden de las alteraciones":"Order of the accidentals","Los sostenidos aparecen siempre en el mismo orden: Fa, Do, Sol, Re, La, Mi, Si. Los bemoles, al rev\xE9s: Si, Mi, La, Re, Sol, Do, Fa.":"Sharps always appear in the same order: F, C, G, D, A, E, B. Flats, the other way round: B, E, A, D, G, C, F.","En la escala mayor, \xBFd\xF3nde est\xE1n los semitonos?":"In the major scale, where are the semitones?","Entre 1-2 y 5-6":"Between 1-2 and 5-6","Entre 3-4 y 7-8":"Between 3-4 and 7-8","Entre 2-3 y 6-7":"Between 2-3 and 6-7","No tiene semitonos":"It has no semitones","Entre los grados 3-4 y 7-8 (en Do: Mi-Fa y Si-Do).":"Between degrees 3-4 and 7-8 (in C: E-F and B-C).","\xBFCu\xE1ntos bemoles tiene Mi\u266D mayor?":"How many flats does E\u266D major have?","Tres: Si\u266D, Mi\u266D y La\u266D.":"Three: B\u266D, E\u266D and A\u266D.","Cambios de cuerda":"String crossings","Prepara el codo antes de cambiar de cuerda. El movimiento sale del brazo, no solo de la mu\xF1eca.":"Prepare your elbow before changing string. The movement comes from the arm, not just the wrist.","La relativa menor":"The relative minor","Cada tonalidad mayor tiene una menor con la misma armadura, una tercera menor por debajo: Do mayor y La menor, Sol mayor y Mi menor, Fa mayor y Re menor.":"Every major key has a minor key with the same key signature, a minor third below: C major and A minor, G major and E minor, F major and D minor.","C\xF3mo distinguirlas":"How to tell them apart","Mira la \xFAltima nota y el acorde final: si acaba en La con la armadura de Do, est\xE1 en La menor. En menor suele aparecer el 7.\xBA grado subido (Sol\u266F en La menor).":"Look at the last note and the final chord: if it ends on A with the key signature of C, it is in A minor. In minor the 7th degree is usually raised (G\u266F in A minor).","\xBFCu\xE1l es la relativa menor de Sol mayor?":"What is the relative minor of G major?","Mi menor: comparten el Fa\u266F de la armadura.":"E minor: they share the F\u266F in the key signature.","La afinaci\xF3n":"Tuning","Compara con las cuerdas al aire: un Re pisado en la cuerda La debe \xABhacer vibrar\xBB la cuerda Re al aire.":"Compare with the open strings: a stopped D on the A string should \u201Cmake the open D string ring\u201D.",Intervalos:"Intervals","Se cuentan las notas de la primera a la \xFAltima, ambas incluidas: Do-Mi es una tercera (Do, Re, Mi); Do-Sol, una quinta; Do-Do, una octava.":"Count the notes from the first to the last, both included: C-E is a third (C, D, E); C-G, a fifth; C-C, an octave.","Mayores y menores":"Major and minor","Una tercera mayor tiene dos tonos (Do-Mi); una menor, tono y medio (La-Do). La tercera mayor suena alegre y la menor, melanc\xF3lica.":"A major third has two tones (C-E); a minor one, a tone and a half (A-C). The major third sounds happy and the minor one, melancholic.","Para afinar":"For tuning","Las quintas y octavas tienen que sonar \xABlimpias\xBB, sin batidos. En la banda, afinar los acordes es escuchar estos intervalos.":"Fifths and octaves have to sound \u201Cclean\u201D, without beats. In a band, tuning chords means listening to these intervals.","\xBFQu\xE9 intervalo hay de Re a La?":"What interval is there from D to A?","Una cuarta":"A fourth","Una quinta":"A fifth","Una sexta":"A sixth","Una tercera":"A third","Re, Mi, Fa, Sol, La: cinco notas, una quinta.":"D, E, F, G, A: five notes, a fifth.","Matices con el arco":"Dynamics with the bow","M\xE1s peso y velocidad de arco para forte; menos para piano. El punto de contacto tambi\xE9n cambia: m\xE1s cerca del puente, m\xE1s fuerte.":"More weight and bow speed for forte; less for piano. The contact point changes too: closer to the bridge, louder.","El tempo y sus palabras":"Tempo and its words","Del m\xE1s lento al m\xE1s r\xE1pido":"From slowest to fastest","Largo, Adagio, Andante (al paso), Moderato, Allegro (r\xE1pido y alegre), Vivace y Presto. Muchas partituras ponen tambi\xE9n el metr\xF3nomo: \u2669 = 96.":"Largo, Adagio, Andante (walking pace), Moderato, Allegro (fast and lively), Vivace and Presto. Many scores also give the metronome mark: \u2669 = 96.","Cambios de tempo":"Tempo changes","Ritardando (rit.): cada vez m\xE1s despacio. Accelerando: cada vez m\xE1s deprisa. A tempo: vuelve a la velocidad de antes. Fermata (\u{1D110}): la nota se alarga a gusto.":"Ritardando (rit.): slower and slower. Accelerando: faster and faster. A tempo: back to the previous speed. Fermata (\u{1D110}): the note is held at will.","\xBFCu\xE1l es m\xE1s r\xE1pido?":"Which is fastest?","Allegro es r\xE1pido; Andante es al paso y Adagio y Largo, lentos.":"Allegro is fast; Andante is a walking pace and Adagio and Largo are slow.","\xBFQu\xE9 significa \xABrit.\xBB?":"What does \u201Crit.\u201D mean?","Ritmo libre":"Free rhythm","Cada vez m\xE1s despacio":"Slower and slower","M\xE1s fuerte":"Louder","Ritardando: frenar poco a poco.":"Ritardando: slowing down little by little.","Escalas de dos octavas":"Two-octave scales","Las escalas en primera posici\xF3n, de memoria y lentas, con la afinaci\xF3n vigilada nota a nota.":"Scales in first position, from memory and slow, checking the tuning note by note.","Repasa las preguntas de todo el libro. Con el 70 % de aciertos apruebas y se abre el Libro 3. Puedes repetirlo las veces que quieras.":"Review the questions from the whole book. With 70 % correct you pass and Book 3 opens. You can retake it as many times as you like.","Acento \u2026 Allegro":"Accent \u2026 Allegro","Acento: Ataque m\xE1s fuerte. \xB7 Escala mayor: Siete notas con el patr\xF3n T-T-S-T-T-T-S. \xB7 Relativa menor: Tonalidad menor con la misma armadura. \xB7 Intervalo: Distancia entre dos notas. \xB7 Allegro: R\xE1pido.":"Accent: Stronger attack. \xB7 Major scale: Seven notes with the pattern T-T-S-T-T-T-S. \xB7 Relative minor: Minor key with the same key signature. \xB7 Interval: Distance between two notes. \xB7 Allegro: Fast.","Andante: Al paso. \xB7 Ritardando: Cada vez m\xE1s despacio. \xB7 Fermata: Calder\xF3n: alargar a gusto.":"Andante: Walking pace. \xB7 Ritardando: Slower and slower. \xB7 Fermata: Pause: hold at will.","Todas las tonalidades, t\xE9cnica avanzada y concierto":"All keys, advanced technique and concert","Compases compuestos: 6/8":"Compound time: 6/8","Pulsos que se dividen en tres":"Beats divided into three","En 6/8 hay seis corcheas por comp\xE1s agrupadas de tres en tres: se sienten dos pulsos de negra con puntillo. Suena a \xABbalanceo\xBB, como una barcarola o una jota.":"In 6/8 there are six eighth notes per bar grouped in threes: you feel two dotted-quarter beats. It sounds like \u201Cswaying\u201D, like a barcarolle or a jota.","C\xF3mo se cuenta":"How it is counted","Lento, se cuentan las seis corcheas; a tempo, solo dos pulsos: \xABUNO-y-a, DOS-y-a\xBB. 9/8 tiene tres pulsos y 12/8, cuatro.":"Slowly, count the six eighth notes; in time, only two beats: \u201CONE-and-a, TWO-and-a\u201D. 9/8 has three beats and 12/8, four.","\xBFCu\xE1ntos pulsos se sienten en un 6/8 r\xE1pido?":"How many beats do you feel in a fast 6/8?","Dos pulsos de negra con puntillo, cada uno con tres corcheas.":"Two dotted-quarter beats, each with three eighth notes.","La tercera posici\xF3n":"Third position","Desliza la mano para que el primer dedo est\xE9 donde estaba el tercero. Practica el cambio con un dedo gu\xEDa y sin prisa.":"Slide your hand so that the first finger is where the third was. Practise the shift with a guide finger and without rushing.","Tresillos y s\xEDncopas":"Triplets and syncopation","El tresillo":"The triplet","Tres notas en el tiempo de dos, marcadas con un 3. Un tresillo de corcheas ocupa una negra: tres notas iguales en un pulso.":"Three notes in the time of two, marked with a 3. An eighth-note triplet takes up a quarter note: three equal notes in one beat.","La s\xEDncopa":"Syncopation","Una nota que empieza en parte d\xE9bil y se alarga sobre la fuerte. Da empuje: es el alma del jazz, el pop y muchos pasodobles. Siente el pulso aunque no lo toques.":"A note that starts on a weak beat and is held over the strong one. It gives drive: it is the soul of jazz, pop and many pasodobles. Feel the pulse even when you don't play it.","Un tresillo de corcheas dura\u2026":"An eighth-note triplet lasts\u2026","Media negra":"Half a quarter note","Una negra":"A quarter note","Una blanca":"A half note","Tres negras":"Three quarter notes","Tres corcheas en el tiempo de dos: una negra.":"Three eighth notes in the time of two: a quarter note.","El vibrato":"Vibrato","Un balanceo suave del dedo desde la mu\xF1eca o el brazo. Empieza lento, con el metr\xF3nomo, sobre notas largas.":"A gentle rocking of the finger from the wrist or the arm. Start slowly, with the metronome, on long notes.","Acordes y funciones":"Chords and functions","El acorde":"The chord","Tres o m\xE1s notas a la vez. El m\xE1s com\xFAn es la tr\xEDada: fundamental, tercera y quinta (Do-Mi-Sol). Si la tercera es mayor, el acorde es mayor; si es menor, menor.":"Three or more notes at once. The most common is the triad: root, third and fifth (C-E-G). If the third is major the chord is major; if it is minor, minor.","T\xF3nica, subdominante y dominante":"Tonic, subdominant and dominant","Sobre los grados I, IV y V se construyen los acordes principales. La t\xF3nica (I) es reposo; la dominante (V) es tensi\xF3n que pide volver a la t\xF3nica. Con I-IV-V se acompa\xF1an miles de canciones.":"The main chords are built on degrees I, IV and V. The tonic (I) is rest; the dominant (V) is tension that wants to return to the tonic. Thousands of songs are accompanied with I-IV-V.","La s\xE9ptima de dominante":"The dominant seventh","A\xF1adir la s\xE9ptima a la dominante (Sol7 en Do) aumenta la tensi\xF3n y hace la vuelta a casa m\xE1s clara. Es la cadencia perfecta: V7-I.":"Adding the seventh to the dominant (G7 in C) increases the tension and makes the return home clearer. It is the perfect cadence: V7-I.","En Do mayor, \xBFcu\xE1l es el acorde de dominante?":"In C major, which is the dominant chord?","Sol: est\xE1 sobre el V grado.":"G: it is on the 5th degree.","Staccato y spiccato":"Staccato and spiccato","Staccato: notas cortas con el arco en la cuerda. Spiccato: el arco rebota cerca del punto de equilibrio. Empieza lento.":"Staccato: short notes with the bow on the string. Spiccato: the bow bounces near the balance point. Start slowly.","Escala crom\xE1tica y enarmon\xEDas":"Chromatic scale and enharmonics","Doce semitonos":"Twelve semitones","La escala crom\xE1tica recorre todos los semitonos de la octava. Subiendo se escribe con sostenidos y bajando con bemoles.":"The chromatic scale goes through every semitone in the octave. Going up it is written with sharps and going down with flats.",Enarmon\u00EDa:"Enharmonics","Do\u266F y Re\u266D suenan igual en tu instrumento: son la misma tecla o posici\xF3n escrita de dos maneras. Se escribe una u otra seg\xFAn la tonalidad.":"C\u266F and D\u266D sound the same on your instrument: they are the same key or position written in two ways. You write one or the other depending on the key.","\xBFQu\xE9 nota suena igual que Sol\u266F?":"Which note sounds the same as G\u266F?","Sol\u266F y La\u266D son enarm\xF3nicas.":"G\u266F and A\u266D are enharmonic.","Dobles cuerdas":"Double stops","Dos cuerdas a la vez con el mismo peso. Empieza con una cuerda al aire y escucha que el intervalo est\xE9 afinado.":"Two strings at once with the same weight. Start with one open string and listen that the interval is in tune.","Las tres escalas menores":"The three minor scales","Natural, arm\xF3nica y mel\xF3dica":"Natural, harmonic and melodic","La menor natural usa las notas de su relativa mayor. La arm\xF3nica sube el 7.\xBA grado (Sol\u266F en La menor). La mel\xF3dica sube el 6.\xBA y el 7.\xBA al subir y los deja naturales al bajar.":"The natural minor uses the notes of its relative major. The harmonic raises the 7th degree (G\u266F in A minor). The melodic raises the 6th and 7th going up and leaves them natural going down.","Para qu\xE9 sirve":"What it is for","El 7.\xBA subido crea la \xABsensible\xBB que empuja hacia la t\xF3nica. Por eso en piezas en menor aparecen alteraciones que no est\xE1n en la armadura.":"The raised 7th creates the \u201Cleading note\u201D that pulls towards the tonic. That is why pieces in minor have accidentals that are not in the key signature.","En La menor arm\xF3nica, \xBFqu\xE9 nota se altera?":"In A harmonic minor, which note is altered?",Ninguna:"None","El 7.\xBA grado, Sol, sube a Sol\u266F.":"The 7th degree, G, is raised to G\u266F.","Estudios t\xE9cnicos":"Technical studies","Los estudios de Wohlfahrt y Kayser trabajan arco y mano izquierda. Uno por semana, lento y perfecto.":"The Wohlfahrt and Kayser studies work on the bow and the left hand. One a week, slow and perfect.","La forma musical":"Musical form","Frases y secciones":"Phrases and sections","La m\xFAsica se organiza en frases (normalmente de 4 u 8 compases) que forman secciones. Se nombran con letras: A, B, C\u2026 Si una secci\xF3n vuelve, se repite la letra.":"Music is organised in phrases (usually 4 or 8 bars) that make up sections. They are named with letters: A, B, C\u2026 If a section comes back, its letter is repeated.","Formas habituales":"Common forms","Binaria (A-B), ternaria (A-B-A), rond\xF3 (A-B-A-C-A) y tema con variaciones. Una marcha de banda suele tener introducci\xF3n, primera parte, segunda y tr\xEDo.":"Binary (A-B), ternary (A-B-A), rondo (A-B-A-C-A) and theme and variations. A band march usually has an introduction, a first strain, a second and a trio.","La forma A-B-A se llama\u2026":"The form A-B-A is called\u2026",Binaria:"Binary",Ternaria:"Ternary",Rond\u00F3:"Rondo",Variaciones:"Variations","Ternaria: tres secciones, y la primera vuelve al final.":"Ternary: three sections, and the first one comes back at the end.","Tocar en secci\xF3n":"Playing in a section","Copia los arcos del concertino y escucha a tu atril: misma parte del arco y mismo car\xE1cter.":"Copy the leader's bowings and listen to your stand partner: same part of the bow and same character.","Para tocar con la banda":"To play with the band","Instrumentos transpositores":"Transposing instruments","Lo escrito y lo que suena":"What is written and what sounds","Un clarinete o una trompeta en Si\u266D que lee Do produce un Si\u266D real. Se escribe as\xED para que la misma digitaci\xF3n se lea igual en toda la familia.":"A B\u266D clarinet or trumpet reading C produces a real B\u266D. It is written like that so the same fingering reads the same across the whole family.","Afinar con la banda":"Tuning with the band","Cuando el director pide un Si\u266D de concierto, la trompeta toca su Do escrito, el saxo alto su Sol y la trompa su Fa. El o\xEDdo manda: escucha y ajusta.":"When the conductor asks for a concert B\u266D, the trumpet plays its written C, the alto sax its G and the horn its F. The ear rules: listen and adjust.","Un clarinete en Si\u266D lee Do. \xBFQu\xE9 nota real suena?":"A B\u266D clarinet reads C. Which real note sounds?","Si\u266D: suena un tono m\xE1s grave de lo escrito.":"B\u266D: it sounds a tone lower than written.","Antes de tocar, mira armadura, comp\xE1s, posiciones y pasajes dif\xEDciles. Al tocar, no te pares.":"Before playing, look at the key signature, time signature, positions and difficult passages. While playing, don't stop.","Fraseo e interpretaci\xF3n":"Phrasing and interpretation","Pensar en frases":"Thinking in phrases","Una frase tiene un punto culminante, como una pregunta o una respuesta. Ll\xE9vala hacia \xE9l y relaja al final. Respira (o cambia de arco) en el final de las frases, no en mitad.":"A phrase has a high point, like a question or an answer. Lead it there and relax at the end. Breathe (or change bow) at the end of phrases, not in the middle.","Estudiar con cabeza":"Practising smart","Busca el pasaje dif\xEDcil, t\xF3calo lento y perfecto, y sube la velocidad poco a poco. Diez minutos atentos valen m\xE1s que una hora en piloto autom\xE1tico.":"Find the hard passage, play it slow and perfect, and raise the speed little by little. Ten focused minutes are worth more than an hour on autopilot.","Tocar en p\xFAblico":"Playing in public","Los nervios son normales. Prep\xE1rate tocando la obra completa sin parar aunque falles: en un concierto, la m\xFAsica sigue.":"Nerves are normal. Prepare by playing the whole piece without stopping even if you make mistakes: in a concert, the music goes on.","\xBFD\xF3nde conviene respirar o cambiar de arco?":"Where is it best to breathe or change bow?","En cualquier sitio":"Anywhere","En mitad de la frase":"In the middle of the phrase","Al final de las frases":"At the end of phrases","Solo en los silencios largos":"Only in long rests","Al final de las frases: as\xED no se rompe el sentido musical.":"At the end of phrases: that way the musical sense is not broken.","Preparar un solo":"Preparing a solo","Decide los arcos y las digitaciones, m\xE1rcalos y gr\xE1bate. La interpretaci\xF3n se construye antes del concierto.":"Decide your bowings and fingerings, mark them and record yourself. The interpretation is built before the concert.","Repasa las preguntas de todo el libro. Con el 70 % de aciertos apruebas. Puedes repetirlo las veces que quieras.":"Review the questions from the whole book. With 70 % correct you pass. You can retake it as many times as you like.","6/8 \u2026 Dominante":"6/8 \u2026 Dominant","6/8: Comp\xE1s de dos pulsos divididos en tres. \xB7 Tresillo: Tres notas en el tiempo de dos. \xB7 S\xEDncopa: Nota en parte d\xE9bil prolongada sobre la fuerte. \xB7 Tr\xEDada: Acorde de tres notas. \xB7 Dominante: Acorde del V grado, de tensi\xF3n.":"6/8: Time of two beats divided into three. \xB7 Triplet: Three notes in the time of two. \xB7 Syncopation: Note on a weak beat held over the strong one. \xB7 Triad: Three-note chord. \xB7 Dominant: Chord on the 5th degree, of tension.","Cadencia perfecta \u2026 Forma ternaria":"Perfect cadence \u2026 Ternary form","Cadencia perfecta: Dominante a t\xF3nica: V-I. \xB7 Escala crom\xE1tica: Los doce semitonos seguidos. \xB7 Enarmon\xEDa: Misma nota con dos nombres. \xB7 Sensible: El 7.\xBA grado a medio tono de la t\xF3nica. \xB7 Forma ternaria: A-B-A.":"Perfect cadence: Dominant to tonic: V-I. \xB7 Chromatic scale: The twelve semitones in a row. \xB7 Enharmonic: Same note with two names. \xB7 Leading note: The 7th degree a semitone below the tonic. \xB7 Ternary form: A-B-A.","Rond\xF3 \u2026 Frase":"Rondo \u2026 Phrase","Rond\xF3: A-B-A-C-A. \xB7 Transpositor: Instrumento que suena distinto de lo que lee. \xB7 Frase: Unidad musical con sentido completo.":"Rondo: A-B-A-C-A. \xB7 Transposing: Instrument that sounds different from what it reads. \xB7 Phrase: Musical unit with a complete meaning.","Aire, embocadura y tres notas":"Air, embouchure and three notes","Conoce tu trompeta":"Get to know your trumpet","La respiraci\xF3n":"Breathing","Coge aire por la boca, profundo y sin subir los hombros, como si bostezaras. Sopla con el aire r\xE1pido y constante: la nota depende m\xE1s del aire que de apretar los labios.":"Breathe in through your mouth, deep and without raising your shoulders, as if yawning. Blow with fast, steady air: the note depends more on the air than on squeezing your lips.","La embocadura":"The embouchure","Labios juntos, comisuras firmes y la boquilla centrada, mitad arriba y mitad abajo. Haz vibrar los labios (el \xABbuzz\xBB) y deja que la boquilla lo amplifique.":"Lips together, firm corners and the mouthpiece centred, half above and half below. Make your lips vibrate (the \u201Cbuzz\u201D) and let the mouthpiece amplify it.","Tus primeras notas":"Your first notes","Empezamos por Do, Re, Mi (notas escritas). El diagrama te muestra qu\xE9 pulsar en cada una.":"We start with C, D, E (written notes). The diagram shows you what to press for each one.","Deja el m\xF3vil a un metro y no soples hacia el micr\xF3fono. La app ense\xF1a la nota escrita en tu instrumento, aunque el sonido real sea otro si transporta.":"Put the phone a metre away and don't blow towards the microphone. The app shows the written note for your instrument, even if the real sound is different when it transposes.","Trompeta en Si\u266D":"Trumpet in B\u266D","Cuando lees Do, suena Si\u266D: un tono m\xE1s grave. Por eso tu parte est\xE1 escrita un tono m\xE1s alta que la de la flauta.":"When you read C, B\u266D sounds: a tone lower. That is why your part is written a tone higher than the flute's.","La banda por tonalidades":"The band by keys","En Do (suenan lo que leen): flauta, oboe, fagot, tromb\xF3n, bombardino en clave de fa, tuba, viol\xEDn y piano. En Si\u266D: clarinete, trompeta, fliscorno, saxo soprano y tenor. En Mi\u266D: saxo alto y bar\xEDtono, requinto. En Fa: trompa. La guitarra suena una octava m\xE1s grave de lo escrito.":"In C (they sound what they read): flute, oboe, bassoon, trombone, euphonium in bass clef, tuba, violin and piano. In B\u266D: clarinet, trumpet, flugelhorn, soprano and tenor sax. In E\u266D: alto and baritone sax, E\u266D clarinet. In F: horn. The guitar sounds an octave lower than written.","\xBFPor qu\xE9? No es un defecto":"Why? It is not a defect","Es tradici\xF3n y comodidad: todos los tama\xF1os de una familia usan los mismos dedos para la misma nota escrita, as\xED un saxofonista cambia de alto a tenor sin aprender nada nuevo. Viene de cuando los metales cambiaban de tubo para tocar en cada tonalidad.":"It is tradition and convenience: every size in a family uses the same fingers for the same written note, so a saxophonist can switch from alto to tenor without learning anything new. It comes from the days when brass players changed tubing to play in each key.","C\xF3mo se afina":"How to tune","Con la bomba general: sacarla alarga el tubo y baja la afinaci\xF3n; meterla la sube. En Re y Do\u266F graves saca un poco la bomba del 3.er pist\xF3n. El aire caliente sube la afinaci\xF3n: afina despu\xE9s de unos minutos tocando, no en fr\xEDo. Y vuelve a comprobarla en mitad del ensayo.":"With the main tuning slide: pulling it out lengthens the tube and lowers the pitch; pushing it in raises it. On low D and C\u266F pull the 3rd valve slide out a little. Warm air raises the pitch: tune after a few minutes of playing, not cold. And check again in the middle of the rehearsal.","El director pide \xABun Si\u266D de concierto\xBB. \xBFQu\xE9 nota tocas t\xFA?":"The conductor asks for \u201Ca concert B\u266D\u201D. Which note do you play?","Tu instrumento est\xE1 en Si\u266D (suena un tono m\xE1s grave de lo escrito): para que suene Si\u266D t\xFA lees y tocas Do.":"Your instrument is in B\u266D (it sounds a tone lower than written): for B\u266D to sound, you read and play C.","Tres notas":"Three notes","Sonidos largos":"Long notes","Redondas: mant\xE9n el aire 4 pulsos":"Whole notes: hold the air for 4 beats","Negras y blancas":"Quarter and half notes","Cinco notas":"Five notes","Tu primera melod\xEDa":"Your first melody","Dos notas nuevas":"Two new notes",Ampliamos:"Expanding","A\xF1adimos Fa y Sol. Mira el diagrama de cada una antes de tocarla.":"We add F and G. Look at the diagram of each one before playing it.","Con las cinco notas, a tempo":"With the five notes, in time","La escala de la banda":"The band scale","Si\u266D mayor de concierto":"Concert B\u266D major","Si\u266D de concierto":"Concert B\u266D","Las bandas afinan y calientan en Si\u266D mayor de concierto. Tu trompeta est\xE1 en Si\u266D: para ti esa escala se escribe empezando en Do.":"Bands tune and warm up in concert B\u266D major. Your trumpet is in B\u266D: for you that scale is written starting on C.","Escala de la banda":"Band scale","Redonda: 4 pulsos. Blanca: 2. Negra: 1. Corchea: medio pulso. Un puntillo suma la mitad. Para las corcheas usa un picado suave con la lengua: \xABtu-tu\xBB.":"Whole note: 4 beats. Half note: 2. Quarter note: 1. Eighth note: half a beat. A dot adds half. For eighth notes use soft tonguing: \u201Ctu-tu\u201D.","Picado suave":"Soft tonguing","Registro agudo":"High register","M\xE1s arriba sin apretar":"Higher without squeezing","Subir de registro":"Going up a register","Aire, no fuerza":"Air, not force","Para subir, acelera el aire y estrecha un poco la apertura de los labios. No aprietes la boquilla contra la boca.":"To go up, speed up the air and narrow the opening of your lips a little. Don't press the mouthpiece against your mouth.","Escala en terceras":"Scale in thirds","Notas agudas":"High notes","Escalas y arpegios":"Scales and arpeggios","T\xE9cnica de banda":"Band technique",Escalas:"Scales","Otra tonalidad":"Another key","Muchas obras de banda est\xE1n en Mi\u266D y Fa de concierto. Practicamos la escala de F escrita y su arpegio.":"Many band pieces are in concert E\u266D and F. We practise the written F scale and its arpeggio.","Escala de F":"F scale",Arpegio:"Arpeggio","T\xF3nica, tercera y quinta":"Root, third and fifth","Afinar en banda":"Tuning in a band","Terceras, quintas y expresi\xF3n":"Thirds, fifths and expression","Afinar dentro del acorde":"Tuning inside the chord","No basta con el afinador":"The tuner is not enough","En un acorde, la tercera mayor suena mejor unos 14 cents m\xE1s baja que en el afinador, y la quinta unos 2 cents m\xE1s alta. Lo practicar\xE1s en \xABEstudio \u2192 Afinar en acorde\xBB.":"In a chord, the major third sounds best about 14 cents lower than on the tuner, and the fifth about 2 cents higher. You will practise it in \u201CPractice \u2192 Chord tuning\u201D.","Tu mapa de afinaci\xF3n":"Your tuning map","Cada vez que tocas, la app apunta si cada nota te sale alta o baja. M\xEDralo en \xABEstudio \u2192 Mapa de afinaci\xF3n\xBB y trabaja tus notas d\xE9biles con notas tenidas.":"Every time you play, the app notes whether each note comes out sharp or flat. See it in \u201CPractice \u2192 Tuning map\u201D and work on your weak notes with long tones.","Expresi\xF3n en menor":"Expression in minor","Toma aire abajo, sin subir los hombros, y su\xE9ltalo con una columna constante. El metal suena con aire, no con presi\xF3n de labios.":"Breathe in low, without raising your shoulders, and let it out in a steady column. Brass sounds with air, not with lip pressure.","El zumbido":"The buzz","Unos minutos de zumbido con la boquilla sola fortalecen los labios y afinan el o\xEDdo. Imita notas largas y glissandos suaves.":"A few minutes buzzing on the mouthpiece alone strengthen the lips and tune the ear. Imitate long notes and gentle glissandos.","Picado y ligado":"Tonguing and slurring","Pica con la lengua como en \xABtu\xBB. En el ligado entre arm\xF3nicos, usa el aire y una s\xEDlaba que se cierra (\xABta-a-i\xBB) sin volver a picar.":"Tongue as in \u201Ctu\u201D. When slurring between harmonics, use the air and a closing syllable (\u201Cta-a-i\u201D) without tonguing again.",Flexibilidad:"Flexibility","Cambia de arm\xF3nico sin mover los pistones (o la vara). Empieza con dos notas vecinas y ampl\xEDa poco a poco.":"Change harmonic without moving the valves (or the slide). Start with two neighbouring notes and widen little by little.","El registro agudo":"The high register","M\xE1s velocidad de aire y apertura m\xE1s peque\xF1a, no m\xE1s presi\xF3n de la boquilla. Descansa tanto como tocas.":"More air speed and a smaller aperture, not more mouthpiece pressure. Rest as much as you play.","Las notas con 1.\xAA y 3.\xAA bomba juntas salen altas: corr\xEDgelas con la bomba o la vara. El o\xEDdo manda.":"Notes using the 1st and 3rd valves together come out sharp: correct them with the slide. The ear rules.",Resistencia:"Endurance","Toca en bloques cortos con descansos. Los labios se cansan antes de lo que parece: cu\xEDdalos para que no se resientan.":"Play in short blocks with rests. Lips tire sooner than you think: look after them so they don't suffer.","Escalas de memoria":"Scales from memory","Las escalas en todas las tonalidades son tu vocabulario. T\xF3calas de memoria, ligadas y picadas.":"Scales in every key are your vocabulary. Play them from memory, slurred and tongued.","Doble y triple picado":"Double and triple tonguing","Alterna \xABtu-ku\xBB (doble) o \xABtu-tu-ku\xBB (triple) para pasajes r\xE1pidos. Practica la \xABku\xBB sola hasta que suene clara.":"Alternate \u201Ctu-ku\u201D (double) or \u201Ctu-tu-ku\u201D (triple) for fast passages. Practise \u201Cku\u201D on its own until it sounds clear.","Ondulaci\xF3n suave con la mand\xEDbula o la mano. En la banda se usa poco y siempre con gusto: escucha a tu secci\xF3n.":"A gentle wave with the jaw or the hand. In a band it is used sparingly and always with taste: listen to your section.","Din\xE1micas extremas":"Extreme dynamics","En pp el aire sigue movi\xE9ndose; en ff, abre el sonido sin romperlo. Practica crescendos largos en notas tenidas.":"In pp the air keeps moving; in ff, open the sound without breaking it. Practise long crescendos on long tones.",Sordinas:"Mutes","La sordina cambia el color y la afinaci\xF3n. Pru\xE9bala antes del ensayo y ajusta la bomba general si hace falta.":"A mute changes the colour and the tuning. Try it before the rehearsal and adjust the main slide if needed.","El Arban y los estudios de Clarke trabajan flexibilidad y dedos. Uno por semana, lento y perfecto antes que r\xE1pido.":"Arban and the Clarke studies work on flexibility and fingers. One a week, slow and perfect before fast.","Empasta con tu secci\xF3n: mismo sonido, mismas articulaciones y mismos finales de nota.":"Blend with your section: the same sound, the same articulations and the same note endings.","Antes de tocar, mira armadura, comp\xE1s y pasajes dif\xEDciles. Al tocar, mant\xE9n el pulso aunque falles notas.":"Before playing, look at the key signature, time signature and difficult passages. While playing, keep the pulse even if you miss notes.","Gr\xE1bate y esc\xFAchate. Decide d\xF3nde respirar y descansar: un solo largo es tambi\xE9n una carrera de fondo.":"Record yourself and listen. Decide where to breathe and rest: a long solo is also a long-distance race.","Conoce tu clarinete":"Get to know your clarinet","Coge aire profundo, con el abdomen, sin subir los hombros. Mant\xE9n la columna de aire constante: un sonido estable sale de un aire estable.":"Take a deep breath, from the belly, without raising your shoulders. Keep the air column steady: a steady sound comes from steady air.","Comisuras firmes y labios relajados alrededor de la boquilla, la ca\xF1a o la embocadura. No muerdas: si el sonido sale alto y estrecho, afloja la mand\xEDbula.":"Firm corners and relaxed lips around the mouthpiece, the reed or the lip plate. Don't bite: if the sound comes out sharp and thin, loosen your jaw.","Empezamos por Sol, Fa, Mi (notas escritas). El diagrama te muestra qu\xE9 pulsar en cada una.":"We start with G, F, E (written notes). The diagram shows you what to press for each one.","Clarinete en Si\u266D":"Clarinet in B\u266D","Cuando lees Do, suena Si\u266D: un tono m\xE1s grave. En tiempos de Mozart hab\xEDa clarinetes en Do, en Si\u266D y en La; en la banda se impuso el de Si\u266D, c\xF3modo en sus tonalidades con bemoles.":"When you read C, B\u266D sounds: a tone lower. In Mozart's time there were clarinets in C, B\u266D and A; in bands the B\u266D one won, comfortable in its flat keys.","Sacando un poco el barrilete (o el cuerpo superior) baja la afinaci\xF3n; meti\xE9ndolo, sube. El aire caliente sube la afinaci\xF3n: afina despu\xE9s de unos minutos tocando, no en fr\xEDo. Y vuelve a comprobarla en mitad del ensayo.":"Pulling the barrel (or the upper joint) out a little lowers the pitch; pushing it in raises it. Warm air raises the pitch: tune after a few minutes of playing, not cold. And check again in the middle of the rehearsal.","A\xF1adimos Re y Do. Mira el diagrama de cada una antes de tocarla.":"We add D and C. Look at the diagram of each one before playing it.","Las bandas afinan y calientan en Si\u266D mayor de concierto. Tu clarinete est\xE1 en Si\u266D: para ti esa escala se escribe empezando en Do.":"Bands tune and warm up in concert B\u266D major. Your clarinet is in B\u266D: for you that scale is written starting on C.","Para subir, usa la llave de octava o registro, acelera el aire y no muerdas. El agudo sale con aire r\xE1pido, no con presi\xF3n.":"To go up, use the octave or register key, speed up the air and don't bite. The high notes come from fast air, not from pressure.","Toma aire por la boca, abajo, como si llenaras la tripa, sin subir los hombros. Una columna de aire firme y constante es la base de un buen sonido.":"Breathe in through your mouth, low, as if filling your belly, without raising your shoulders. A firm, steady column of air is the basis of a good sound.","Cada d\xEDa, unas notas largas de 8 pulsos: empieza suave, crece y vuelve. Escucha que el sonido no tiemble ni cambie de afinaci\xF3n.":"Every day, some long notes of 8 beats: start soft, grow and come back. Listen that the sound doesn't shake or change pitch.","Pica con la punta de la lengua, como diciendo \xABtu\xBB. En lo ligado la lengua no se mueve y los dedos cambian a la vez, justo a tiempo.":"Tongue with the tip of your tongue, as if saying \u201Ctu\u201D. In slurred passages the tongue doesn't move and the fingers change together, right on time.","Dedos r\xE1pidos y relajados":"Fast, relaxed fingers","Los dedos, cerca de las llaves y curvos. Sube la velocidad con el metr\xF3nomo de 4 en 4: si se tensan, vuelve atr\xE1s.":"Fingers close to the keys and curved. Raise the speed with the metronome 4 at a time: if they tense up, go back.","Para subir, m\xE1s velocidad de aire y la embocadura estable, sin morder. Practica saltos de octava lentos y afinados.":"To go up, more air speed and a stable embouchure, without biting. Practise slow, in-tune octave leaps.","Cada instrumento tiene notas que tienden a salir altas o bajas. Usa el mapa de afinaci\xF3n y corrige con la embocadura y el aire.":"Every instrument has notes that tend to come out sharp or flat. Use the tuning map and correct with the embouchure and the air.","Matices sin desafinar":"Dynamics without going out of tune","En piano el sonido tiende a bajar y en forte a subir. Mant\xE9n el aire apoyado en los dos extremos.":"In piano the sound tends to go flat and in forte sharp. Keep the air supported at both extremes.","Las escalas en todas las tonalidades son el vocabulario del m\xFAsico. T\xF3calas de memoria, ligadas y picadas.":"Scales in every key are a musician's vocabulary. Play them from memory, slurred and tongued.","Una ondulaci\xF3n suave del sonido con el aire (diafragma) o la mand\xEDbula, seg\xFAn el instrumento. Empieza lento y a tempo: 4 ondas por pulso.":"A gentle wave in the sound made with the air (diaphragm) or the jaw, depending on the instrument. Start slow and in time: 4 waves per beat.","Doble picado":"Double tonguing","Alterna \xABtu-ku\xBB para picar muy r\xE1pido. Practica solo la s\xEDlaba \xABku\xBB hasta que suene igual de clara que \xABtu\xBB.":"Alternate \u201Ctu-ku\u201D to tongue very fast. Practise just the \u201Cku\u201D syllable until it sounds as clear as \u201Ctu\u201D.","Prepara pp y ff con notas tenidas. El sonido debe seguir siendo bonito y afinado en los dos extremos.":"Prepare pp and ff with long tones. The sound must stay beautiful and in tune at both extremes.","Posiciones alternativas":"Alternative fingerings","Muchas notas tienen digitaciones alternativas que hacen m\xE1s f\xE1ciles los pasajes r\xE1pidos o afinan mejor. Cons\xFAltalas en un buen m\xE9todo.":"Many notes have alternative fingerings that make fast passages easier or tune better. Look them up in a good method.","Los estudios (Klos\xE9, Rubank, Berbiguier\u2026) trabajan un problema concreto. Toca uno cada semana, lento y perfecto antes que r\xE1pido.":"Studies (Klos\xE9, Rubank, Berbiguier\u2026) work on one specific problem. Play one a week, slow and perfect before fast.","En la banda tu sonido debe empastar con el de tus compa\xF1eros: escucha a quien toca la misma voz y aj\xFAstate a \xE9l.":"In a band your sound must blend with your colleagues': listen to whoever plays your part and match them.","Antes de tocar, mira la armadura, el comp\xE1s y los pasajes dif\xEDciles. Al tocar, mant\xE9n el pulso aunque falles notas.":"Before playing, look at the key signature, the time signature and the difficult passages. While playing, keep the pulse even if you miss notes.","Gr\xE1bate, esc\xFAchate y corrige. Decide d\xF3nde respirar y marca los matices en la partitura antes del ensayo.":"Record yourself, listen and correct. Decide where to breathe and mark the dynamics in the score before the rehearsal.","Conoce tu saxof\xF3n alto":"Get to know your alto sax","Empezamos por Si, La, Sol (notas escritas). El diagrama te muestra qu\xE9 pulsar en cada una.":"We start with B, A, G (written notes). The diagram shows you what to press for each one.","Saxo alto en Mi\u266D":"Alto sax in E\u266D","Cuando lees Do, suena Mi\u266D: una sexta m\xE1s grave. Adolphe Sax cre\xF3 la familia en dos grupos, Si\u266D (soprano y tenor) y Mi\u266D (alto y bar\xEDtono), todos con los mismos dedos.":"When you read C, E\u266D sounds: a sixth lower. Adolphe Sax created the family in two groups, B\u266D (soprano and tenor) and E\u266D (alto and baritone), all with the same fingers.","Moviendo la boquilla en el tudel: metida sube la afinaci\xF3n, sacada la baja. El aire caliente sube la afinaci\xF3n: afina despu\xE9s de unos minutos tocando, no en fr\xEDo. Y vuelve a comprobarla en mitad del ensayo.":"Moving the mouthpiece on the neck: pushed in raises the pitch, pulled out lowers it. Warm air raises the pitch: tune after a few minutes of playing, not cold. And check again in the middle of the rehearsal.","Tu instrumento est\xE1 en Mi\u266D (suena una sexta m\xE1s grave de lo escrito): para que suene Si\u266D t\xFA lees y tocas Sol.":"Your instrument is in E\u266D (it sounds a sixth lower than written): for B\u266D to sound, you read and play G.","A\xF1adimos Do y Re. Mira el diagrama de cada una antes de tocarla.":"We add C and D. Look at the diagram of each one before playing it.","Las bandas afinan y calientan en Si\u266D mayor de concierto. Tu saxof\xF3n alto est\xE1 en Mi\u266D: para ti esa escala se escribe empezando en Sol.":"Bands tune and warm up in concert B\u266D major. Your alto sax is in E\u266D: for you that scale is written starting on G.","Muchas obras de banda est\xE1n en Mi\u266D y Fa de concierto. Practicamos la escala de D escrita y su arpegio.":"Many band pieces are in concert E\u266D and F. We practise the written D scale and its arpeggio.","Escala de D":"D scale","Conoce tu saxof\xF3n tenor":"Get to know your tenor sax","Saxo tenor en Si\u266D":"Tenor sax in B\u266D","Cuando lees Do, suena Si\u266D una octava y un tono m\xE1s grave. Usa los mismos dedos que el alto: por eso los saxofonistas cambian de uno a otro con facilidad.":"When you read C, B\u266D sounds an octave and a tone lower. It uses the same fingers as the alto: that is why saxophonists switch from one to the other easily.","Moviendo la boquilla en el tudel: metida sube, sacada baja. El aire caliente sube la afinaci\xF3n: afina despu\xE9s de unos minutos tocando, no en fr\xEDo. Y vuelve a comprobarla en mitad del ensayo.":"Moving the mouthpiece on the neck: pushed in raises it, pulled out lowers it. Warm air raises the pitch: tune after a few minutes of playing, not cold. And check again in the middle of the rehearsal.","Tu instrumento est\xE1 en Si\u266D (suena una novena m\xE1s grave de lo escrito): para que suene Si\u266D t\xFA lees y tocas Do.":"Your instrument is in B\u266D (it sounds a ninth lower than written): for B\u266D to sound, you read and play C.","Las bandas afinan y calientan en Si\u266D mayor de concierto. Tu saxof\xF3n tenor est\xE1 en Si\u266D: para ti esa escala se escribe empezando en Do.":"Bands tune and warm up in concert B\u266D major. Your tenor sax is in B\u266D: for you that scale is written starting on C.","Conoce tu saxof\xF3n bar\xEDtono":"Get to know your baritone sax","Saxo bar\xEDtono en Mi\u266D":"Baritone sax in E\u266D","Cuando lees Do, suena Mi\u266D m\xE1s de una octava por debajo. Es el alto en grande: mismos dedos, una octava m\xE1s grave.":"When you read C, E\u266D sounds more than an octave below. It is the alto made big: the same fingers, an octave lower.","Tu instrumento est\xE1 en Mi\u266D (suena una octava y una sexta m\xE1s grave de lo escrito): para que suene Si\u266D t\xFA lees y tocas Sol.":"Your instrument is in E\u266D (it sounds an octave and a sixth lower than written): for B\u266D to sound, you read and play G.","Las bandas afinan y calientan en Si\u266D mayor de concierto. Tu saxof\xF3n bar\xEDtono est\xE1 en Mi\u266D: para ti esa escala se escribe empezando en Sol.":"Bands tune and warm up in concert B\u266D major. Your baritone sax is in E\u266D: for you that scale is written starting on G.","Conoce tu flauta":"Get to know your flute","Flauta en Do":"Flute in C","La flauta suena lo que lees: cuando la banda afina al Si\u266D de concierto, t\xFA tocas Si\u266D. (El flaut\xEDn, en cambio, suena una octava m\xE1s agudo.)":"The flute sounds what you read: when the band tunes to concert B\u266D, you play B\u266D. (The piccolo, on the other hand, sounds an octave higher.)","Sacando un poco la cabeza baja la afinaci\xF3n; meti\xE9ndola, sube. Tapar m\xE1s o menos el agujero con el labio tambi\xE9n cambia la nota. El aire caliente sube la afinaci\xF3n: afina despu\xE9s de unos minutos tocando, no en fr\xEDo. Y vuelve a comprobarla en mitad del ensayo.":"Pulling the head joint out a little lowers the pitch; pushing it in raises it. Covering more or less of the hole with your lip also changes the note. Warm air raises the pitch: tune after a few minutes of playing, not cold. And check again in the middle of the rehearsal.","Tu instrumento est\xE1 en Do (suena lo que lees): para que suene Si\u266D t\xFA lees y tocas Si\u266D.":"Your instrument is in C (it sounds what you read): for B\u266D to sound, you read and play B\u266D.","Las bandas afinan y calientan en Si\u266D mayor de concierto. Tu instrumento est\xE1 en Do, as\xED que para ti es Si\u266D mayor tal cual.":"Bands tune and warm up in concert B\u266D major. Your instrument is in C, so for you it is simply B\u266D major.","Para subir a la segunda octava casi no cambian los dedos: sopla m\xE1s r\xE1pido, acerca un poco los labios al bisel y dirige el aire algo m\xE1s arriba. Sin forzar.":"To go up to the second octave the fingers hardly change: blow faster, bring your lips a little closer to the edge and aim the air slightly higher. Without forcing.","Conoce tu oboe":"Get to know your oboe","Oboe en Do":"Oboe in C","El oboe suena lo que lees. En la orquesta es quien da el La para afinar: su sonido es estable y se oye por encima de todos.":"The oboe sounds what you read. In the orchestra it gives the A for tuning: its sound is steady and is heard above everyone.","Sobre todo con la ca\xF1a: metida m\xE1s a fondo sube la afinaci\xF3n. La ca\xF1a y c\xF3mo la sujetas con los labios cambian mucho la nota. El aire caliente sube la afinaci\xF3n: afina despu\xE9s de unos minutos tocando, no en fr\xEDo. Y vuelve a comprobarla en mitad del ensayo.":"Mostly with the reed: pushed further in raises the pitch. The reed and how you hold it with your lips change the note a lot. Warm air raises the pitch: tune after a few minutes of playing, not cold. And check again in the middle of the rehearsal.","\xBFQu\xE9 instrumento da el La para afinar a la orquesta?":"Which instrument gives the orchestra the A to tune to?","El oboe: su sonido es estable y penetrante, y casi siempre estaba en las orquestas.":"The oboe: its sound is steady and penetrating, and it was almost always in orchestras.","A\xF1adimos Mi y Re. Mira el diagrama de cada una antes de tocarla.":"We add E and D. Look at the diagram of each one before playing it.","Conoce tu requinto":"Get to know your E\u266D clarinet","Requinto en Mi\u266D":"E\u266D clarinet","Es el clarinete peque\xF1o: cuando lees Do, suena Mi\u266D, una tercera menor m\xE1s aguda. Lleva los mismos dedos que el clarinete en Si\u266D.":"It is the small clarinet: when you read C, E\u266D sounds, a minor third higher. It uses the same fingers as the B\u266D clarinet.","Con el barrilete: sacarlo un poco baja la afinaci\xF3n. En el agudo tiende a subir: no muerdas la ca\xF1a. El aire caliente sube la afinaci\xF3n: afina despu\xE9s de unos minutos tocando, no en fr\xEDo. Y vuelve a comprobarla en mitad del ensayo.":"With the barrel: pulling it out a little lowers the pitch. In the high register it tends to go sharp: don't bite the reed. Warm air raises the pitch: tune after a few minutes of playing, not cold. And check again in the middle of the rehearsal.","Tu instrumento est\xE1 en Mi\u266D (suena una tercera menor m\xE1s aguda de lo escrito): para que suene Si\u266D t\xFA lees y tocas Sol.":"Your instrument is in E\u266D (it sounds a minor third higher than written): for B\u266D to sound, you read and play G.","Las bandas afinan y calientan en Si\u266D mayor de concierto. Tu requinto est\xE1 en Mi\u266D: para ti esa escala se escribe empezando en Sol.":"Bands tune and warm up in concert B\u266D major. Your E\u266D clarinet is in E\u266D: for you that scale is written starting on G.","Conoce tu clarinete bajo":"Get to know your bass clarinet","Clarinete bajo en Si\u266D":"Bass clarinet in B\u266D","Se escribe en clave de sol como el clarinete y suena una novena m\xE1s grave: cuando lees Do, suena Si\u266D una octava y un tono por debajo. Mismos dedos que el clarinete.":"It is written in treble clef like the clarinet and sounds a ninth lower: when you read C, B\u266D sounds an octave and a tone below. The same fingers as the clarinet.","Moviendo la boquilla o el tudel: sacarlo baja la afinaci\xF3n. Necesita mucho aire y una embocadura m\xE1s relajada que el clarinete. El aire caliente sube la afinaci\xF3n: afina despu\xE9s de unos minutos tocando, no en fr\xEDo. Y vuelve a comprobarla en mitad del ensayo.":"Moving the mouthpiece or the neck: pulling it out lowers the pitch. It needs lots of air and a more relaxed embouchure than the clarinet. Warm air raises the pitch: tune after a few minutes of playing, not cold. And check again in the middle of the rehearsal.","Las bandas afinan y calientan en Si\u266D mayor de concierto. Tu clarinete bajo est\xE1 en Si\u266D: para ti esa escala se escribe empezando en Do.":"Bands tune and warm up in concert B\u266D major. Your bass clarinet is in B\u266D: for you that scale is written starting on C.","Conoce tu flaut\xEDn":"Get to know your piccolo","Flaut\xEDn en Do":"Piccolo in C","Se escribe como la flauta pero suena una octava m\xE1s aguda, para no llenar la partitura de l\xEDneas adicionales. Mismos dedos que la flauta.":"It is written like the flute but sounds an octave higher, so the score isn't full of ledger lines. The same fingers as the flute.","Sacando un poco la cabeza baja la afinaci\xF3n. Se oye much\xEDsimo: escucha a la banda y toca m\xE1s suave de lo que crees. El aire caliente sube la afinaci\xF3n: afina despu\xE9s de unos minutos tocando, no en fr\xEDo. Y vuelve a comprobarla en mitad del ensayo.":"Pulling the head joint out a little lowers the pitch. It is heard a lot: listen to the band and play softer than you think. Warm air raises the pitch: tune after a few minutes of playing, not cold. And check again in the middle of the rehearsal.","Tu instrumento est\xE1 en Do (suena una octava m\xE1s aguda, pero la nota es la misma): para que suene Si\u266D t\xFA lees y tocas Si\u266D.":"Your instrument is in C (it sounds an octave higher, but the note is the same): for B\u266D to sound, you read and play B\u266D.","Las bandas afinan y calientan en Si\u266D mayor de concierto. Tu flaut\xEDn suena una octava m\xE1s aguda de lo escrito, pero la escala se escribe igual: Si\u266D mayor.":"Bands tune and warm up in concert B\u266D major. Your piccolo sounds an octave higher than written, but the scale is written the same: B\u266D major.","Conoce tu saxof\xF3n soprano":"Get to know your soprano sax","Saxo soprano en Si\u266D":"Soprano sax in B\u266D","Cuando lees Do, suena Si\u266D: un tono m\xE1s grave. Usa los mismos dedos que el resto de saxos.":"When you read C, B\u266D sounds: a tone lower. It uses the same fingers as the other saxes.","Moviendo la boquilla: metida sube, sacada baja. Es el saxo m\xE1s dif\xEDcil de afinar: escucha mucho y usa el mapa de afinaci\xF3n. El aire caliente sube la afinaci\xF3n: afina despu\xE9s de unos minutos tocando, no en fr\xEDo. Y vuelve a comprobarla en mitad del ensayo.":"Moving the mouthpiece: pushed in raises it, pulled out lowers it. It is the hardest sax to keep in tune: listen a lot and use the tuning map. Warm air raises the pitch: tune after a few minutes of playing, not cold. And check again in the middle of the rehearsal.","Las bandas afinan y calientan en Si\u266D mayor de concierto. Tu saxof\xF3n soprano est\xE1 en Si\u266D: para ti esa escala se escribe empezando en Do.":"Bands tune and warm up in concert B\u266D major. Your soprano sax is in B\u266D: for you that scale is written starting on C.","Conoce tu fliscorno":"Get to know your flugelhorn","Fliscorno en Si\u266D":"Flugelhorn in B\u266D","Se toca y se lee igual que la trompeta (mismos pistones), pero su tubo es m\xE1s ancho y suena m\xE1s redondo y dulce. Cuando lees Do, suena Si\u266D.":"It is played and read like the trumpet (same valves), but its tube is wider and it sounds rounder and sweeter. When you read C, B\u266D sounds.","Con la bomba de afinaci\xF3n: sacarla baja la afinaci\xF3n. En Re y Do\u266F graves, saca un poco la del 3.er pist\xF3n. El aire caliente sube la afinaci\xF3n: afina despu\xE9s de unos minutos tocando, no en fr\xEDo. Y vuelve a comprobarla en mitad del ensayo.":"With the tuning slide: pulling it out lowers the pitch. On low D and C\u266F, pull the 3rd valve slide out a little. Warm air raises the pitch: tune after a few minutes of playing, not cold. And check again in the middle of the rehearsal.","Las bandas afinan y calientan en Si\u266D mayor de concierto. Tu fliscorno est\xE1 en Si\u266D: para ti esa escala se escribe empezando en Do.":"Bands tune and warm up in concert B\u266D major. Your flugelhorn is in B\u266D: for you that scale is written starting on C.","Conoce tu trompa":"Get to know your horn","Trompa en Fa":"Horn in F","Cuando lees Do, suena Fa: una quinta m\xE1s grave. Por eso, cuando la banda afina al Si\u266D de concierto, t\xFA tocas tu Fa.":"When you read C, F sounds: a fifth lower. That is why, when the band tunes to concert B\u266D, you play your F.","Con la bomba general, y tambi\xE9n con la mano derecha dentro del pabell\xF3n: cuanto m\xE1s la cierras, m\xE1s baja la nota. El aire caliente sube la afinaci\xF3n: afina despu\xE9s de unos minutos tocando, no en fr\xEDo. Y vuelve a comprobarla en mitad del ensayo.":"With the main slide, and also with your right hand inside the bell: the more you close it, the lower the note. Warm air raises the pitch: tune after a few minutes of playing, not cold. And check again in the middle of the rehearsal.","Tu instrumento est\xE1 en Fa (suena una quinta m\xE1s grave de lo escrito): para que suene Si\u266D t\xFA lees y tocas Fa.":"Your instrument is in F (it sounds a fifth lower than written): for B\u266D to sound, you read and play F.","Las bandas afinan y calientan en Si\u266D mayor de concierto. Tu trompa est\xE1 en Fa: para ti esa escala se escribe empezando en Fa.":"Bands tune and warm up in concert B\u266D major. Your horn is in F: for you that scale is written starting on F.","Muchas obras de banda est\xE1n en Mi\u266D y Fa de concierto. Practicamos la escala de C escrita y su arpegio.":"Many band pieces are in concert E\u266D and F. We practise the written C scale and its arpeggio.","Escala de C":"C scale","Conoce tu tromb\xF3n":"Get to know your trombone","Empezamos por Fa, Mi\u266D, Re (notas escritas). El diagrama te muestra qu\xE9 pulsar en cada una.":"We start with F, E\u266D, D (written notes). The diagram shows you what to press for each one.","Tromb\xF3n en Do":"Trombone in C","El tromb\xF3n lee en clave de fa y suena lo que lees: cuando la banda afina al Si\u266D, t\xFA tocas Si\u266D en 1.\xAA posici\xF3n, con la vara cerrada.":"The trombone reads in bass clef and sounds what you read: when the band tunes to B\u266D, you play B\u266D in 1st position, with the slide closed.","Siete posiciones":"Seven positions","Cada posici\xF3n de la vara baja medio tono. Las posiciones no son marcas fijas: afinas con el o\xEDdo, moviendo la vara un poco hacia dentro o hacia fuera.":"Each slide position lowers the note a semitone. Positions are not fixed marks: you tune by ear, moving the slide slightly in or out.","Con la bomba de afinaci\xF3n de la campana, con la vara en 1.\xAA. El aire caliente sube la afinaci\xF3n: afina despu\xE9s de unos minutos tocando, no en fr\xEDo. Y vuelve a comprobarla en mitad del ensayo.":"With the tuning slide on the bell section, with the slide in 1st position. Warm air raises the pitch: tune after a few minutes of playing, not cold. And check again in the middle of the rehearsal.","\xBFQu\xE9 pasa al alargar la vara una posici\xF3n?":"What happens when you extend the slide by one position?","La nota sube medio tono":"The note goes up a semitone","La nota baja medio tono":"The note goes down a semitone","Suena m\xE1s fuerte":"It sounds louder","No cambia":"It doesn't change","Baja medio tono: el tubo es m\xE1s largo.":"It goes down a semitone: the tube is longer.","A\xF1adimos Do y Si\u266D. Mira el diagrama de cada una antes de tocarla.":"We add C and B\u266D. Look at the diagram of each one before playing it.","Muchas obras de banda est\xE1n en Mi\u266D y Fa de concierto. Practicamos la escala de Eb escrita y su arpegio.":"Many band pieces are in concert E\u266D and F. We practise the written E\u266D scale and its arpeggio.","Escala de Eb":"E\u266D scale","Conoce tu bombardino":"Get to know your euphonium","Bombardino en Si\u266D":"Euphonium in B\u266D","En las bandas espa\xF1olas suele leerse en clave de sol en Si\u266D: los mismos pistones que la trompeta y suena una novena m\xE1s grave. (Si lees en clave de fa, suena lo que lees.)":"In Spanish bands it is usually read in treble clef in B\u266D: the same valves as the trumpet, sounding a ninth lower. (If you read bass clef, it sounds what you read.)","Con la bomba general: sacarla baja la afinaci\xF3n. Necesita aire abundante y lento. El aire caliente sube la afinaci\xF3n: afina despu\xE9s de unos minutos tocando, no en fr\xEDo. Y vuelve a comprobarla en mitad del ensayo.":"With the main slide: pulling it out lowers the pitch. It needs plenty of slow air. Warm air raises the pitch: tune after a few minutes of playing, not cold. And check again in the middle of the rehearsal.","Tu instrumento est\xE1 en Si\u266D en clave de sol (suena una novena m\xE1s grave de lo escrito): para que suene Si\u266D t\xFA lees y tocas Do.":"Your instrument is in B\u266D in treble clef (it sounds a ninth lower than written): for B\u266D to sound, you read and play C.","Las bandas afinan y calientan en Si\u266D mayor de concierto. Tu bombardino est\xE1 en Si\u266D: para ti esa escala se escribe empezando en Do.":"Bands tune and warm up in concert B\u266D major. Your euphonium is in B\u266D: for you that scale is written starting on C.","Conoce tu tuba":"Get to know your tuba","Empezamos por Si\u266D, Do, Re (notas escritas). El diagrama te muestra qu\xE9 pulsar en cada una.":"We start with B\u266D, C, D (written notes). The diagram shows you what to press for each one.","Tuba en Do (clave de fa)":"Tuba in C (bass clef)","En las bandas la tuba lee en clave de fa y suena lo que lees, aunque el instrumento sea en Si\u266D o Fa. Cuando la banda afina al Si\u266D, t\xFA tocas Si\u266D.":"In bands the tuba reads bass clef and sounds what you read, even if the instrument is in B\u266D or F. When the band tunes to B\u266D, you play B\u266D.","El cimiento de la banda":"The foundation of the band","La tuba sostiene la afinaci\xF3n de todos: si el bajo est\xE1 afinado, el acorde entero suena mejor.":"The tuba holds everyone's tuning: if the bass is in tune, the whole chord sounds better.","Con la bomba general. En el grave el aire debe ser lento y muy abundante. El aire caliente sube la afinaci\xF3n: afina despu\xE9s de unos minutos tocando, no en fr\xEDo. Y vuelve a comprobarla en mitad del ensayo.":"With the main slide. In the low register the air must be slow and very plentiful. Warm air raises the pitch: tune after a few minutes of playing, not cold. And check again in the middle of the rehearsal.","Tu instrumento est\xE1 en Do en clave de fa (suena lo que lees): para que suene Si\u266D t\xFA lees y tocas Si\u266D.":"Your instrument is in C in bass clef (it sounds what you read): for B\u266D to sound, you read and play B\u266D.","A\xF1adimos Mi\u266D y Fa. Mira el diagrama de cada una antes de tocarla.":"We add E\u266D and F. Look at the diagram of each one before playing it.","Tus tres primeras notas":"Your first three notes","\xA1Hola, flautista!":"Hello, recorder player!","C\xF3mo se coge":"How to hold it","La mano izquierda va arriba, cerca de la boquilla, y la derecha abajo. El pulgar izquierdo tapa el agujerito de detr\xE1s.":"The left hand goes on top, near the mouthpiece, and the right hand below. The left thumb covers the little hole at the back.","Sopla suave":"Blow gently","Sopla despacito, como si dijeras \xABtuuu\xBB para apagar una vela sin que se caiga la cera. Si la flauta pita, est\xE1s soplando demasiado fuerte.":"Blow very gently, as if saying \u201Ctuuu\u201D to blow out a candle without spilling the wax. If the recorder squeaks, you are blowing too hard.","Tu primera nota: Si":"Your first note: B","Tapa el agujero de detr\xE1s con el pulgar y el primer agujero con el dedo \xEDndice izquierdo. Usa la yema del dedo, que quede bien tapado.":"Cover the hole at the back with your thumb and the first hole with your left index finger. Use the pad of your finger so it is fully covered.","Deja el m\xF3vil cerca, en un sitio sin ruido. Cuando suene la nota correcta se pondr\xE1 verde. \xA1As\xED sabr\xE1s que lo haces bien!":"Put the phone close by, somewhere quiet. When the right note sounds it turns green. That way you'll know you're doing it right!","Tu flauta dulce":"Your recorder","La flauta del cole se llama flauta dulce soprano. Suena una octava m\xE1s aguda de lo que se escribe, para que la partitura sea f\xE1cil de leer.":"The school recorder is called a soprano recorder. It sounds an octave higher than written, so the score is easy to read.","Tapar bien":"Covering well","El secreto de la flauta es tapar los agujeros con la yema del dedo, sin dejar rendijas. Si una nota chilla o no sale, mira qu\xE9 dedo deja pasar el aire.":"The secret of the recorder is covering the holes with the pad of your finger, with no gaps. If a note squeaks or doesn't come out, check which finger is letting air through.","Afinar la flauta":"Tuning the recorder","Sacando un poquito la cabeza de la flauta (la parte de arriba) suena m\xE1s grave; meti\xE9ndola, m\xE1s aguda. As\xED todos los de clase suenan juntos.":"Pulling the head (the top part) out a little makes it sound lower; pushing it in, higher. That way everyone in class sounds together.","Si tu flauta pita muy fuerte, \xBFqu\xE9 haces?":"If your recorder squeaks very loudly, what do you do?","Soplar m\xE1s fuerte":"Blow harder","Soplar m\xE1s suave":"Blow more gently","Morder la boquilla":"Bite the mouthpiece","Tapar menos agujeros":"Cover fewer holes","Soplar m\xE1s suave: la flauta dulce necesita muy poco aire.":"Blow more gently: the recorder needs very little air.","La nota Si":"The note B","Pulgar y dedo 1":"Thumb and finger 1","A\xF1ade el dedo 2":"Add finger 2","Tres dedos de la mano izquierda":"Three fingers of the left hand","Do y Re agudos":"High C and D","M\xE1s arriba":"Higher","Do agudo":"High C","Pulgar detr\xE1s y solo el dedo 2 (el coraz\xF3n). \xA1Ojo! El dedo 1 se levanta.":"Thumb at the back and only finger 2 (the middle finger). Careful! Finger 1 comes off.","Re agudo":"High D","Ahora suelta tambi\xE9n el pulgar: solo el dedo 2 tapa su agujero. Sopla un poquito m\xE1s suave todav\xEDa.":"Now let go of the thumb too: only finger 2 covers its hole. Blow even a little more gently.","Arriba y abajo":"Up and down","Con Si, La, Sol y Re":"With B, A, G and D","El Himno de la alegr\xEDa":"The Ode to Joy","Una canci\xF3n famosa":"A famous song","Escribi\xF3 esta melod\xEDa hace unos 200 a\xF1os y hoy es el himno de Europa. \xA1Y ya la puedes tocar con las notas que sabes!":"He wrote this melody about 200 years ago and today it is the anthem of Europe. And you can already play it with the notes you know!","Notas largas y cortas":"Long and short notes","La negra dura un pulso; la blanca, dos. El puntito al lado de una nota la hace un poco m\xE1s larga.":"The quarter note lasts one beat; the half note, two. The little dot next to a note makes it a bit longer.",Calentamiento:"Warm-up","Himno de la alegr\xEDa":"Ode to Joy","La mano derecha":"The right hand","Mi y Re graves":"Low E and D",Bajamos:"Going down","Mi grave":"Low E","Tapa el pulgar y los tres agujeros de la mano izquierda, y con la derecha los agujeros 4 y 5 (\xEDndice y medio). Sopla muy suave: las notas graves piden poco aire.":"Cover the thumb and the three holes of the left hand, and with the right hand holes 4 and 5 (index and middle). Blow very gently: low notes need little air.","Re grave":"Low D","Igual que Mi, pero tapando tambi\xE9n el agujero 6. Si chilla, revisa que todos los dedos tapen bien.":"Like E, but also covering hole 6. If it squeaks, check that all your fingers cover well.","Mano derecha":"Right hand","La escalera":"The staircase","De Re a Re":"From D to D","Fa sostenido y Do grave":"F sharp and low C","La escala de Sol":"The G scale","Las \xFAltimas notas graves":"The last low notes","Fa sostenido":"F sharp","Mano izquierda entera y, en la derecha, los agujeros 5 y 6 (el 4 queda abierto).":"The whole left hand and, on the right, holes 5 and 6 (hole 4 stays open).","Do grave":"Low C","Todos los agujeros tapados, tambi\xE9n el 7. Es la nota m\xE1s dif\xEDcil: sopla muy despacito.":"Every hole covered, including 7. It is the hardest note: blow very slowly.","Hasta abajo del todo":"All the way down","Para tocar en todas las fiestas":"To play at every party","El Fa":"The F","Canciones en Do":"Songs in C","Fa natural":"F natural","Fa (flauta alemana)":"F (German recorder)","Pulgar y agujeros 1, 2, 3 y 4. Casi todas las flautas del colegio son \xABalemanas\xBB. Si la tuya pone una \xABB\xBB (barroca), el Fa es pulgar y 1-2-3-4-6-7: pregunta a tu profe.":"Thumb and holes 1, 2, 3 and 4. Almost all school recorders are \u201CGerman\u201D. If yours says \u201CB\u201D (baroque), F is thumb and 1-2-3-4-6-7: ask your teacher.","Entre Mi y Sol":"Between E and G","Himno de la alegr\xEDa en Do":"Ode to Joy in C","Ahora m\xE1s grave":"Now lower","El medio pulgar":"The half thumb","El truco del pulgar":"The thumb trick","Medio pulgar":"Half thumb","Para las notas agudas, el pulgar deja abierta una rendija: dobla un poco la punta del dedo para destapar solo la mitad del agujero.":"For the high notes, the thumb leaves a gap open: bend the tip of your thumb a little to uncover only half of the hole.","Mi agudo":"High E","Medio pulgar y los agujeros 1, 2, 3, 4 y 5. Sopla un poquito m\xE1s r\xE1pido que en las graves, pero sin pitar.":"Half thumb and holes 1, 2, 3, 4 and 5. Blow a little faster than for low notes, but without squeaking.","Con medio pulgar":"With half thumb","Canci\xF3n popular":"Folk song","Canci\xF3n popular francesa":"French folk song","Tus canciones favoritas":"Your favourite songs","\xA1Ya eres flautista!":"You're a recorder player now!","Tu concierto":"Your concert","Con todas las notas que sabes puedes tocar much\xEDsimas canciones. Gr\xE1bate y ens\xE9\xF1aselo a tu familia: en \xABEstudio\xBB puedes escucharte.":"With all the notes you know you can play lots of songs. Record yourself and show your family: in \u201CPractice\u201D you can listen to yourself.","Para Navidad":"For Christmas","Tus primeros acordes":"Your first chords","{Em} y {Am}: tu primera canci\xF3n hoy":"{Em} and {Am}: your first song today","{D}, {A} y {E}":"{D}, {A} and {E}","{G} y {C}":"{G} and {C}","{F} y {G}":"{F} and {G}","Conoce tu guitarra":"Get to know your guitar","Seis cuerdas":"Six strings","De grave a aguda: {E}, {A}, {D}, {G}, {B} y {E}. Se numeran al rev\xE9s: la 1.\xAA es la {E} aguda (la m\xE1s fina) y la 6.\xAA la {E} grave.":"From low to high: {E}, {A}, {D}, {G}, {B} and {E}. They are numbered the other way round: the 1st is the high {E} (the thinnest) and the 6th the low {E}.","Afina siempre antes":"Always tune first","Una guitarra desafinada suena mal aunque lo hagas todo bien. Usa el afinador de la pesta\xF1a Estudio cada vez que empieces.":"An out-of-tune guitar sounds bad even if you do everything right. Use the tuner in the Practice tab every time you start.","Las yemas duelen al principio":"Fingertips hurt at first","Es normal. Con 10 o 15 minutos al d\xEDa salen callos en dos o tres semanas y deja de doler. Mejor poco cada d\xEDa que mucho un d\xEDa.":"It's normal. With 10 or 15 minutes a day calluses form in two or three weeks and it stops hurting. Better a little every day than a lot one day.","Deja el m\xF3vil a medio metro. En los acordes, rasguea y deja sonar: cuando el acorde suene limpio, se pondr\xE1 verde.":"Put the phone half a metre away. For chords, strum and let it ring: when the chord sounds clean, it turns green.","Casi todas las cuerdas est\xE1n a una cuarta de la siguiente, salvo Sol-Si, que est\xE1n a una tercera. As\xED las formas de los acordes caben bajo la mano.":"Almost every string is a fourth from the next, except G-B, which are a third apart. That way chord shapes fit under the hand.","Suena una octava m\xE1s grave":"It sounds an octave lower","La guitarra se escribe una octava por encima de como suena, para no llenar la partitura de l\xEDneas adicionales. Por lo dem\xE1s est\xE1 en Do.":"Guitar is written an octave above how it sounds, so the score isn't full of ledger lines. Otherwise it is in C.","Afina cada vez":"Tune every time","Las cuerdas se destensan con el calor, la humedad y el uso. Afina siempre antes de tocar, empezando por la 5.\xAA cuerda: un La de 110 Hz, dos octavas por debajo del La 440 del diapas\xF3n.":"Strings go slack with heat, humidity and use. Always tune before playing, starting with the 5th string: an A at 110 Hz, two octaves below the A 440 of the tuning fork.","\xBFEntre qu\xE9 dos cuerdas el intervalo no es una cuarta?":"Between which two strings is the interval not a fourth?","Entre Sol y Si hay una tercera mayor; entre las dem\xE1s, cuartas.":"Between G and B there is a major third; between the others, fourths.","Cuerdas al aire":"Open strings","Pulsa cada cuerda sin pisar":"Pluck each string without pressing","Tu primer acorde: {Em}":"Your first chord: {Em}","{Em}: solo dos dedos":"{Em}: just two fingers","Dedos 2 y 3 en el traste 2 de las cuerdas 5 y 4. Rasguea las seis cuerdas de arriba abajo. Apoya la yema justo detr\xE1s del traste, no encima.":"Fingers 2 and 3 on fret 2 of strings 5 and 4. Strum all six strings from top to bottom. Put the fingertip just behind the fret, not on top of it.","{Am}: el primo de {Em}":"{Am}: {Em}'s cousin","Baja los dedos 2 y 3 una cuerda (cuerdas 4 y 3) y a\xF1ade el 1 en el traste 1 de la cuerda 2. No toques la 6.\xAA cuerda.":"Move fingers 2 and 3 down one string (strings 4 and 3) and add finger 1 on fret 1 of string 2. Don't play the 6th string.","Suena {Em}":"{Em} rings out","Pon los dedos, rasguea y deja sonar":"Place your fingers, strum and let it ring","{Em} y {Am}":"{Em} and {Am}","Cambia sin prisa":"Change without rushing","Balada en {Em}":"Ballad in {Em}","Tres acordes, decenas de canciones":"Three chords, dozens of songs","Tres acordes nuevos":"Three new chords","Tri\xE1ngulo con los dedos 1, 3 y 2 en las tres cuerdas agudas. Rasguea solo desde la 4.\xAA cuerda (Re) hacia abajo.":"A triangle with fingers 1, 3 and 2 on the three high strings. Strum only from the 4th string (D) down.","Los dedos 1, 2 y 3 en fila en el traste 2. Si no caben, incl\xEDnalos un poco. Rasguea desde la 5.\xAA cuerda.":"Fingers 1, 2 and 3 in a row on fret 2. If they don't fit, tilt them a little. Strum from the 5th string.","Es {Em} con el dedo 1 en el traste 1 de la 3.\xAA cuerda. F\xEDjate: el 2 y el 3 ya estaban.":"It is {Em} with finger 1 on fret 1 of the 3rd string. Notice: 2 and 3 were already there.","Dedos ancla":"Anchor fingers","Cuando cambies, busca el dedo que no se mueve o que solo se desliza. De {A} a {E} el dedo 1 se queda casi en el mismo sitio.":"When you change, look for the finger that doesn't move or only slides. From {A} to {E} finger 1 stays almost in the same place.","El cambio m\xE1s famoso":"The most famous change","Dos acordes, una canci\xF3n entera":"Two chords, a whole song","Con dedo ancla":"With an anchor finger","Los tres mosqueteros":"The Three Musketeers","{D}, {A} y {E} juntos":"{D}, {A} and {E} together","Los acordes de mil canciones":"The chords of a thousand songs","Dedo 2 en el traste 3 de la 6.\xAA, dedo 1 en el 2 de la 5.\xAA y dedo 3 en el 3 de la 1.\xAA. Suenan las seis cuerdas.":"Finger 2 on fret 3 of the 6th, finger 1 on fret 2 of the 5th and finger 3 on fret 3 of the 1st. All six strings ring.","Una escalera: dedo 3 en la 5.\xAA (traste 3), dedo 2 en la 4.\xAA (traste 2) y dedo 1 en la 2.\xAA (traste 1). No toques la 6.\xAA.":"A staircase: finger 3 on the 5th (fret 3), finger 2 on the 4th (fret 2) and finger 1 on the 2nd (fret 1). Don't play the 6th.","Despacio y limpio":"Slow and clean","Para cualquier cumplea\xF1os":"For any birthday","En tres por cuatro":"In three-four","Ritmo y s\xE9ptimas":"Rhythm and sevenths","Rasgueo con ganas":"Strumming with feeling","El p\xE9ndulo":"The pendulum","La mano no para de moverse arriba y abajo al ritmo, toques o no. Abajo en cada pulso, arriba entre pulsos. As\xED nunca pierdes el comp\xE1s.":"Your hand never stops moving up and down in time, whether you play or not. Down on every beat, up between beats. That way you never lose the bar.","El rasgueo de casi todo":"The strum for almost everything","Abajo, abajo-arriba, arriba-abajo-arriba (\u2193 \u2193\u2191 \u2191\u2193\u2191). Empieza con la mano suelta y la p\xFAa sujeta sin apretar.":"Down, down-up, up-down-up (\u2193 \u2193\u2191 \u2191\u2193\u2191). Start with a loose hand and the pick held without squeezing.","Acordes de s\xE9ptima":"Seventh chords","{A7}, {D7}, {E7} y {G7} suenan con \xABganas de ir\xBB al siguiente acorde. Muchos son m\xE1s f\xE1ciles que el acorde normal.":"{A7}, {D7}, {E7} and {G7} sound \u201Ceager to move\u201D to the next chord. Many are easier than the normal chord.","Las s\xE9ptimas":"The sevenths",Kumbay\u00E1:"Kumbaya","Rasgueo \u2193 \u2193\u2191 \u2191\u2193\u2191":"Strum \u2193 \u2193\u2191 \u2191\u2193\u2191","La cucaracha":"La Cucaracha","R\xE1pida y alegre":"Fast and cheerful","Con {G7} y {D7}":"With {G7} and {D7}",Punteo:"Picking","Melod\xEDas nota a nota":"Melodies note by note","Tocar melod\xEDas":"Playing melodies","Primera posici\xF3n":"First position","Cada dedo se encarga de un traste: el 1 del primero, el 2 del segundo y el 3 del tercero. Pulsa con la p\xFAa hacia abajo.":"Each finger looks after one fret: 1 the first, 2 the second and 3 the third. Pick downwards.","Las cuerdas 1 y 2":"Strings 1 and 2","Cuerda 1: {E} (al aire), {F} (traste 1) y {G} (traste 3). Cuerda 2: {B} (al aire), {C} (traste 1) y {D} (traste 3).":"String 1: {E} (open), {F} (fret 1) and {G} (fret 3). String 2: {B} (open), {C} (fret 1) and {D} (fret 3).","Cuerda 1":"String 1","Cuerda 2":"String 2","Oda a la alegr\xEDa":"Ode to Joy","Beethoven en las dos primeras cuerdas":"Beethoven on the first two strings","Melod\xEDa con la p\xFAa":"Melody with the pick",Arpegios:"Arpeggios","Dedos de la mano derecha":"Right-hand fingers",Arpegiar:"Arpeggiating","Pulgar (p) para las cuerdas graves; \xEDndice (i), medio (m) y anular (a) para las cuerdas 3, 2 y 1. Deja que todo suene junto.":"Thumb (p) for the low strings; index (i), middle (m) and ring (a) for strings 3, 2 and 1. Let everything ring together.","{Fmaj7}, un Fa sin cejilla":"{Fmaj7}, an F without a barre","Dedos 3, 2 y 1 en escalera sobre las cuerdas 4, 3 y 2; la 1.\xAA al aire. Suena precioso y prepara la cejilla.":"Fingers 3, 2 and 1 in a staircase on strings 4, 3 and 2; the 1st open. It sounds lovely and prepares you for the barre.","Como {D}, pero la 1.\xAA cuerda baja al traste 1 (dedo 1) y el dedo 2 pasa al traste 2 de la 3.\xAA cuerda. M\xE1s triste, m\xE1s bonito.":"Like {D}, but the 1st string goes down to fret 1 (finger 1) and finger 2 moves to fret 2 of the 3rd string. Sadder, prettier.","Arpegia {Am}, {C} y {Fmaj7}":"Arpeggiate {Am}, {C} and {Fmaj7}","p-i-m-a en cada acorde":"p-i-m-a on each chord","La casa del sol naciente":"The House of the Rising Sun","Arpegios en 3 por 4":"Arpeggios in 3/4","{Dm} y {Am}":"{Dm} and {Am}","Los menores":"The minors","Melanc\xF3lica, en 3 por 4":"Melancholic, in 3/4","Quintas y blues":"Fifths and blues","Acordes de quinta":"Power chords","Dos notas, mucha energ\xEDa":"Two notes, lots of energy","Un acorde de quinta ({E5}, {A5}\u2026) es solo la nota base y su quinta. Se mueve igual por todo el m\xE1stil: aprende la forma una vez y sirve siempre.":"A power chord ({E5}, {A5}\u2026) is just the root and its fifth. It moves the same way all over the neck: learn the shape once and it always works.","Silencia lo que sobra":"Mute what you don't need","Toca solo las cuerdas del acorde. Apoya un poco la palma derecha sobre las cuerdas graves cerca del puente para un sonido m\xE1s seco.":"Play only the strings of the chord. Rest your right palm lightly on the low strings near the bridge for a drier sound.","El acorde que lleva de vuelta a {E} en el blues. Cuatro dedos: t\xF3mate tu tiempo.":"The chord that leads back to {E} in the blues. Four fingers: take your time.",Quintas:"Fifths","Riff de quintas":"Power-chord riff","Tu primer riff":"Your first riff","Blues en Mi":"Blues in E","Doce compases de blues":"Twelve-bar blues","La cejilla":"The barre","{F} y {Bm}: el gran salto":"{F} and {Bm}: the big leap","El dedo 1 como cejuela":"Finger 1 as a nut","Estira el dedo 1 sobre todas las cuerdas en el traste 1, un poco de lado (el hueso, no la yema). Presiona con el peso del brazo, no apretando el pulgar.":"Stretch finger 1 across all the strings on fret 1, slightly on its side (the bone, not the pad). Press with the weight of your arm, not by squeezing with your thumb.",Paciencia:"Patience","La cejilla tarda semanas en sonar limpia. Toca primero solo las cuerdas agudas y ve a\xF1adiendo. Todos los guitarristas han pasado por aqu\xED.":"A barre takes weeks to sound clean. Play only the high strings first and add the rest gradually. Every guitarist has been through this.","Cejilla en el traste 2 desde la 5.\xAA cuerda, con la forma de {Am} dos trastes m\xE1s arriba.":"Barre on fret 2 from the 5th string, with the {Am} shape two frets higher.","Suena {F}":"{F} rings out","Cuerda a cuerda, sin prisa":"String by string, without rushing","Los cuatro acordes del pop":"The four chords of pop","Balada con cejilla":"Ballad with barre chords","Con {F} de verdad":"With a real {F}","Sim en movimiento":"Moving Bm","Cejilla en el traste 2":"Barre on fret 2","Cadencia andaluza, tangos y rumba":"Andalusian cadence, tangos and rumba","La guitarra flamenca":"Flamenco guitar","La cadencia andaluza":"The Andalusian cadence","{Am}, {G}, {F} y {E}: bajando de uno en uno hasta el {E}. Es el sonido del flamenco y lo usan los tangos, la rumba y las sevillanas.":"{Am}, {G}, {F} and {E}: stepping down one at a time to {E}. It is the sound of flamenco and is used by tangos, rumba and sevillanas.","El rasgueo de rumba":"The rumba strum","Golpe hacia abajo con el pulgar, arriba con el \xEDndice y un golpe seco con la palma que apaga las cuerdas en el 2 y el 4. Empieza despacio.":"A downstroke with the thumb, up with the index and a dry slap with the palm that mutes the strings on 2 and 4. Start slowly.","El mismo camino empezando en {Dm}: {Dm}, {C}, {Bb} y {A}. Lo llaman \xABpor medio\xBB porque descansa en La.":"The same path starting on {Dm}: {Dm}, {C}, {Bb} and {A}. It is called \u201Cpor medio\u201D because it rests on A.","Cadencia andaluza":"Andalusian cadence","El sonido del flamenco":"The sound of flamenco","Con {Dm} al final":"With {Dm} at the end","Rumba flamenca":"Flamenco rumba","Alegre y r\xE1pida":"Cheerful and fast","Con {Bb} con cejilla":"With {Bb} as a barre chord","Cambia en el pulso 3":"Change on beat 3","Abajo-arriba-arriba: un-dos-tres":"Down-up-up: one-two-three","Todos los acordes del cap\xEDtulo, a tempo":"All the chords of the chapter, in time","Los acordes del libro, a tempo":"The chords of the book, in time","Postura y relajaci\xF3n":"Posture and relaxation","Espalda recta, hombros sueltos y el pulgar izquierdo detr\xE1s del m\xE1stil, sin apretar. La tensi\xF3n es el gran enemigo de la velocidad.":"Straight back, loose shoulders and the left thumb behind the neck, without squeezing. Tension is the great enemy of speed.","Un acorde por comp\xE1s, rasgueo \u2193 \u2193\u2191 \u2191\u2193\u2191":"One chord per bar, strum \u2193 \u2193\u2191 \u2191\u2193\u2191","Bajo en el uno y acorde en el dos y el tres":"Bass on one and chord on two and three","Cambios limpios":"Clean changes","Busca dedos gu\xEDa y mueve todos los dedos a la vez. Los cambios de un minuto miden tu progreso: apunta tu r\xE9cord.":"Look for guide fingers and move all your fingers at once. One-minute changes measure your progress: note down your record.","Ritmos de rasgueo":"Strumming rhythms","Mant\xE9n la mano como un p\xE9ndulo y var\xEDa solo d\xF3nde tocas: as\xED cualquier ritmo sale a tempo.":"Keep your hand like a pendulum and change only where you hit: that way any rhythm comes out in time.","Cumplea\xF1os feliz (en Do)":"Happy Birthday (in C)","Las s\xE9ptimas dan color y empuje a la vuelta a casa. Apr\xE9ndelas como \xABprimas\xBB de los acordes que ya sabes.":"Sevenths add colour and drive to the return home. Learn them as \u201Ccousins\u201D of the chords you already know.","Amazing Grace (en Do)":"Amazing Grace (in C)","Arpegios con los dedos":"Arpeggios with the fingers","p-i-m-a por cuerdas. Practica despacio con el metr\xF3nomo y deja sonar todas las notas.":"p-i-m-a across the strings. Practise slowly with the metronome and let every note ring.","Kumbay\xE1 (en Do)":"Kumbaya (in C)","Un dedo por traste. Practica la escala de Do y de Sol leyendo las notas, no solo de memoria.":"One finger per fret. Practise the C and G scales reading the notes, not just from memory.","When the Saints (en Do)":"When the Saints (in C)",Silenciar:"Muting","Apaga las cuerdas que no suenan con la palma o con dedos libres. Un sonido limpio es tan importante como las notas.":"Mute the strings that shouldn't ring with your palm or spare fingers. A clean sound is as important as the notes.","Vals en {Am}":"Waltz in {Am}","Acompa\xF1ar una canci\xF3n":"Accompanying a song","Escucha la melod\xEDa y cambia de acorde justo en la parte fuerte. Si dudas, simplifica el rasgueo, no el pulso.":"Listen to the melody and change chord right on the downbeat. If in doubt, simplify the strum, not the pulse.","Balada en Do y Lam":"Ballad in C and Am","El dedo 1 algo de lado y el peso del brazo, no la fuerza del pulgar. Las formas con cejilla se mueven por todo el m\xE1stil.":"Finger 1 slightly on its side and the weight of your arm, not the strength of your thumb. Barre shapes move all over the neck.","Acordes m\xF3viles":"Movable chords","Una misma forma con cejilla sirve para 12 acordes: solo cambia el traste. Aprende d\xF3nde est\xE1 cada nota en las dos cuerdas graves.":"One barre shape works for 12 chords: only the fret changes. Learn where each note is on the two low strings.","Blues en La":"Blues in A","Escalas pentat\xF3nicas":"Pentatonic scales","Cinco notas que suenan bien sobre casi todo: la base de los solos de blues y rock. Apr\xE9ndelas en una posici\xF3n y luego mu\xE9velas.":"Five notes that sound good over almost anything: the basis of blues and rock solos. Learn them in one position and then move them.","Nana en {Am}":"Lullaby in {Am}","Fingerpicking avanzado":"Advanced fingerpicking","El pulgar marca el bajo alternando cuerdas mientras los dedos tocan la melod\xEDa. Lento y regular, el pulgar nunca para.":"The thumb plays the bass alternating strings while the fingers play the melody. Slow and steady, the thumb never stops.","Reggae en Do":"Reggae in C","T\xE9cnicas de adorno":"Ornament techniques","Ligados ascendentes (hammer-on), descendentes (pull-off) y deslizamientos (slides) dan expresi\xF3n a la melod\xEDa.":"Hammer-ons, pull-offs and slides give expression to the melody.","Armon\xEDa funcional":"Functional harmony","I-IV-V, ii-V-I y el c\xEDrculo de quintas: entender por qu\xE9 van los acordes te permite sacar canciones de o\xEDdo.":"I-IV-V, ii-V-I and the circle of fifths: understanding why chords go where they go lets you work songs out by ear.","Lectura de cifrados":"Reading chord charts","Lee cifrados y tablaturas, pero aprende tambi\xE9n la partitura: te abre todo el repertorio.":"Read chord charts and tabs, but learn standard notation too: it opens up the whole repertoire.","Tocar con otros":"Playing with others","En un grupo, menos es m\xE1s: deja espacio a la voz y al resto. Escucha el bajo y el ritmo del bater\xEDa.":"In a group, less is more: leave space for the voice and the rest. Listen to the bass and the drummer's groove.","Tu primer acorde":"Your first chord","{C} con un dedo y tu primera canci\xF3n":"{C} with one finger and your first song","Conoce tu ukelele":"Get to know your ukulele","Las cuatro cuerdas, de la de arriba (la 4.\xAA) a la de abajo (la 1.\xAA). El Sol es agudo, no grave: por eso el ukelele suena tan alegre y brillante.":"The four strings, from the top one (the 4th) to the bottom one (the 1st). The G is high, not low: that is why the ukulele sounds so cheerful and bright.","C\xF3mo se sujeta":"How to hold it","Apoya el cuerpo contra el pecho y suj\xE9talo suave con el antebrazo derecho. El m\xE1stil, un poco hacia arriba. El pulgar izquierdo, detr\xE1s del m\xE1stil, sin apretar.":"Rest the body against your chest and hold it gently with your right forearm. The neck slightly upwards. The left thumb behind the neck, without squeezing.","Se rasguea con el \xEDndice":"Strum with your index finger","Hacia abajo con la u\xF1a, hacia arriba con la yema. Rasguea donde acaba el m\xE1stil, no encima de la boca: suena m\xE1s dulce.":"Down with the nail, up with the pad. Strum where the neck ends, not over the sound hole: it sounds sweeter.","Deja el m\xF3vil a medio metro. En los acordes, rasguea y deja sonar: cuando el acorde suene limpio, se pondr\xE1 verde. Afina antes en Estudio \u2192 Afinador.":"Put the phone half a metre away. For chords, strum and let it ring: when the chord sounds clean, it turns green. Tune first in Practice \u2192 Tuner.","La afinaci\xF3n reentrante":"Re-entrant tuning","Sol, Do, Mi, La, pero el Sol est\xE1 por encima del Do: la cuerda de arriba no es la m\xE1s grave. Por eso los acordes suenan cerrados y brillantes.":"G, C, E, A, but the G is above the C: the top string is not the lowest. That is why chords sound close and bright.","Se escribe como suena":"It is written as it sounds","El ukelele lee la clave de sol tal cual, sin transportar. Su nota m\xE1s grave al aire es el Do central (Do4).":"The ukulele reads treble clef as it is, without transposing. Its lowest open note is middle C (C4).","Las cuerdas de nailon se estiran mucho las primeras semanas: afina antes de cada sesi\xF3n. La 1.\xAA cuerda es el La 440 del diapas\xF3n.":"Nylon strings stretch a lot in the first weeks: tune before every session. The 1st string is the A 440 of the tuning fork.","\xBFCu\xE1l es la cuerda m\xE1s grave del ukelele con afinaci\xF3n normal?":"Which is the lowest string on a ukulele in standard tuning?","La 4.\xAA (Sol)":"The 4th (G)","La 3.\xAA (Do)":"The 3rd (C)","La 2.\xAA (Mi)":"The 2nd (E)","La 1.\xAA (La)":"The 1st (A)","La 3.\xAA, el Do central. El Sol de la 4.\xAA est\xE1 afinado agudo: es la afinaci\xF3n reentrante.":"The 3rd, middle C. The G on the 4th is tuned high: that is re-entrant tuning.","Acordes de un dedo":"One-finger chords","{C}: un solo dedo":"{C}: a single finger","Dedo 3 (anular) en el traste 3 de la 1.\xAA cuerda, la de abajo. Rasguea las cuatro. Ya est\xE1s tocando un acorde.":"Finger 3 (ring) on fret 3 of the 1st string, the bottom one. Strum all four. You're already playing a chord.","{Am}: tambi\xE9n un dedo":"{Am}: also one finger","Dedo 2 (medio) en el traste 2 de la 4.\xAA cuerda, la de arriba. Suena m\xE1s triste que {C}: es un acorde menor.":"Finger 2 (middle) on fret 2 of the 4th string, the top one. It sounds sadder than {C}: it is a minor chord.","Apoya justo detr\xE1s del traste":"Press just behind the fret","Con la yema, de punta y casi tocando el metal del traste. As\xED basta con poca fuerza y la cuerda no zumba.":"With the fingertip, upright and almost touching the metal fret. That way little force is needed and the string doesn't buzz.","Suena {C}":"{C} rings out","Pon el dedo, rasguea y deja sonar":"Place the finger, strum and let it ring","{C} y {Am}":"{C} and {Am}","Los cuatro acordes m\xE1gicos":"The four magic chords","Dos acordes nuevos":"Two new chords","Dedo 1 en el traste 1 de la 2.\xAA cuerda (Mi) y dedo 2 en el traste 2 de la 4.\xAA (Sol). Truco: de {Am} a {F} el dedo 2 no se mueve, solo a\xF1ades el 1.":"Finger 1 on fret 1 of the 2nd string (E) and finger 2 on fret 2 of the 4th (G). Trick: from {Am} to {F} finger 2 doesn't move, you just add finger 1.","Un tri\xE1ngulo: dedo 1 en el traste 2 de la 3.\xAA, dedo 2 en el traste 2 de la 1.\xAA y dedo 3 en el traste 3 de la 2.\xAA. Es el m\xE1s dif\xEDcil de los cuatro: dale tiempo.":"A triangle: finger 1 on fret 2 of the 3rd, finger 2 on fret 2 of the 1st and finger 3 on fret 3 of the 2nd. It is the hardest of the four: give it time.","Los cuatro m\xE1gicos":"The magic four","{C}, {G}, {Am} y {F}: con estos cuatro se tocan cientos de canciones de pop. Ya los tienes todos.":"{C}, {G}, {Am} and {F}: with these four you can play hundreds of pop songs. You've got them all now.","Con el dedo 2 de ancla":"With finger 2 as the anchor","El tri\xE1ngulo, despacio":"The triangle, slowly","Ritmo de isla":"Island rhythm","Rasgueos y s\xE9ptimas":"Strums and sevenths","La mano no para: abajo en cada pulso y arriba entre pulsos, toques o no. As\xED nunca pierdes el comp\xE1s.":"Your hand never stops: down on every beat and up between beats, whether you play or not. That way you never lose the bar.","El rasgueo de isla":"The island strum","Abajo, abajo-arriba, arriba-abajo-arriba (\u2193 \u2193\u2191 \u2191\u2193\u2191). Es el ritmo del ukelele por excelencia. Dilo en voz alta mientras rasgueas: \xABuno, dos-y, y-cua-tro-y\xBB.":"Down, down-up, up-down-up (\u2193 \u2193\u2191 \u2191\u2193\u2191). It is the ukulele rhythm par excellence. Say it out loud while you strum: \u201Cone, two-and, and-four-and\u201D.","{C7} es el acorde m\xE1s f\xE1cil de todos: dedo 1 en el traste 1 de la 1.\xAA cuerda. {G7} es un tri\xE1ngulo al rev\xE9s que el de {G}. Las s\xE9ptimas \xABpiden\xBB volver a casa.":"{C7} is the easiest chord of all: finger 1 on fret 1 of the 1st string. {G7} is an upside-down version of the {G} triangle. Sevenths \u201Cask\u201D to go back home.","Con ganas de volver a {C}":"Eager to go back to {C}","La canci\xF3n hawaiana m\xE1s famosa":"The most famous Hawaiian song","Con {C7} y {G7}":"With {C7} and {G7}","{D}, {A} y el blues":"{D}, {A} and the blues","Nuevas tonalidades":"New keys","Acordes de {D} y {A}":"{D} and {A} chords","{A} y {E}":"{A} and {E}","{D} y {G}":"{D} and {G}","Dedos 1, 2 y 3 en el traste 2 de las cuerdas 4, 3 y 2. Si no caben, prueba a pisar las tres con el dedo 1 estirado.":"Fingers 1, 2 and 3 on fret 2 of strings 4, 3 and 2. If they don't fit, try pressing all three with finger 1 stretched out.","Dedo 2 en el traste 2 de la 4.\xAA y dedo 1 en el traste 1 de la 3.\xAA. {A7} es todav\xEDa m\xE1s f\xE1cil: solo el dedo 1.":"Finger 2 on fret 2 of the 4th and finger 1 on fret 1 of the 3rd. {A7} is even easier: just finger 1.","El blues: {A7}, {D7} y {E7}":"The blues: {A7}, {D7} and {E7}","Doce compases con tres s\xE9ptimas. {D7}: traste 2 en las cuerdas 4 y 2. {E7}: trastes 1, 2 y 2 en las cuerdas 4, 3 y 1.":"Twelve bars with three sevenths. {D7}: fret 2 on strings 4 and 2. {E7}: frets 1, 2 and 2 on strings 4, 3 and 1.","El cambio de las canciones del oeste":"The change of cowboy songs","R\xE1pida y alegre, con {A7}":"Fast and cheerful, with {A7}","Las s\xE9ptimas del blues":"The blues sevenths",Melod\u00EDas:"Melodies","Punteo nota a nota":"Picking note by note","Un dedo por traste":"One finger per fret","El dedo 1 se encarga del traste 1, el 2 del 2 y el 3 del 3. Pulsa con el pulgar o el \xEDndice, de una en una.":"Finger 1 looks after fret 1, finger 2 fret 2 and finger 3 fret 3. Pluck with your thumb or index, one at a time.","Las cuerdas La y Mi":"The A and E strings","Cuerda La (1.\xAA): La al aire, Si en el traste 2 y Do en el 3. Cuerda Mi (2.\xAA): Mi al aire, Fa en el traste 1 y Sol en el 3.":"A string (1st): A open, B on fret 2 and C on fret 3. E string (2nd): E open, F on fret 1 and G on fret 3.","La cuerda Do":"The C string","Do al aire y Re en el traste 2. Con las tres cuerdas ya tienes la escala de Do entera.":"C open and D on fret 2. With the three strings you have the whole C scale.","Tres cuerdas":"Three strings","Beethoven en las cuerdas Do y Mi":"Beethoven on the C and E strings","Melod\xEDa nota a nota":"Melody note by note","Menores y fingerpicking":"Minors and fingerpicking","Tocar con los dedos":"Playing with the fingers","Con los dedos":"With the fingers","Pulgar (p) para la 4.\xAA cuerda, \xEDndice (i) para la 3.\xAA, medio (m) para la 2.\xAA y anular (a) para la 1.\xAA. Cada dedo, su cuerda.":"Thumb (p) for the 4th string, index (i) for the 3rd, middle (m) for the 2nd and ring (a) for the 1st. Each finger, its own string.","El patr\xF3n p-i-m-a":"The p-i-m-a pattern","Una cuerda detr\xE1s de otra, de arriba abajo, y deja que todas sigan sonando. Despacio y parejo: suena a caja de m\xFAsica.":"One string after another, from top to bottom, and let them all keep ringing. Slow and even: it sounds like a music box.","{Dm} y {Em}":"{Dm} and {Em}","{Dm}: trastes 2, 2 y 1 en las cuerdas 4, 3 y 2. {Em}: trastes 4, 3 y 2 en las cuerdas 3, 2 y 1 (la 4.\xAA al aire).":"{Dm}: frets 2, 2 and 1 on strings 4, 3 and 2. {Em}: frets 4, 3 and 2 on strings 3, 2 and 1 (the 4th open).","{Am}, {Dm} y {Em}":"{Am}, {Dm} and {Em}","Arpegia p-i-m-a en cada uno":"Arpeggiate p-i-m-a on each one","El chuck y el reggae":"The chuck and reggae","Golpe apagado y contratiempo":"Muted stroke and offbeat","Ritmos con car\xE1cter":"Rhythms with character","El chuck":"The chuck","En el 2 y el 4, rasguea hacia abajo y apaga las cuerdas a la vez con el canto de la mano. Suena \xABchuck\xBB, como una caja de bater\xEDa.":"On 2 and 4, strum down and mute the strings at the same time with the side of your hand. It sounds \u201Cchuck\u201D, like a snare drum.","Rasguea solo a contratiempo, entre los pulsos (hacia arriba), y apaga enseguida. Cuenta \xABuno-Y, dos-Y\xBB y toca solo en la Y.":"Strum only on the offbeat, between the beats (upwards), and mute straight away. Count \u201Cone-AND, two-AND\u201D and play only on the AND.","Dedo 1 en el traste 2 de la 3.\xAA y dedo 2 en el traste 2 de la 1.\xAA. Un color suave que queda bien en el reggae.":"Finger 1 on fret 2 of the 3rd and finger 2 on fret 2 of the 1st. A soft colour that suits reggae.","Rasgueo a contratiempo":"Offbeat strumming","Con chuck en el 2 y el 4":"With a chuck on 2 and 4","Balada con {Em}":"Ballad with {Em}","Cejilla y {Bb}":"Barre and {Bb}","Mucho m\xE1s f\xE1cil que en guitarra":"Much easier than on guitar","Solo son cuatro cuerdas y est\xE1n poco tensas. Estira el dedo 1 sobre todas, un poco de lado, y presiona con el peso del brazo.":"There are only four strings and they are not very tight. Stretch finger 1 across all of them, slightly on its side, and press with the weight of your arm.","Cejilla en el traste 1 con el dedo 1, dedo 2 en el traste 2 de la 3.\xAA y dedo 3 en el traste 3 de la 4.\xAA.":"Barre on fret 1 with finger 1, finger 2 on fret 2 of the 3rd and finger 3 on fret 3 of the 4th.","{Bm} y {B7}":"{Bm} and {B7}","Cejilla en el traste 2. Para {Bm}, dedo 3 en el traste 4 de la 4.\xAA; para {B7}, dedo 2 en el traste 3 de la 3.\xAA.":"Barre on fret 2. For {Bm}, finger 3 on fret 4 of the 4th; for {B7}, finger 2 on fret 3 of the 3rd.","Suena {Bb}":"{Bb} rings out","Rumba y cadencia andaluza":"Rumba and the Andalusian cadence","Flamenco en el ukelele":"Flamenco on the ukulele","Flamenco en cuatro cuerdas":"Flamenco on four strings","{Am}, {G}, {F} y {E}: bajando de uno en uno. Es el sonido del flamenco y en el ukelele tambi\xE9n funciona.":"{Am}, {G}, {F} and {E}: stepping down one at a time. It is the sound of flamenco and it works on the ukulele too.","Dedo 1 en el traste 1 de la 4.\xAA, dedo 2 en el traste 2 de la 1.\xAA y dedo 4 en el traste 4 de la 3.\xAA. Si cuesta, usa {E7} mientras tanto.":"Finger 1 on fret 1 of the 4th, finger 2 on fret 2 of the 1st and finger 4 on fret 4 of the 3rd. If it's hard, use {E7} in the meantime.","Abajo, arriba y un golpe seco con la palma que apaga las cuerdas en el 2 y el 4. Empieza despacio.":"Down, up and a dry slap with the palm that mutes the strings on 2 and 4. Start slowly.","Posici\xF3n de {C}":"{C} position","Cinco dedos, tu primera melod\xEDa":"Five fingers, your first melody","Conoce el teclado":"Get to know the keyboard","Encuentra el Do":"Find C","Las teclas negras van en grupos de dos y de tres. El Do es la tecla blanca justo a la izquierda de cada grupo de dos. El del centro del piano es el Do central.":"The black keys come in groups of two and three. C is the white key just to the left of each group of two. The one in the middle of the piano is middle C.","Tus dedos tienen n\xFAmero":"Your fingers have numbers","En las dos manos: 1 el pulgar, 2 el \xEDndice, 3 el medio, 4 el anular y 5 el me\xF1ique. Los ver\xE1s debajo de cada nota.":"On both hands: 1 is the thumb, 2 the index, 3 the middle, 4 the ring and 5 the little finger. You will see them under each note.","La postura":"Posture","Si\xE9ntate a la altura justa para que el antebrazo quede recto. Mano redondeada, como si sujetaras una naranja, y toca con la yema.":"Sit at the right height so your forearm is level. A rounded hand, as if holding an orange, and play with the fingertips.","Deja el m\xF3vil cerca del piano. Toca cada nota con decisi\xF3n y su\xE9ltala: cuando suene la correcta se pondr\xE1 verde.":"Put the phone near the piano. Play each note decisively and release it: when the right one sounds it turns green.","T\xFA no lo afinas":"You don't tune it","Un piano ac\xFAstico lo afina un afinador profesional, una o dos veces al a\xF1o. Un piano digital nunca se desafina.":"An acoustic piano is tuned by a professional tuner, once or twice a year. A digital piano never goes out of tune.","Doce semitonos iguales":"Twelve equal semitones","Se afina el La central a 440 Hz y se reparten los doce semitonos de la octava exactamente iguales (temperamento igual). As\xED suena bien en todas las tonalidades.":"The A above middle C is tuned to 440 Hz and the twelve semitones of the octave are spread exactly equally (equal temperament). That way it sounds good in every key.","Octavas estiradas":"Stretched octaves","Las cuerdas del piano son r\xEDgidas y sus arm\xF3nicos salen algo m\xE1s altos de lo \xABperfecto\xBB. Por eso el afinador deja los agudos un poco altos y los graves un poco bajos: as\xED suena afinado.":"Piano strings are stiff and their harmonics come out a little higher than \u201Cperfect\u201D. That is why the tuner leaves the treble slightly high and the bass slightly low: that way it sounds in tune.","\xBFQui\xE9n afina un piano ac\xFAstico?":"Who tunes an acoustic piano?","Quien lo toca, antes de cada clase":"The player, before every lesson","Un afinador profesional":"A professional tuner","Se afina solo":"It tunes itself","Nadie: nunca se desafina":"Nobody: it never goes out of tune","Un afinador profesional, una o dos veces al a\xF1o (el digital no se desafina).":"A professional tuner, once or twice a year (a digital one never goes out of tune).","Dedos 1, 2 y 3":"Fingers 1, 2 and 3","Cinco dedos":"Five fingers","Tu primera canci\xF3n, hoy mismo":"Your first song, today","Sin mirar las manos":"Without looking at your hands","Mano izquierda":"Left hand","La clave de fa":"The bass clef","Otra clave para los graves":"Another clef for the low notes","La mano izquierda lee en clave de fa: los dos puntos rodean la l\xEDnea del Fa. El Do grave (un Do por debajo del central) est\xE1 en el segundo espacio.":"The left hand reads bass clef: the two dots surround the F line. Low C (one C below middle C) is in the second space.","Al rev\xE9s que la derecha":"The opposite of the right","En la izquierda el me\xF1ique (5) est\xE1 en el Do y el pulgar (1) en el Sol. Subir es ir hacia el pulgar.":"On the left hand the little finger (5) is on C and the thumb (1) on G. Going up means moving towards the thumb.","Cinco dedos (izquierda)":"Five fingers (left)","Do, Re, Mi, Fa y Sol graves":"Low C, D, E, F and G","Oda con la izquierda":"Ode with the left hand","La misma canci\xF3n, una octava m\xE1s grave":"The same song, an octave lower","Estrellita (izquierda)":"Twinkle, Twinkle (left hand)","Con un peque\xF1o estiramiento":"With a small stretch","Tres notas a la vez":"Three notes at once","Dedos 1, 3 y 5 en Do, Mi y Sol. Baja las tres teclas a la vez, como una sola.":"Fingers 1, 3 and 5 on C, E and G. Press the three keys together, as one.","{F} sin moverte casi":"{F} almost without moving","Deja el pulgar en Do, sube el 3 al Fa y el 5 al La. As\xED el cambio es m\xEDnimo.":"Leave the thumb on C, move 3 up to F and 5 to A. That way the change is minimal.","{G} cerca del Do":"{G} close to C","Pulgar al Si, dedo 2 al Re y el 5 se queda en el Sol. Con {C}, {F} y {G} se acompa\xF1an cientos de canciones.":"Thumb to B, finger 2 to D and 5 stays on G. With {C}, {F} and {G} you can accompany hundreds of songs.","Las tres teclas a la vez":"The three keys at once","Moviendo lo m\xEDnimo":"Moving as little as possible","Acompa\xF1a un cumplea\xF1os":"Accompany a birthday","Tres acordes, una canci\xF3n":"Three chords, one song","Acompa\xF1ar canciones":"Accompanying songs","Menores y s\xE9ptimas":"Minors and sevenths","M\xE1s colores":"More colours","Desde {C}, cambia solo el 5: del Sol al La. Un dedo y el acorde se vuelve triste.":"From {C}, change only finger 5: from G to A. One finger and the chord turns sad.","Como {G}, pero con el Fa: pide volver a {C}. Pulgar en Si, 4 en Fa y 5 en Sol.":"Like {G}, but with F: it wants to go back to {C}. Thumb on B, 4 on F and 5 on G.","Re, Fa y La con los dedos 1, 3 y 5.":"D, F and A with fingers 1, 3 and 5.","{Am}, {Dm} y {G7}":"{Am}, {Dm} and {G7}","Con {G7}":"With {G7}","Con {C7}":"With {C7}","Posici\xF3n de {G}":"{G} position","Tu primer sostenido":"Your first sharp","Otra posici\xF3n":"Another position","Pulgar en Sol":"Thumb on G","Coloca el pulgar derecho en el Sol de arriba del Do central y los dem\xE1s dedos en La, Si, Do y Re.":"Put your right thumb on the G above middle C and the other fingers on A, B, C and D.","En Sol mayor el Fa es sostenido: la tecla negra justo a la derecha del Fa. La armadura te lo recuerda al principio de cada l\xEDnea.":"In G major the F is sharp: the black key just to the right of F. The key signature reminds you at the start of each line.","Cinco dedos en Sol":"Five fingers in G","Petzold, del cuaderno de Ana Magdalena Bach":"Petzold, from the Anna Magdalena Bach notebook","En otra tonalidad":"In another key","Redonda: 4 pulsos. Blanca: 2. Negra: 1. Corchea: medio pulso. Un puntillo suma la mitad de la nota.":"Whole note: 4 beats. Half note: 2. Quarter note: 1. Eighth note: half a beat. A dot adds half of the note.","Cuenta en voz alta":"Count out loud","\xABUno y dos y tres y cuatro y\xBB: las corcheas caen en los n\xFAmeros y en las \xABy\xBB. Activa el metr\xF3nomo para no correr.":"\u201COne and two and three and four and\u201D: the eighth notes fall on the numbers and on the \u201Cands\u201D. Turn on the metronome so you don't rush.","Corcheas con alegr\xEDa":"Cheerful eighth notes","Ahora en Re":"Now in D","El paso del pulgar":"Passing the thumb","M\xE1s all\xE1 de cinco dedos":"Beyond five fingers","El pulgar pasa por debajo":"The thumb passes under","Sube Do-Re-Mi con 1-2-3 y pasa el pulgar por debajo hasta el Fa. Sigue con 1-2-3-4-5 hasta el Do de arriba.":"Go up C-D-E with 1-2-3 and pass the thumb under to F. Carry on with 1-2-3-4-5 up to the top C.",Bajando:"Going down","Al bajar es al rev\xE9s: el dedo 3 cruza por encima del pulgar del Fa al Mi.":"Going down it is the other way round: finger 3 crosses over the thumb from F to E.","Escala de Do (derecha)":"C scale (right hand)","Con paso del pulgar":"With the thumb passing under","Escala de Do (izquierda)":"C scale (left hand)","El 3 cruza al subir":"3 crosses over going up","Tradicional inglesa":"Traditional English","Vals con {Am}, {Dm} y {E}":"Waltz with {Am}, {Dm} and {E}","Las dos manos":"Both hands","Bajo, acorde y Para Elisa":"Bass, chord and F\xFCr Elise","Las dos manos juntas":"Both hands together","Bajo y acorde":"Bass and chord","La izquierda toca la nota que da nombre al acorde (el bajo) y la derecha el acorde. Empieza muy despacio: primero que suenen juntas, luego a tempo.":"The left hand plays the note that names the chord (the bass) and the right hand the chord. Start very slowly: first make them sound together, then in time.","Para Elisa":"F\xFCr Elise","Beethoven la escribi\xF3 en 1810. El famoso comienzo alterna Mi y Re\u266F con los dedos 5 y 4 de la derecha.":"Beethoven wrote it in 1810. The famous opening alternates E and D\u266F with fingers 5 and 4 of the right hand.","Izquierda en el bajo, derecha en el acorde":"Left hand on the bass, right hand on the chord","Ahora con las dos manos":"Now with both hands","El comienzo, mano derecha":"The opening, right hand","Postura y peso":"Posture and weight","Sentado a la altura justa, antebrazos paralelos al teclado y dedos curvos. El sonido sale del peso del brazo, no de golpear.":"Sitting at the right height, forearms parallel to the keyboard and curved fingers. The sound comes from the weight of the arm, not from hitting.","Practica cada mano sola y luego juntas, lento. Si se traban, vuelve a la mano que falla.":"Practise each hand alone and then together, slowly. If they get stuck, go back to the hand that slips.","Paso del pulgar":"Thumb under","En las escalas el pulgar pasa por debajo de la mano sin girar la mu\xF1eca. Es la clave de las escalas largas.":"In scales the thumb passes under the hand without turning the wrist. It is the key to long scales.","Acordes en la izquierda":"Chords in the left hand","Acompa\xF1a con acordes en la mano izquierda: primero en bloque, luego bajo-acorde (como un vals o una marcha).":"Accompany with chords in the left hand: first blocked, then bass-chord (like a waltz or a march).","Legato y staccato":"Legato and staccato","Legato: una tecla no se suelta hasta que suena la siguiente. Staccato: el dedo rebota desde la tecla.":"Legato: a key isn't released until the next one sounds. Staccato: the finger bounces off the key.","Leer en clave de fa":"Reading bass clef","La mano izquierda lee la clave de fa: el Fa est\xE1 en la cuarta l\xEDnea. Repasa las notas cada d\xEDa cinco minutos.":"The left hand reads bass clef: F is on the fourth line. Review the notes for five minutes every day.",Din\u00E1micas:"Dynamics","Forte con m\xE1s peso y piano con menos, sin cambiar la velocidad. Practica una escala en crescendo y diminuendo.":"Forte with more weight and piano with less, without changing speed. Practise a scale in crescendo and diminuendo.","Manos separadas y juntas, con la digitaci\xF3n correcta. La digitaci\xF3n se estudia, no se improvisa.":"Hands separately and together, with the right fingering. Fingering is studied, not improvised.","El pedal":"The pedal","El pedal de resonancia se cambia justo despu\xE9s de tocar el acorde nuevo (\xABpedal sincopado\xBB): sube y baja sin dejar huecos.":"The sustain pedal is changed just after playing the new chord (\u201Csyncopated pedal\u201D): up and down without leaving gaps.","Inversiones de acordes":"Chord inversions","Do-Mi-Sol, Mi-Sol-Do y Sol-Do-Mi son el mismo acorde. Elegir la inversi\xF3n m\xE1s cercana hace el acompa\xF1amiento fluido.":"C-E-G, E-G-C and G-C-E are the same chord. Choosing the nearest inversion makes the accompaniment flow.","Arpegios a dos manos":"Arpeggios with both hands","Arpegios de dos octavas con el paso del pulgar. Primero lentos y con el brazo acompa\xF1ando el movimiento.":"Two-octave arpeggios with the thumb passing under. Slow at first, with the arm following the movement.","Independencia de manos":"Hand independence","Una mano en legato y otra en staccato, o una fuerte y otra suave: la melod\xEDa debe destacar sobre el acompa\xF1amiento.":"One hand legato and the other staccato, or one loud and one soft: the melody must stand out over the accompaniment.","Czerny, Burgm\xFCller y Hanon trabajan problemas concretos. Uno por semana, lento y perfecto antes que r\xE1pido.":"Czerny, Burgm\xFCller and Hanon work on specific problems. One a week, slow and perfect before fast.",Ornamentos:"Ornaments","Trinos, mordentes y grupetos adornan la melod\xEDa. T\xF3calos con los dedos relajados y siempre a tempo.":"Trills, mordents and turns decorate the melody. Play them with relaxed fingers and always in time.","Lee primero el ritmo, despu\xE9s las notas. Mant\xE9n el pulso aunque te saltes alguna nota de la izquierda.":"Read the rhythm first, then the notes. Keep the pulse even if you skip a note in the left hand.","Preparar una obra":"Preparing a piece","Divide la obra en secciones, aprende las dif\xEDciles primero y une. Gr\xE1bate antes de tocarla en p\xFAblico.":"Divide the piece into sections, learn the hard ones first and put them together. Record yourself before playing it in public.","Los dos sonidos":"The two sounds","Grave y agudo":"Bass and slap","Antes de tocar":"Before playing","C\xF3mo sentarte":"How to sit","Si\xE9ntate encima del caj\xF3n, en la mitad de atr\xE1s, con las piernas a los lados. Incl\xEDnate un poco hacia delante y deja caer las manos sobre la tapa (la cara con el agujero va detr\xE1s).":"Sit on top of the caj\xF3n, on the back half, with your legs at the sides. Lean forward a little and let your hands fall on the front panel (the side with the hole goes at the back).","El grave":"The bass","Palma relajada, golpeando un poco por encima del centro de la tapa. Deja que la mano rebote: as\xED suena hondo, como un bombo. En la partitura va abajo y lleva una G.":"A relaxed palm, hitting slightly above the centre of the panel. Let your hand bounce: that way it sounds deep, like a bass drum. In the score it goes at the bottom and is marked G (from \u201Cgrave\u201D).","El agudo":"The slap","Las yemas de los dedos, juntos, en el borde de arriba, cerca de la esquina. Suena seco y con chasquido. En la partitura va arriba y lleva una A.":"The fingertips, together, on the top edge, near the corner. It sounds dry and snappy. In the score it goes at the top and is marked A (from \u201Cagudo\u201D).","La app oye cada golpe y te dice si llega a tiempo y si fue grave o agudo. Pon el m\xF3vil cerca, en un sitio sin ruido, y calibra el micr\xF3fono en Estudio.":"The app hears every stroke and tells you if it arrives on time and whether it was bass or slap. Put the phone close, somewhere quiet, and calibrate the microphone in Practice.","Un instrumento peruano":"A Peruvian instrument","El caj\xF3n naci\xF3 en Per\xFA. Paco de Luc\xEDa lo trajo al flamenco en los a\xF1os 70 y desde entonces no falta en ning\xFAn tablao.":"The caj\xF3n was born in Peru. Paco de Luc\xEDa brought it into flamenco in the 1970s and since then no flamenco venue is without one.","Las bordonas":"The snares","Dentro lleva cuerdas o bordonas pegadas a la tapa: son las que dan el chasquido del agudo. Algunos cajones tienen un tornillo para tensarlas o aflojarlas.":"Inside there are strings or snares against the front panel: they make the snap of the slap. Some cajones have a screw to tighten or loosen them.","Afinar el caj\xF3n":"Tuning the caj\xF3n","No da notas: se ajusta el sonido. Si los tornillos de las esquinas de arriba est\xE1n m\xE1s flojos, el agudo restalla m\xE1s.":"It doesn't give notes: you adjust the sound. If the screws in the top corners are looser, the slap cracks more.","\xBFQu\xE9 produce el chasquido del agudo?":"What makes the snap of the slap?","La madera de detr\xE1s":"The wood at the back","Las bordonas de dentro":"The snares inside","El agujero":"The hole","Las patas":"The legs","Las bordonas (cuerdas) pegadas a la tapa vibran con el golpe en el borde.":"The snares (strings) against the front panel vibrate when you hit the edge.",Graves:"Bass notes","Palma en el centro":"Palm in the centre",Agudos:"Slaps","Dedos en el borde":"Fingers on the edge","Uno y uno":"One and one","Tu primer ritmo":"Your first rhythm","Dos golpes por pulso":"Two strokes per beat","Uno-y, dos-y":"One-and, two-and","Cada pulso se parte en dos. Cuenta en voz alta \xABuno-y, dos-y\u2026\xBB y mant\xE9n las manos sueltas: las corcheas salen del rebote.":"Each beat splits in two. Count out loud \u201Cone-and, two-and\u2026\u201D and keep your hands loose: the eighth notes come from the bounce.","Grave y agudo alternados":"Alternating bass and slap","El ritmo b\xE1sico":"The basic rhythm","El que suena en mil canciones":"The one in a thousand songs","El 3-3-2":"The 3-3-2","La rumba":"The rumba","Tres, tres y dos":"Three, three and two","La rumba flamenca agrupa las ocho corcheas del comp\xE1s en 3 + 3 + 2. Los graves caen al principio de cada grupo: uno, el \xABy\xBB del dos y el cuatro.":"Flamenco rumba groups the eight eighth notes of the bar into 3 + 3 + 2. The bass notes fall at the start of each group: one, the \u201Cand\u201D of two, and four.","Suelto y alegre":"Loose and cheerful","No aprietes. La rumba se baila: si mueves el cuerpo, el ritmo sale solo.":"Don't squeeze. Rumba is danced: if you move your body, the rhythm comes by itself.","Rumba b\xE1sica":"Basic rumba","Rumba con aire":"Rumba with flair","Graves y agudos mezclados":"Bass and slaps mixed","Rumba con guitarra":"Rumba with guitar","La guitarra hace la cadencia andaluza":"The guitar plays the Andalusian cadence","El uno en silencio":"The silent one","Un comp\xE1s de cuatro":"A bar of four","Los tangos flamencos van en cuatro tiempos, pero el uno muchas veces no se toca: se siente. Cuenta \xAB(uno) dos, tres, cuatro\xBB y deja ese hueco.":"Flamenco tangos are in four beats, but beat one is often not played: it is felt. Count \u201C(one) two, three, four\u201D and leave that gap.","Los palos del flamenco":"The flamenco palos","Palos de cuatro":"Palos in four","Tangos, tientos y rumba van en cuatro tiempos. Son los m\xE1s f\xE1ciles para empezar a acompa\xF1ar.":"Tangos, tientos and rumba are in four beats. They are the easiest to start accompanying.","Palos de doce":"Palos in twelve","Sole\xE1, alegr\xEDas y buler\xEDas cuentan doce tiempos con acentos en 3, 6, 8, 10 y 12. La seguiriya tambi\xE9n es de doce, pero con otros acentos: la ver\xE1s m\xE1s adelante.":"Sole\xE1, alegr\xEDas and buler\xEDas count twelve beats with accents on 3, 6, 8, 10 and 12. Seguiriya is also in twelve, but with other accents: you will see it later.","\xBFCu\xE1l de estos palos va en comp\xE1s de 12?":"Which of these palos is in a 12-beat cycle?",Ninguno:"None","Las buler\xEDas, como la sole\xE1 y las alegr\xEDas, cuentan doce tiempos.":"Buler\xEDas, like sole\xE1 and alegr\xEDas, count twelve beats.","Tangos b\xE1sicos":"Basic tangos","El uno se siente":"Beat one is felt","Tangos con corcheas":"Tangos with eighth notes",Rellenando:"Filling in","Tangos con acentos":"Tangos with accents","Marca el cuatro":"Mark the four","Tangos con guitarra":"Tangos with guitar","Por tangos, con la guitarra de fondo":"Por tangos, with the guitar in the background","El comp\xE1s de 12":"The 12-beat cycle","La base del flamenco":"The basis of flamenco","Contar hasta 12":"Counting to 12","Doce tiempos":"Twelve beats","La sole\xE1, las alegr\xEDas y las buler\xEDas cuentan doce tiempos. Los fuertes son el 3, el 6, el 8, el 10 y el 12. Dilo en voz alta: \xABuno, dos, TRES, cuatro, cinco, SEIS, siete, OCHO, nueve, DIEZ, once, DOCE\xBB.":"Sole\xE1, alegr\xEDas and buler\xEDas count twelve beats. The strong ones are 3, 6, 8, 10 and 12. Say it out loud: \u201Cone, two, THREE, four, five, SIX, seven, EIGHT, nine, TEN, eleven, TWELVE\u201D.","En la partitura":"In the score","Lo escribimos en cuatro compases de tres tiempos. Los acentos (>) son los agudos fuertes; los dem\xE1s, graves suaves.":"We write it in four bars of three beats. The accents (>) are the strong slaps; the rest, soft bass notes.","Contar 12":"Counting 12","Graves con acentos agudos":"Bass notes with slap accents","Los acentos solos":"The accents alone","Silencio donde no hay acento":"Silence where there is no accent","Despacio y con peso":"Slow and weighty","La sole\xE1":"The sole\xE1","La madre del comp\xE1s":"The mother of the comp\xE1s","La sole\xE1 es lenta y solemne. Cada acento pesa. Toca el grave con la palma bien suelta y deja respirar los silencios.":"Sole\xE1 is slow and solemn. Every accent carries weight. Play the bass with a very loose palm and let the rests breathe.","Comp\xE1s de 12, lento":"12-beat cycle, slow","Sole\xE1 con graves":"Sole\xE1 with bass notes","Rellena los huecos":"Fill in the gaps","El 12 con alegr\xEDa":"The 12 with joy","Las alegr\xEDas":"The alegr\xEDas","Mismo comp\xE1s, otro car\xE1cter":"Same cycle, another character","Las alegr\xEDas usan el mismo comp\xE1s de 12 que la sole\xE1, pero m\xE1s vivo y luminoso. Llega con las manos sueltas a cada acento.":"Alegr\xEDas use the same 12-beat cycle as sole\xE1, but livelier and brighter. Arrive at each accent with loose hands.","Palmas y jaleo":"Palmas and jaleo","Palmas claras y sordas":"Clear and muffled palmas","Las claras (dedos de una mano contra la palma de la otra) suenan fuerte y agudo; las sordas (palmas huecas) suenan suave. El caj\xF3n dialoga con ellas.":"Clear palmas (fingers of one hand against the palm of the other) sound loud and high; muffled ones (cupped palms) sound soft. The caj\xF3n converses with them.","Escuchar al cante y al baile":"Listening to the singing and the dance","El caj\xF3n acompa\xF1a: cuando canta el cantaor, toca m\xE1s suave; cuando el bailaor zapatea, deja hueco o refu\xE9rzalo en los acentos.":"The caj\xF3n accompanies: when the singer sings, play softer; when the dancer stamps, leave space or reinforce the accents.","\xBFC\xF3mo suenan las palmas sordas?":"How do muffled palmas sound?","Fuertes y agudas":"Loud and high","Suaves y graves":"Soft and low","Como un aplauso normal":"Like normal applause","No suenan":"They make no sound","Suaves: se dan con las palmas huecas, sin chasquido.":"Soft: they are played with cupped palms, without a snap.","Alegr\xEDas con corcheas":"Alegr\xEDas with eighth notes","Graves en corcheas, acentos agudos":"Bass in eighth notes, slap accents","Desde el 12":"From 12","Las buler\xEDas":"The buler\xEDas","Se empieza en el 12":"You start on 12","Las buler\xEDas se cuentan empezando por el 12: \xABDOCE, uno, dos, TRES, cuatro, cinco, SEIS, siete, OCHO, nueve, DIEZ, once\xBB. Es el palo m\xE1s r\xE1pido y juguet\xF3n.":"Buler\xEDas are counted starting on 12: \u201CTWELVE, one, two, THREE, four, five, SIX, seven, EIGHT, nine, TEN, eleven\u201D. It is the fastest and most playful palo.","Escucha mucho":"Listen a lot","Pon buler\xEDas de tus artistas favoritos y cuenta el comp\xE1s en voz alta mientras suenan. Cuando lo sientas, t\xF3calo encima.":"Put on buler\xEDas by your favourite artists and count the comp\xE1s out loud while they play. When you feel it, play along.","Buler\xEDas desde el 12":"Buler\xEDas from 12","Despacio primero":"Slowly first","Buler\xEDas con graves":"Buler\xEDas with bass notes","Rellena con la palma":"Fill in with the palm","Cuenta en voz alta y mant\xE9n el pulso":"Count out loud and keep the pulse","Una lectura nueva con los ritmos del cap\xEDtulo":"A new reading with the chapter's rhythms","Una lectura r\xEDtmica nueva, de una sola vez":"A new rhythm reading, in a single take","Agarre y rebote":"Grip and rebound","Las baquetas sueltas entre el pulgar y el \xEDndice: deja que reboten. El golpe sale de la mu\xF1eca, no del hombro.":"Loose sticks between thumb and index finger: let them bounce. The stroke comes from the wrist, not the shoulder.","Primero lento, contando en voz alta":"Slowly first, counting out loud","A tempo y sin pararte":"In time and without stopping","Golpes simples y dobles":"Single and double strokes","D-I-D-I y DD-II. Empieza lento con el metr\xF3nomo y sube de 4 en 4 cuando salga perfectamente igualado.":"R-L-R-L and RR-LL. Start slowly with the metronome and go up 4 at a time when it sounds perfectly even.","El paradiddle":"The paradiddle","D-I-D-D, I-D-I-I. Con \xE9l se cambia de mano sin pensar. Pract\xEDcalo con acento en la primera nota.":"R-L-R-R, L-R-L-L. With it you change hands without thinking. Practise it with an accent on the first note.",Acentos:"Accents","Un acento es un golpe m\xE1s alto, no m\xE1s tenso: sube m\xE1s la baqueta y deja las dem\xE1s notas bajas.":"An accent is a higher stroke, not a tenser one: lift the stick higher and keep the other notes low.","Leer ritmos":"Reading rhythms","Cuenta en voz alta \xAB1-y-2-y\xBB o \xAB1-e-y-a\xBB. Leer bien el ritmo es la mitad del trabajo del percusionista.":"Count out loud \u201C1-and-2-and\u201D or \u201C1-e-and-a\u201D. Reading rhythm well is half of a percussionist's job.",Matices:"Dynamics","M\xE1s altura de baqueta, m\xE1s volumen. Practica crescendos de pp a ff sin acelerar.":"Higher sticks, more volume. Practise crescendos from pp to ff without speeding up.","Tocar con la banda":"Playing with the band","El percusionista sostiene el tempo de todos: escucha a la banda pero no te dejes arrastrar.":"The percussionist holds everyone's tempo: listen to the band but don't get dragged along.","Estudiar con metr\xF3nomo":"Practising with a metronome","El metr\xF3nomo es tu compa\xF1ero de ensayo. Ponlo tambi\xE9n en las corcheas para comprobar que lo entre pulsos est\xE1 igualado.":"The metronome is your practice partner. Set it to eighth notes too, to check that what falls between beats is even.","El redoble":"The roll","Dobles cada vez m\xE1s r\xE1pidos hasta que suenen continuos. El redoble a presi\xF3n (buzz) se hace apoyando la baqueta.":"Doubles getting faster and faster until they sound continuous. The buzz roll is played by pressing the stick into the head.","Flams y drags":"Flams and drags","El flam: una nota de adorno muy baja justo antes del golpe principal. El drag: dos notas de adorno. Dan cuerpo al golpe.":"The flam: a very soft grace note just before the main stroke. The drag: two grace notes. They give the stroke body.","Compases compuestos":"Compound time","En 6/8 y 12/8 siente el pulso en grupos de tres. Muchas marchas y ritmos latinos van as\xED.":"In 6/8 and 12/8 feel the pulse in groups of three. Many marches and Latin rhythms go like this.",Independencia:"Independence","En el caj\xF3n, el grave y el agudo; en la bater\xEDa, manos y pies. Practica cada parte sola y luego juntas, lento.":"On the caj\xF3n, bass and slap; on the drum kit, hands and feet. Practise each part on its own and then together, slowly.","Los estudios de caja (Wilcoxon, Del\xE9cluse) combinan rudimentos y lectura. Uno por semana, lento y perfecto.":"Snare studies (Wilcoxon, Del\xE9cluse) combine rudiments and reading. One a week, slow and perfect.","Los palos flamencos":"The flamenco palos","Rumba, tangos, buler\xEDas y sole\xE1: aprende su comp\xE1s y d\xF3nde caen los acentos. Escucha discos y cuenta con ellos.":"Rumba, tangos, buler\xEDas and sole\xE1: learn their comp\xE1s and where the accents fall. Listen to records and count along.","Busca primero las figuras m\xE1s r\xE1pidas y los cambios de comp\xE1s. Al tocar, no te pares nunca.":"First look for the fastest note values and the time-signature changes. While playing, never stop.","Decide los matices y las manos (stickings), m\xE1rcalos y gr\xE1bate. Un solo de percusi\xF3n tambi\xE9n cuenta una historia.":"Decide the dynamics and the hands (stickings), mark them and record yourself. A percussion solo tells a story too.","Estudio de concierto":"Concert study","Negras, blancas y redondas":"Quarter, half and whole notes","Antes de empezar":"Before you start","Las baquetas":"The sticks","Sujeta cada baqueta a un tercio del final, entre el pulgar y la segunda falange del \xEDndice. El resto de dedos la rodean sin apretar: la baqueta tiene que poder rebotar.":"Hold each stick a third of the way from the end, between your thumb and the second joint of your index finger. The other fingers wrap round it without squeezing: the stick has to be able to bounce.","Golpe y rebote":"Stroke and rebound","Deja caer la baqueta desde unos 10 cm y deja que rebote sola hacia arriba. El sonido sale de la ca\xEDda, no de empujar. Mu\xF1eca suelta y hombros relajados.":"Drop the stick from about 10 cm and let it bounce back up by itself. The sound comes from the fall, not from pushing. Loose wrist and relaxed shoulders.","Practica en la caja, en un pad o en una mesa. La app no oye notas: detecta cada golpe y te dice si llega a tiempo, antes o despu\xE9s. Calibra el micr\xF3fono una vez en Estudio.":"Practise on the snare, on a pad or on a table. The app doesn't hear pitches: it detects each stroke and tells you whether it is on time, early or late. Calibrate the microphone once in Practice.","Percusi\xF3n que afina":"Pitched percussion","Caja, bombo y platos no dan una nota concreta: solo se tensan los parches para que suenen bien. Los timbales, el xil\xF3fono y el glockenspiel s\xED dan notas.":"Snare, bass drum and cymbals don't give a specific note: the heads are only tightened so they sound good. Timpani, xylophone and glockenspiel do give notes.","Los timbales":"The timpani","Se afinan con el pedal, que tensa el parche, y el timbalero comprueba la nota con un diapas\xF3n o de o\xEDdo antes de cada obra.":"They are tuned with the pedal, which tightens the head, and the timpanist checks the note with a tuning fork or by ear before each piece.","La banda afina al Si\u266D":"The band tunes to B\u266D","La banda afina al Si\u266D de concierto: es la nota natural de la mayor\xEDa de sus instrumentos. La orquesta afina al La (todas las cuerdas tienen un La y el oboe lo da con un sonido estable). Algunas bandas usan La = 442 Hz en vez de 440.":"A band tunes to concert B\u266D: it is the natural note of most of its instruments. An orchestra tunes to A (every string instrument has an A and the oboe gives it with a steady sound). Some bands use A = 442 Hz instead of 440.","\xBFCu\xE1l de estos instrumentos de percusi\xF3n da notas afinadas?":"Which of these percussion instruments plays tuned notes?",Caja:"Snare drum",Bombo:"Bass drum",Timbales:"Timpani",Platos:"Cymbals","Los timbales: el pedal tensa el parche hasta la nota que pide la obra.":"The timpani: the pedal tightens the head to the note the piece asks for.",Negras:"Quarter notes","Un golpe por pulso":"One stroke per beat","Blancas y negras":"Half and quarter notes","Cuenta los pulsos largos":"Count the long beats","Redondas y negras":"Whole and quarter notes","Cuatro pulsos sin tocar":"Four beats without playing","Las corcheas":"Eighth notes","Cada pulso se divide en dos: cuenta \xABuno-y, dos-y\u2026\xBB. Alterna las manos (D I D I) y deja que caigan a la misma altura para que suenen igual.":"Each beat is divided in two: count \u201Cone-and, two-and\u2026\u201D. Alternate hands (R L R L) and let them fall from the same height so they sound the same.","Corcheas alternadas":"Alternating eighth notes","Negras y corcheas":"Quarter and eighth notes","Mezclar figuras":"Mixing note values","Saber cu\xE1ndo no tocar":"Knowing when not to play","Los silencios":"Rests","El silencio tambi\xE9n se cuenta":"Silence is counted too","Durante un silencio sigue contando y mueve la baqueta en el aire sin tocar: as\xED no pierdes el pulso.":"During a rest keep counting and move the stick in the air without playing: that way you don't lose the pulse.","Silencios de negra":"Quarter rests","Cuenta en el aire":"Count in the air",Contratiempo:"Offbeat","Golpe en la \xABy\xBB":"Stroke on the \u201Cand\u201D","Cuatro golpes por pulso":"Four strokes per beat","Las semicorcheas":"Sixteenth notes","Uno-e-y-a":"One-e-and-a","Cada pulso se divide en cuatro: \xABuno-e-y-a\xBB. Empieza despacio (al 50 %) y no aceleres: la regularidad es m\xE1s importante que la velocidad.":"Each beat is divided in four: \u201Cone-e-and-a\u201D. Start slowly (at 50 %) and don't speed up: evenness matters more than speed.","Leer percusi\xF3n":"Reading percussion","Cada sitio, un instrumento":"Each place, an instrument","La clave de percusi\xF3n son dos barras: no hay notas, sino instrumentos. Lo habitual: bombo en el primer espacio, caja en el tercero y platos encima del pentagrama, con la cabeza en forma de \xD7.":"The percussion clef is two bars: there are no pitches, but instruments. Usually: bass drum in the first space, snare in the third and cymbals above the staff, with an \xD7 notehead.","Las letras bajo las notas dicen la mano: D derecha, I izquierda. Respetarlas desde el principio hace que los pasajes r\xE1pidos salgan solos.":"The letters under the notes tell you the hand: R right, L left. Following them from the start makes fast passages come out by themselves.","\xBFQu\xE9 indica una \xABI\xBB debajo de una nota?":"What does an \u201CL\u201D under a note mean?","M\xE1s intenso":"Louder","Mano izquierda; la D es la derecha.":"Left hand; R is the right.","D e I":"R and L","Corchea y dos semicorcheas":"Eighth and two sixteenths",Galope:"Gallop",Rudimentos:"Rudiments","La t\xE9cnica b\xE1sica de caja":"Basic snare technique","Los rudimentos":"The rudiments","El abecedario del percusionista":"The percussionist's alphabet","Los rudimentos son combinaciones de manos que aparecen en todas las marchas: golpes simples (D I D I), dobles (D D I I) y paradiddle (D I D D I D I I). Mira las letras debajo de cada nota.":"Rudiments are hand combinations that appear in every march: single strokes (R L R L), doubles (R R L L) and paradiddle (R L R R L R L L). Look at the letters under each note (D = right, I = left).","Golpes simples":"Single strokes","Golpes dobles":"Double strokes","Golpes fuertes y suaves":"Loud and soft strokes","Los acentos":"Accents","Fuerte y suave":"Loud and soft","Una nota con \xAB>\xBB se toca m\xE1s fuerte, levantando m\xE1s la baqueta. Las dem\xE1s, bajas y suaves. La app compara la fuerza de tus golpes acentuados con la del resto.":"A note with \u201C>\u201D is played louder, lifting the stick higher. The rest, low and soft. The app compares the strength of your accented strokes with the others.","Acentos y redobles":"Accents and rolls","El acento":"The accent","El signo > sobre una nota pide tocarla m\xE1s fuerte que las dem\xE1s. Sube la baqueta un poco m\xE1s, no aprietes.":"The > sign over a note asks you to play it louder than the others. Lift the stick a little higher, don't squeeze.","Las rayitas cruzadas en la plica piden un redoble: muchos golpes seguidos que suenan como un sonido continuo. Se aprende despacio, golpe a golpe.":"The little slashes across the stem ask for a roll: many strokes in a row that sound like one continuous sound. It is learned slowly, stroke by stroke.","\xBFQu\xE9 significa el signo > sobre una nota?":"What does the > sign over a note mean?","M\xE1s fuerte (acento)":"Louder (accent)","M\xE1s largo":"Longer","Es un acento: esa nota se toca m\xE1s fuerte que las dem\xE1s.":"It is an accent: that note is played louder than the others.","Acento en la parte fuerte":"Accent on the downbeat","El primero de cada grupo":"The first of each group","Acentos que se mueven":"Moving accents","Uno de cada cuatro semicorcheas":"One in every four sixteenths","Ritmos de banda":"Band rhythms","Marcha, pasodoble y vals":"March, pasodoble and waltz","Tocar en la banda":"Playing in the band","El motor de la banda":"The engine of the band","La percusi\xF3n lleva el tempo de toda la banda. En la marcha y el pasodoble (2/4) el pulso no se puede mover; en el vals (3/4), el bombo marca el primer tiempo y la caja el segundo y el tercero.":"Percussion carries the whole band's tempo. In the march and the pasodoble (2/4) the pulse can't move; in the waltz (3/4), the bass drum marks the first beat and the snare the second and third.",Marcha:"March","2/4 con puntillo":"2/4 with dots","2/4 vivo":"Lively 2/4",Vals:"Waltz","3/4: um-pa-pa":"3/4: oom-pa-pa","El ritmo de tus canciones":"The rhythm of your songs","El ritmo de las canciones":"The rhythm of songs","Toca la melod\xEDa con la caja":"Play the melody on the snare","Cada canci\xF3n de la biblioteca se puede practicar como ritmo: tocas un golpe por cada nota. Es la mejor forma de aprender a leer cualquier partitura.":"Every song in the library can be practised as rhythm: you play one stroke per note. It is the best way to learn to read any score.","El pentagrama y la clave":"The staff and the clef","Redonda, blanca y negra":"Whole, half and quarter notes","Corcheas y puntillo":"Eighth notes and the dot","Sostenidos, bemoles y becuadros":"Sharps, flats and naturals","Signos de repetici\xF3n":"Repeat signs","Fuerte y suave: los matices":"Loud and soft: dynamics",Pentagrama:"Staff","Las cinco l\xEDneas donde se escribe la m\xFAsica.":"The five lines on which music is written.",Clave:"Clef","Signo del principio que da nombre a las notas.":"Sign at the start that names the notes.","El latido regular de la m\xFAsica.":"The steady heartbeat of the music.","Grupo de pulsos entre dos barras.":"Group of beats between two bar lines.","Figura de un pulso.":"Value of one beat.","Figura de dos pulsos.":"Value of two beats.","Figura de cuatro pulsos.":"Value of four beats.","Figura de medio pulso.":"Value of half a beat.",Puntillo:"Dot","Suma a la nota la mitad de su valor.":"Adds half of its value to the note.","Sube la nota medio tono.":"Raises the note a semitone.","Baja la nota medio tono.":"Lowers the note a semitone.",Becuadro:"Natural","Anula una alteraci\xF3n.":"Cancels an accidental.",Armadura:"Key signature","Alteraciones fijas junto a la clave.":"Fixed accidentals next to the clef.","Volver al principio.":"Back to the beginning.","Suave / fuerte.":"Soft / loud.","Figura de un cuarto de pulso.":"Value of a quarter of a beat.","Suma la duraci\xF3n de dos notas iguales.":"Adds up the length of two identical notes.","Tocar sin cortes entre las notas.":"Playing with no breaks between notes.","Nota corta y separada.":"Short, separated note.","Nota larga y apoyada.":"Long, leaned-on note.",Acento:"Accent","Ataque m\xE1s fuerte.":"Stronger attack.","Escala mayor":"Major scale","Siete notas con el patr\xF3n T-T-S-T-T-T-S.":"Seven notes with the pattern T-T-S-T-T-T-S.","Relativa menor":"Relative minor","Tonalidad menor con la misma armadura.":"Minor key with the same key signature.",Intervalo:"Interval","Distancia entre dos notas.":"Distance between two notes.","R\xE1pido.":"Fast.","Al paso.":"Walking pace.","Cada vez m\xE1s despacio.":"Slower and slower.","Calder\xF3n: alargar a gusto.":"Pause: hold at will.","Comp\xE1s de dos pulsos divididos en tres.":"Time of two beats divided into three.",Tresillo:"Triplet","Tres notas en el tiempo de dos.":"Three notes in the time of two.",S\u00EDncopa:"Syncopation","Nota en parte d\xE9bil prolongada sobre la fuerte.":"Note on a weak beat held over the strong one.",Tr\u00EDada:"Triad","Acorde de tres notas.":"Three-note chord.",Dominante:"Dominant","Acorde del V grado, de tensi\xF3n.":"Chord on the 5th degree, of tension.","Cadencia perfecta":"Perfect cadence","Dominante a t\xF3nica: V-I.":"Dominant to tonic: V-I.","Escala crom\xE1tica":"Chromatic scale","Los doce semitonos seguidos.":"The twelve semitones in a row.","Misma nota con dos nombres.":"Same note with two names.",Sensible:"Leading note","El 7.\xBA grado a medio tono de la t\xF3nica.":"The 7th degree a semitone below the tonic.","Forma ternaria":"Ternary form",Transpositor:"Transposing","Instrumento que suena distinto de lo que lee.":"Instrument that sounds different from what it reads.",Frase:"Phrase","Unidad musical con sentido completo.":"Musical unit with a complete meaning.","C. Petzold (cuaderno de A. M. Bach)":"C. Petzold (Anna Magdalena Bach notebook)","Himno tradicional":"Traditional hymn","Canci\xF3n marinera tradicional":"Traditional sea shanty","Scarborough Fair (primera frase)":"Scarborough Fair (first phrase)","Canci\xF3n tradicional estadounidense":"Traditional American song","Tradicional de Nueva Orleans":"Traditional from New Orleans","Villancico tradicional ingl\xE9s":"Traditional English carol","Villancico tradicional gal\xE9s":"Traditional Welsh carol","Himno tradicional (J. F. Wade)":"Traditional hymn (J. F. Wade)","Canci\xF3n infantil tradicional":"Traditional children's song","Canon popular franc\xE9s":"French folk round","M. y P. Hill":"M. and P. Hill","Canci\xF3n infantil alemana":"German children's song","Canci\xF3n infantil inglesa":"English children's song",Tradicional:"Traditional","Flamenco tradicional":"Traditional flamenco","El ukelele contra el pecho, sujeto con el antebrazo derecho, y el pulgar izquierdo detr\xE1s del m\xE1stil sin apretar.":"The ukulele against your chest, held with your right forearm, and your left thumb behind the neck without squeezing.","Busca el dedo que no se mueve entre dos acordes (de {Am} a {F}, el dedo 2) y mueve los dem\xE1s a la vez. Los cambios de un minuto miden tu progreso.":"Find the finger that stays put between two chords (from {Am} to {F}, finger 2) and move the others together. One-minute changes measure your progress.","El \xEDndice como un p\xE9ndulo: abajo en el pulso y arriba entre pulsos, toques o no. As\xED cualquier rasgueo sale a tempo.":"The index finger as a pendulum: down on the beat and up between beats, whether you strum or not. That way any strum stays in time.","Muchas s\xE9ptimas del ukelele son m\xE1s f\xE1ciles que el acorde normal ({C7}, {A7}). Dan empuje a la vuelta a casa.":"Many ukulele sevenths are easier than the plain chord ({C7}, {A7}). They give a push back home.","Punteo con los dedos":"Picking with the fingers","p-i-m-a, un dedo por cuerda: pulgar en el Sol, \xEDndice en el Do, medio en el Mi y anular en el La. Lento y parejo.":"p-i-m-a, one finger per string: thumb on G, index on C, middle on E and ring on A. Slow and even.","Un dedo por traste en los tres primeros trastes. La escala de Do usa las cuerdas Do, Mi y La; el Sol agudo repite notas.":"One finger per fret on the first three frets. The C scale uses the C, E and A strings; the high G repeats notes.","Apagar las cuerdas":"Muting the strings","El chuck: rasguea hacia abajo y apaga a la vez con el canto de la mano. Un sonido limpio es tan importante como las notas.":"The chuck: strum down and mute at the same time with the edge of your hand. A clean sound matters as much as the notes.","Cambia de acorde justo en la parte fuerte. Si dudas, simplifica el rasgueo, nunca el pulso.":"Change chord right on the strong beat. If in doubt, simplify the strum, never the beat.","Con cuatro cuerdas poco tensas es mucho m\xE1s f\xE1cil que en guitarra: el dedo 1 algo de lado y el peso del brazo.":"With four slack strings it is much easier than on guitar: finger 1 slightly on its side and the weight of the arm.","Las formas de {Bb} y {Bm} sirven en todo el m\xE1stil: s\xFAbelas traste a traste y cambia de tonalidad sin aprender acordes nuevos.":"The {Bb} and {Bm} shapes work all over the neck: move them up fret by fret and change key without learning new chords.","Melod\xEDa en la 1.\xAA cuerda":"Melody on the 1st string","Sube por la cuerda La m\xE1s all\xE1 del traste 5 para tocar melod\xEDas agudas; el Sol agudo te deja sonar notas al aire entre medias (campanella).":"Go up the A string past fret 5 to play high melodies; the high G lets open notes ring in between (campanella).","Fingerpicking reentrante":"Re-entrant fingerpicking","Como el Sol de la 4.\xAA es agudo, los patrones p-i-m-a suenan como un arpa: deja que las notas se mezclen.":"Because the 4th-string G is high, p-i-m-a patterns sound like a harp: let the notes blend.","Lee cifrados y tablaturas de 4 l\xEDneas (la de arriba es la 1.\xAA cuerda, La), pero aprende tambi\xE9n la partitura.":"Read chord charts and 4-line tabs (the top line is the 1st string, A), but learn notation too.","En un grupo el ukelele suena brillante: deja espacio a la voz y f\xEDjate en el bajo y el ritmo de los dem\xE1s.":"In a group the ukulele sounds bright: leave room for the voice and listen to the bass and the others' rhythm.","Postura y manos":"Posture and hands","Sentado encima del caj\xF3n, algo inclinado hacia delante, con la espalda recta. Las manos golpean desde la mu\xF1eca y rebotan: nunca se quedan pegadas a la tapa.":"Sit on top of the caj\xF3n, leaning slightly forward, with a straight back. The hands strike from the wrist and bounce: they never stay stuck to the front.","El grave, con la palma en el centro de la tapa, un poco por debajo del borde; el agudo, con los dedos juntos en la esquina superior. Que se distingan bien.":"The bass, with the palm in the centre of the front, a little below the edge; the slap, with the fingers together on the top corner. Make them clearly different.","Golpes alternos":"Alternating strokes","D-I-D-I con el mismo sonido en las dos manos. Empieza lento con el metr\xF3nomo y sube de 4 en 4 cuando salga igualado.":"R-L-R-L with the same sound in both hands. Start slowly with the metronome and go up 4 at a time when it is even.","Un acento es un golpe m\xE1s abierto, no m\xE1s tenso: sube m\xE1s la mano y deja las dem\xE1s notas suaves.":"An accent is a more open stroke, not a tenser one: lift the hand higher and keep the other notes soft.","M\xE1s recorrido de la mano, m\xE1s volumen. Practica crescendos de pp a ff sin acelerar.":"More hand travel, more volume. Practise crescendos from pp to ff without speeding up.","Ghost notes":"Ghost notes","Notas muy suaves con la punta de los dedos entre los golpes fuertes: rellenan el ritmo sin taparlo.":"Very soft notes with the fingertips between the strong strokes: they fill the rhythm without covering it.","El metr\xF3nomo es tu compa\xF1ero de ensayo. Ponlo tambi\xE9n en las corcheas para comprobar que lo de entre pulsos est\xE1 igualado.":"The metronome is your practice partner. Set it to eighth notes too, to check that the notes between beats are even.","El redoble de dedos":"Finger rolls","Golpes muy r\xE1pidos con las yemas, alternando manos o dedo a dedo, cerca del borde. Empieza lento y sin tensi\xF3n.":"Very fast strokes with the fingertips, alternating hands or finger by finger, near the edge. Start slowly and without tension.","El flam en el caj\xF3n":"The flam on the caj\xF3n","Una mano muy suave justo antes que la otra en el mismo golpe: engorda el sonido. Pract\xEDcalo empezando con cada mano.":"One hand very softly just before the other on the same stroke: it fattens the sound. Practise it starting with each hand.","En 6/8 y 12/8 siente el pulso en grupos de tres. Las buler\xEDas y la sole\xE1 se cuentan en ciclos de 12.":"In 6/8 and 12/8 feel the beat in groups of three. Buler\xEDas and sole\xE1 are counted in 12-beat cycles.","El grave marca el pulso y el agudo hace el ritmo: practica cada mano sola y luego juntas, lento.":"The bass keeps the beat and the slap plays the rhythm: practise each hand alone and then together, slowly.","Tonos de la tapa":"Tones of the front","Prueba sonidos entre el centro y el borde, y con la palma apagando la tapa: cada zona tiene su color.":"Try sounds between the centre and the edge, and with the palm damping the front: each area has its own colour.","Acompa\xF1ar a otros":"Accompanying others","El caj\xF3n sostiene el ritmo del grupo: escucha la guitarra y la voz, toca menos de lo que sabes y no te dejes arrastrar.":"The caj\xF3n holds the group's rhythm: listen to the guitar and the voice, play less than you know and don't get dragged along.","Toma aire abajo, sin subir los hombros, y su\xE9ltalo muy despacio: la flauta dulce necesita poco aire y siempre igual.":"Breathe in low, without raising your shoulders, and let it out very slowly: the recorder needs little air and always the same.","Notas largas con un \xABduuu\xBB suave y constante. Si la nota sube o chilla, soplas demasiado; si suena d\xE9bil y baja, falta aire.":"Long notes with a soft, steady \u201Cdooo\u201D. If the note rises or squeaks, you are blowing too hard; if it sounds weak and flat, you need more air.","Pica con la punta de la lengua diciendo \xABdu\xBB. En lo ligado la lengua no se mueve y los dedos cambian a la vez.":"Tongue with the tip of the tongue saying \u201Cdoo\u201D. In legato the tongue does not move and the fingers change together.","Tapar bien los agujeros":"Covering the holes well","Los dedos planos tapan con la yema, sin apretar. Si una nota grave no sale, casi siempre hay un agujero mal tapado.":"Flat fingers cover with the pad, without pressing. If a low note does not sound, there is almost always a hole not fully covered.","El pulgar de atr\xE1s":"The back thumb","Para las agudas, el pulgar deja una rendija peque\xF1a en el agujero de atr\xE1s, dobl\xE1ndolo un poco. Practica Mi-Mi agudo despacio.":"For high notes, the thumb leaves a small gap in the back hole by bending slightly. Practise E to high E slowly.","En la flauta dulce la afinaci\xF3n depende del soplo: m\xE1s fuerte, m\xE1s alta. Busca con el afinador el aire justo de cada nota.":"On the recorder the tuning depends on the breath: harder means higher. Use the tuner to find the right air for each note.","Los dedos, cerca de los agujeros y curvos. Sube la velocidad con el metr\xF3nomo de 4 en 4: si se tensan, vuelve atr\xE1s.":"Fingers close to the holes and curved. Increase the speed with the metronome 4 at a time: if they tense up, go back.","Do y Sol mayor primero, luego Fa con su digitaci\xF3n de horquilla para el Si\u266D. Ligadas y picadas.":"C and G major first, then F with its forked fingering for B\u266D. Slurred and tongued.","Digitaciones de horquilla":"Forked fingerings","Notas como el Fa\u266F o el Si\u266D se hacen destapando un agujero entre otros tapados. Apr\xE9ndelas despacio y escucha que salgan afinadas.":"Notes like F\u266F or B\u266D are made by opening one hole between closed ones. Learn them slowly and listen that they are in tune.","Alterna \xABdu-gu\xBB para picar muy r\xE1pido. Practica solo la s\xEDlaba \xABgu\xBB hasta que suene igual de clara que \xABdu\xBB.":"Alternate \u201Cdoo-goo\u201D to tongue very fast. Practise just the \u201Cgoo\u201D syllable until it is as clear as \u201Cdoo\u201D.","Como el aire cambia la afinaci\xF3n, los matices se hacen sobre todo con la articulaci\xF3n y el car\xE1cter, y con alg\xFAn dedo de correcci\xF3n en las notas largas.":"Because the air changes the tuning, dynamics come mostly from articulation and character, with an occasional correcting finger on long notes.","Trinos, mordentes y notas de adorno son el alma de la m\xFAsica barroca para flauta de pico. T\xF3calos ligeros y a tempo.":"Trills, mordents and grace notes are the soul of baroque recorder music. Play them light and in time.","Estudios y repertorio":"Studies and repertoire","Los m\xE9todos y las piezas barrocas (Van Eyck, Telemann) trabajan dedos y articulaci\xF3n. Una pieza por semana, lenta y perfecta.":"Methods and baroque pieces (Van Eyck, Telemann) work on fingers and articulation. One piece a week, slow and perfect.","En clase o en un conjunto de flautas, escucha a quien toca tu voz y ajusta el soplo para sonar igual de afinados.":"In class or in a recorder ensemble, listen to whoever plays your part and adjust your breath so you sound equally in tune.","Preparar una pieza":"Preparing a piece","Gr\xE1bate, esc\xFAchate y corrige. Decide d\xF3nde respirar y marca los matices en la partitura.":"Record yourself, listen and correct. Decide where to breathe and mark the dynamics in the music.","El peso del brazo":"The weight of the arm","El sonido sale del peso del brazo que cae en la cuerda a trav\xE9s del \xEDndice y el medio, no de apretar con la mano.":"The sound comes from the weight of the arm falling into the string through the index and middle fingers, not from squeezing with the hand.","El dedo 2 y el dedo 3":"Fingers 2 and 3","En el chelo cada dedo es medio tono: el 2 da la tercera menor y el 3 la mayor. Escucha la diferencia entre Do natural (dedo 2) y Do\u266F (dedo 3) en la cuerda La.":"On the cello each finger is a semitone: 2 gives the minor third and 3 the major. Hear the difference between C natural (finger 2) and C\u266F (finger 3) on the A string.","Las extensiones":"Extensions","Hacia atr\xE1s, el 1 se abre medio tono hacia la cejuela (Si\u266D en la cuerda La); hacia delante, el 4 se estira medio tono (Do\u266F en la cuerda Sol). La mano no se mueve: se abre.":"Backwards, finger 1 opens a semitone towards the nut (B\u266D on the A string); forwards, finger 4 stretches a semitone (C\u266F on the G string). The hand does not move: it opens.","Cada cuerda tiene su altura de brazo: Do con el codo alto, La con el codo bajo. Prepara el brazo antes de cambiar.":"Each string has its own arm height: C with the elbow high, A with the elbow low. Prepare the arm before changing.","Compara con las cuerdas al aire: el Re con el dedo 4 en la cuerda La debe \xABhacer vibrar\xBB la cuerda Re al aire.":"Check against the open strings: the D with finger 4 on the A string should make the open D string \u201Cring\u201D.","Escalas en primera posici\xF3n":"Scales in first position","Do mayor y Re mayor de dos octavas (Re con las extensiones) y Sol mayor de una octava, de memoria y lentas, con la afinaci\xF3n vigilada nota a nota. Sol de dos octavas llega con la cuarta posici\xF3n.":"C major and D major over two octaves (D with the extensions) and G major over one octave, from memory and slowly, watching the tuning note by note. Two-octave G comes with fourth position.","La cuarta posici\xF3n":"Fourth position","Desliza la mano hasta que el dedo 1 d\xE9 el Mi en la cuerda La (donde el pulgar toca el tal\xF3n del m\xE1stil). Practica el cambio con un dedo gu\xEDa y sin prisa.":"Slide the hand until finger 1 gives the E on the A string (where the thumb meets the heel of the neck). Practise the shift with a guide finger and without hurrying.","Un balanceo del brazo entero que mueve el dedo sobre la cuerda. Empieza lento, con el metr\xF3nomo, sobre notas largas.":"A rocking of the whole arm that moves the finger on the string. Start slowly, with the metronome, on long notes.","Los estudios de Dotzauer y de Lee trabajan arco y mano izquierda. Uno por semana, lento y perfecto.":"The Dotzauer and Lee studies work on the bow and the left hand. One a week, slow and perfect.","La clave de do en 4.\xAA":"Tenor clef","Para las notas agudas el chelo lee en clave de do en 4.\xAA: el Do central est\xE1 en la 4.\xAA l\xEDnea. Lee despacio las primeras veces.":"For high notes the cello reads tenor clef: middle C is on the 4th line. Read slowly at first.","Copia los arcos del solista de chelos y escucha a tu atril: misma parte del arco y mismo car\xE1cter.":"Copy the principal cellist's bowings and listen to your desk partner: same part of the bow and same character.","Al cambiar de matiz la afinaci\xF3n tiende a moverse (en la flauta, el piano baja y el forte sube). Vig\xEDlala con el afinador y mant\xE9n el aire apoyado en los dos extremos.":"When the dynamic changes the tuning tends to move (on the flute, piano goes flat and forte goes sharp). Watch it with the tuner and keep the air supported at both extremes.","Las notas con los pistones 1 y 3 (y 1, 2 y 3) salen altas: corr\xEDgelas sacando la bomba del 3.er pist\xF3n o con el 4.\xBA pist\xF3n si lo tienes. El o\xEDdo manda.":"Notes using valves 1 and 3 (and 1, 2 and 3) come out sharp: correct them by pulling the 3rd valve slide or with the 4th valve if you have one. The ear rules.","En la bater\xEDa y la percusi\xF3n m\xFAltiple, manos y pies hacen cosas distintas. Practica cada parte sola y luego juntas, lento.":"On drum kit and multi-percussion, hands and feet do different things. Practise each part alone and then together, slowly.","Marchas y pasodobles":"Marches and pasodobles","La caja y el bombo sostienen la banda en la calle: aprende los patrones de marcha y de pasodoble y d\xF3nde caen los acentos. Escucha grabaciones y cuenta con ellas.":"Snare and bass drum hold the band together on the street: learn the march and pasodoble patterns and where the accents fall. Listen to recordings and count along.","Cambia de arm\xF3nico sin mover la vara. Empieza con dos notas vecinas en 1.\xAA posici\xF3n y ampl\xEDa poco a poco.":"Change partial without moving the slide. Start with two neighbouring notes in 1st position and widen gradually.","En el tromb\xF3n afinas con la vara: la 3.\xAA y la 4.\xAA posici\xF3n tienden a quedarse cortas y la 6.\xAA y la 7.\xAA se estiran. Escucha y ajusta un par de cent\xEDmetros.":"On the trombone you tune with the slide: 3rd and 4th positions tend to fall short and 6th and 7th stretch out. Listen and adjust a couple of centimetres.","Ondulaci\xF3n suave con la vara o la mand\xEDbula. En la banda se usa poco y siempre con gusto: escucha a tu secci\xF3n.":"A gentle wave with the slide or the jaw. In a band it is used sparingly and always with taste: listen to your section.","El Arban y los estudios de Rochut (legato) y Kopprasch trabajan flexibilidad y vara. Uno por semana, lento y perfecto antes que r\xE1pido.":"The Arban and the Rochut (legato) and Kopprasch studies work on flexibility and the slide. One a week, slow and perfect before fast.","Cambia de arm\xF3nico sin mover los cilindros. En la trompa los arm\xF3nicos est\xE1n muy juntos: empieza con dos vecinos y ampl\xEDa poco a poco.":"Change partial without moving the rotary valves. On the horn the partials are very close: start with two neighbours and widen gradually.","En la trompa la mano derecha dentro de la campana afina: m\xE1s cerrada, la nota baja; m\xE1s abierta, sube. Ajusta tambi\xE9n las bombas de los cilindros.":"On the horn the right hand inside the bell tunes: more closed lowers the note; more open raises it. Adjust the valve slides too.","En la trompa casi no se usa vibrato: busca un sonido redondo y estable con la mano en la campana.":"On the horn vibrato is hardly used: look for a round, steady sound with the hand in the bell.","Adem\xE1s de la sordina, la trompa tapa la campana con la mano (sonido tapado), que sube la nota medio tono: se corrige con la digitaci\xF3n.":"Besides the mute, the horn can close the bell with the hand (stopped sound), which raises the note a semitone: it is corrected with the fingering.","Los estudios de Kopprasch y Maxime-Alphonse trabajan flexibilidad y dedos. Uno por semana, lento y perfecto antes que r\xE1pido.":"The Kopprasch and Maxime-Alphonse studies work on flexibility and fingers. One a week, slow and perfect before fast.","Do\u266F y Re\u266D suenan igual (en el piano son la misma tecla negra): se escribe uno u otro seg\xFAn la tonalidad.":"C\u266F and D\u266D sound the same (on the piano they are the same black key): you write one or the other depending on the key.","Do, Sol, Re y La: cada cuerda est\xE1 una quinta por encima de la anterior, una octava por debajo de la viola. Se afina primero el La (220 Hz con el La de 440) y las dem\xE1s compar\xE1ndolas con ella.":"C, G, D and A: each string is a fifth above the one before, an octave below the viola. Tune the A first (220 Hz with A = 440) and then the others against it.","Las clavijas hacen cambios grandes; los tensores finos del cordal, los peque\xF1os. Gira las clavijas empuj\xE1ndolas hacia dentro para que no se suelten.":"The pegs make big changes; the fine tuners on the tailpiece, small ones. Turn the pegs while pushing them in so they don't slip.","El chelo suena exactamente lo que lees. Lee en clave de fa y, para las notas agudas, en clave de do en 4.\xAA y en clave de sol. La banda afina al Si\u266D de concierto: es la nota natural de la mayor\xEDa de sus instrumentos. La orquesta afina al La (todas las cuerdas tienen un La y el oboe lo da con un sonido estable). Algunas bandas usan La = 442 Hz en vez de 440.":"The cello sounds exactly what you read. It reads bass clef and, for high notes, tenor and treble clef. A band tunes to concert B\u266D: it is the natural note of most of its instruments. An orchestra tunes to A (every string instrument has an A and the oboe gives it with a steady sound). Some bands use A = 442 Hz instead of 440.","Labios juntos, comisuras firmes y la boquilla centrada de lado a lado; la altura depende del instrumento (en la trompa, unos dos tercios de labio de arriba). Haz vibrar los labios (el \xABbuzz\xBB) y deja que la boquilla lo amplifique.":"Lips together, firm corners and the mouthpiece centred side to side; the height depends on the instrument (on the horn, about two thirds upper lip). Make your lips vibrate (the \u201Cbuzz\u201D) and let the mouthpiece amplify it.","El labio de abajo cubre un poco los dientes, los dientes de arriba apoyan en la boquilla y los labios rodean la boquilla como una goma, sin morder. Si el sonido sale alto y estrecho, afloja la mand\xEDbula.":"The lower lip covers the teeth slightly, the upper teeth rest on the mouthpiece and the lips seal around it like an elastic band, without biting. If the sound comes out sharp and thin, loosen your jaw.","La placa de la embocadura apoya bajo el labio de abajo, que tapa un tercio del agujero. Labios relajados y una abertura peque\xF1a: sopla hacia el borde del agujero, como al soplar sobre una botella.":"The lip plate rests under the lower lip, which covers a third of the hole. Relaxed lips and a small opening: blow towards the edge of the hole, as when blowing across a bottle.","Las bandas afinan y calientan en Si\u266D mayor de concierto. Tu parte se escribe en sonido real, as\xED que para ti es Si\u266D mayor tal cual.":"Bands tune and warm up in concert B\u266D major. Your part is written at concert pitch, so for you it is simply B\u266D major.","Los dos labios cubren los dientes y rodean la punta de la ca\xF1a doble como un cord\xF3n, sin morder. Solo entran unos mil\xEDmetros de ca\xF1a.":"Both lips cover the teeth and surround the tip of the double reed like a drawstring, without biting. Only a few millimetres of reed go in.","Empezamos por Fa, Mi\u266D, Re (notas escritas). El diagrama te muestra en qu\xE9 posici\xF3n va la vara en cada una.":"We start with F, E\u266D, D (written notes). The diagram shows you the slide position for each one.","Lees en sonido real":"You read at concert pitch","El tromb\xF3n es un instrumento en Si\u266D (con la vara cerrada da la serie de Si\u266D), pero lee en clave de fa y suena lo que lees: cuando la banda afina al Si\u266D, t\xFA tocas Si\u266D en 1.\xAA posici\xF3n, con la vara cerrada.":"The trombone is a B\u266D instrument (with the slide closed it gives the B\u266D harmonic series), but it reads bass clef and sounds what you read: when the band tunes to B\u266D, you play B\u266D in 1st position, with the slide closed.","Tu instrumento lee en sonido real (suena lo que lees): para que suene Si\u266D t\xFA lees y tocas Si\u266D.":"Your instrument reads at concert pitch (it sounds what you read): for B\u266D to sound, you read and play B\u266D.","Lees en sonido real (clave de fa)":"You read at concert pitch (bass clef)","Tu instrumento lee en sonido real en clave de fa (suena lo que lees): para que suene Si\u266D t\xFA lees y tocas Si\u266D.":"Your instrument reads at concert pitch in bass clef (it sounds what you read): for B\u266D to sound, you read and play B\u266D.","Do\u266F y Re\u266D suenan igual: son la misma nota escrita de dos maneras (en el piano, la misma tecla negra). Se escribe una u otra seg\xFAn la tonalidad.":"C\u266F and D\u266D sound the same: they are the same note written two ways (on the piano, the same black key). You write one or the other depending on the key.","Para tocarlo en p\xFAblico":"To play in public","Un acorde por comp\xE1s: izquierda en el bajo, derecha en el acorde":"One chord per bar: left hand on the bass, right hand on the chord","Arpegio de C":"C arpeggio","Escala de Do":"C scale","Arpegio de Do":"C arpeggio","Muchas obras de banda est\xE1n en Mi\u266D y Fa de concierto. Practicamos la escala de Do escrita y su arpegio.":"Many band pieces are in concert E\u266D and F. We practise the written C scale and its arpeggio.","Arpegio de D":"D arpeggio","Escala de Re":"D scale","Arpegio de Re":"D arpeggio","Muchas obras de banda est\xE1n en Mi\u266D y Fa de concierto. Practicamos la escala de Re escrita y su arpegio.":"Many band pieces are in concert E\u266D and F. We practise the written D scale and its arpeggio.","Arpegio de F":"F arpeggio","Escala de Fa":"F scale","Arpegio de Fa":"F arpeggio","Muchas obras de banda est\xE1n en Mi\u266D y Fa de concierto. Practicamos la escala de Fa escrita y su arpegio.":"Many band pieces are in concert E\u266D and F. We practise the written F scale and its arpeggio.","Escala de Mi\u266D":"E\u266D scale","Arpegio de Mi\u266D":"E\u266D arpeggio","Muchas obras de banda est\xE1n en Mi\u266D y Fa de concierto. Practicamos la escala de Mi\u266D escrita y su arpegio.":"Many band pieces are in concert E\u266D and F. We practise the written E\u266D scale and its arpeggio.","Escala de E\u266D":"E\u266D scale","Arpegio de E\u266D":"E\u266D arpeggio","Muchas obras de banda est\xE1n en Mi\u266D y Fa de concierto. Practicamos la escala de E\u266D escrita y su arpegio.":"Many band pieces are in concert E\u266D and F. We practise the written E\u266D scale and its arpeggio.",Petzold:"Petzold","Do, Re y Mi":"C, D and E","Tus tres primeras l\xE1minas":"Your first three bars","\xA1Hola, xilofonista!":"Hello, xylophone player!","Coge cada baqueta como si dieras la mano: el pulgar a un lado, el \xEDndice al otro y los dem\xE1s dedos rode\xE1ndola sin apretar.":"Hold each mallet as if shaking hands: thumb on one side, index on the other and the other fingers wrapped round without squeezing.","Golpea y rebota":"Strike and bounce","Da en el centro de la l\xE1mina y deja que la baqueta salte hacia arriba sola, como una pelota. Si la dejas apoyada, la nota se apaga.":"Hit the middle of the bar and let the mallet jump back up by itself, like a ball. If you leave it resting there, the note dies.","Tu primera l\xE1mina: Do":"Your first bar: C","Las l\xE1minas largas suenan graves y las cortas, agudas. La 1, la m\xE1s larga de la izquierda, es el Do.":"Long bars sound low and short ones high. Bar 1, the longest on the left, is C.","Pon el m\xF3vil cerca del xil\xF3fono. Da igual que tu xil\xF3fono suene m\xE1s agudo o m\xE1s grave: si aciertas la l\xE1mina, se pone en verde.":"Put the phone near the xylophone. It does not matter if your xylophone sounds higher or lower: if you hit the right bar, it turns green.","Las l\xE1minas 1, 2 y 3":"Bars 1, 2 and 3","Bollitos calientes":"Hot cross buns","El baile del robot":"The robot dance","Do, Re y Mi con silencios":"C, D and E with rests","Fa y Sol":"F and G","Cinco l\xE1minas":"Five bars","Dos l\xE1minas m\xE1s":"Two more bars","Fa es la l\xE1mina 4 y Sol la 5. Con Do, Re, Mi, Fa y Sol ya puedes tocar much\xEDsimas canciones.":"F is bar 4 and G is bar 5. With C, D, E, F and G you can already play lots of songs.","Una mano y otra":"One hand and the other","Alterna las baquetas: derecha, izquierda, derecha\u2026 As\xED nunca se cansa una mano y las notas salen iguales.":"Alternate the mallets: right, left, right\u2026 That way no hand gets tired and the notes come out even.","Sube y baja":"Up and down","De Do a Sol":"From C to G","Mar\xEDa ten\xEDa un corderito":"Mary had a little lamb","La, Si y Do agudo":"A, B and high C","Todas las l\xE1minas":"All the bars","El xil\xF3fono entero":"The whole xylophone","La, Si y Do":"A, B and C","La es la l\xE1mina 6, Si la 7 y la \xFAltima, la m\xE1s corta, otra vez Do, pero agudo. \xA1Ya tienes la escala de Do!":"A is bar 6, B is bar 7 and the last, the shortest, is C again, but high. Now you have the C scale!","Mira antes de golpear":"Look before you strike","Antes de cada nota, mira la l\xE1mina a la que vas. Las baquetas siguen a los ojos.":"Before each note, look at the bar you are going to. The mallets follow your eyes.","La escala de Do":"The C scale","De la l\xE1mina 1 a la 8":"From bar 1 to bar 8","Mis patitos":"My little ducklings",Estrellita:"Twinkle, twinkle","M\xE1s r\xE1pido":"Faster","Dos corcheas duran lo mismo que una negra. Cuenta \xABun-y, dos-y\xBB y toca una nota en cada s\xEDlaba.":'Two eighth notes last as long as a quarter note. Count "one-and, two-and" and play a note on each syllable.',"Para repetir una nota r\xE1pido, alterna las manos sobre la misma l\xE1mina: derecha-izquierda-derecha.":"To repeat a note quickly, alternate hands on the same bar: right-left-right.","Alterna las manos":"Alternate hands","Jingle Bells":"Jingle Bells","En la granja de mi t\xEDo":"Old MacDonald had a farm","\xA1Ia, ia, oh!":"E-I-E-I-O!","De l\xE1mina en l\xE1mina":"From bar to bar","Saltar sin miedo":"Leap without fear","El arpegio":"The arpeggio","Do, Mi, Sol y Do agudo: una l\xE1mina s\xED y otra no. Es el salto m\xE1s famoso de la m\xFAsica.":"C, E, G and high C: every other bar. It is the most famous leap in music.","Notas en otra octava":"Notes in another octave","Si la partitura pide una nota m\xE1s grave que tu l\xE1mina 1, toca la del mismo nombre que tengas: la app tambi\xE9n te la da por buena.":"If the music asks for a note lower than your bar 1, play the one with the same name that you have: the app counts it as right too.","Saltos de una l\xE1mina":"Skipping one bar","Cuando los santos":"When the Saints","When the Saints, de Nueva Orleans":"When the Saints, from New Orleans","El puente de Londres":"London Bridge","Canci\xF3n inglesa":"English song",Martinillo:"Fr\xE8re Jacques","T\xF3calo en canon con alguien":"Play it as a round with someone","Xil\xF3fono grande":"Big xylophone","Graves y l\xE1minas de atr\xE1s":"Low notes and back-row bars","Si tu xil\xF3fono tiene m\xE1s l\xE1minas":"If your xylophone has more bars","Las l\xE1minas de atr\xE1s":"The back-row bars","Los xil\xF3fonos grandes tienen una segunda fila, como las teclas negras del piano: son los sostenidos y bemoles.":"Big xylophones have a second row, like the black keys of a piano: they are the sharps and flats.","Las graves":"The low ones","A la izquierda de tu Do hay l\xE1minas m\xE1s largas: Si, La, Sol\u2026 Si tu xil\xF3fono no las tiene, toca la misma nota en otra l\xE1mina: tambi\xE9n vale.":"To the left of your C there are longer bars: B, A, G\u2026 If your xylophone does not have them, play the same note on another bar: it counts too.","Cumplea\xF1os feliz":"Happy Birthday","Para todas las fiestas":"For every party","La canci\xF3n del Tetris":"The Tetris song","Korob\xE9iniki, canci\xF3n popular rusa":"Korobeiniki, Russian folk song",Beethoven:"Beethoven",Concierto:"Concert","\xA1Ya eres xilofonista!":"You are a xylophonist now!","Elige tus tres canciones favoritas, t\xF3calas seguidas y gr\xE1bate. Ens\xE9\xF1aselo a tu familia: \xA1los aplausos tambi\xE9n cuentan!":"Choose your three favourite songs, play them one after another and record yourself. Show your family: applause counts too!","L\xE1minas de madera":"Wooden bars","Xilo quiere decir \xABmadera\xBB en griego. Las l\xE1minas largas suenan graves y las cortas agudas. Los de juguete suelen ser de metal: se llaman metal\xF3fonos o carillones.":'Xylo means "wood" in Greek. Long bars sound low and short ones high. Toy ones are often metal: they are called metallophones or glockenspiels.',"Se escribe m\xE1s grave":"Written lower","El xil\xF3fono suena una octava m\xE1s agudo de lo que se escribe, para que la partitura no se llene de l\xEDneas adicionales. Cada marca suena en una octava distinta: la app te escucha en cualquiera.":"The xylophone sounds an octave higher than written, so the music does not fill up with ledger lines. Each brand sounds in a different octave: the app hears you in any of them.","Viene afinado":"It comes in tune","Las l\xE1minas se afinan en la f\xE1brica limando la madera por debajo: t\xFA no tienes que afinar nada. Solo acertar la l\xE1mina.":"The bars are tuned at the factory by filing the wood underneath: you do not have to tune anything. Just hit the right bar.","\xBFQu\xE9 l\xE1minas suenan m\xE1s graves?":"Which bars sound lower?","Las m\xE1s cortas":"The shortest","Las m\xE1s largas":"The longest","Las de colores claros":"The light-coloured ones","Todas igual":"All the same","Cuanto m\xE1s larga es la l\xE1mina, m\xE1s despacio vibra y m\xE1s grave suena.":"The longer the bar, the slower it vibrates and the lower it sounds.",Postura:"Posture","De pie o sentado con el xil\xF3fono a la altura de la cintura y un poco separado: los codos sueltos y las baquetas formando una \xABV\xBB.":'Standing or sitting with the xylophone at waist height and a little away from you: loose elbows and the mallets forming a "V".',"El golpe sale de la mu\xF1eca y la baqueta rebota sola. Busca el centro de la l\xE1mina: ah\xED suena m\xE1s redondo.":"The stroke comes from the wrist and the mallet bounces back by itself. Aim for the middle of the bar: it sounds fullest there.","Manos alternas":"Alternate hands","D-I-D-I sobre la misma l\xE1mina y luego subiendo la escala. Empieza lento con el metr\xF3nomo y sube de 4 en 4.":"R-L-R-L on the same bar and then up the scale. Start slowly with the metronome and go up 4 at a time.","Mirar adelantado":"Look ahead","Mientras tocas una nota, los ojos ya buscan la siguiente l\xE1mina. As\xED los saltos dejan de dar miedo.":"While you play one note, your eyes are already looking for the next bar. That way leaps stop being scary.","Cuenta en voz alta \xAB1-y-2-y\xBB. En el xil\xF3fono las notas no se sostienen: el ritmo lo marcan los golpes.":'Count out loud "1-and-2-and". On the xylophone notes do not sustain: the strokes mark the rhythm.',"M\xE1s altura de baqueta, m\xE1s volumen. Practica una escala de pp a ff sin acelerar.":"Higher mallet, more volume. Practise a scale from pp to ff without speeding up.","Saltos y arpegios":"Leaps and arpeggios","Do-Mi-Sol-Do: practica cada salto lento, mirando la l\xE1mina antes de golpear.":"C-E-G-C: practise each leap slowly, looking at the bar before you strike.","El xil\xF3fono suena brillante y corto: en grupo, toca algo m\xE1s suave para no tapar la melod\xEDa de los dem\xE1s.":"The xylophone sounds bright and short: in a group, play a little softer so you do not cover the others' melody.","El tr\xE9molo":"The tremolo","Para que una nota larga \xABsuene seguida\xBB, alterna las dos baquetas muy r\xE1pido sobre la misma l\xE1mina, sin tensi\xF3n.":'To make a long note "keep sounding", alternate both mallets very fast on the same bar, without tension.',"Dobles y paradiddles":"Doubles and paradiddles","Los rudimentos de la caja (DD-II, D-I-D-D) tambi\xE9n sirven en las l\xE1minas para elegir qu\xE9 mano va a cada nota.":"Snare rudiments (RR-LL, R-L-R-R) also work on the bars to choose which hand goes to each note.","La fila de atr\xE1s":"The back row","Sostenidos y bemoles van detr\xE1s: golp\xE9alos en el borde de delante de la l\xE1mina, que queda m\xE1s cerca de ti.":"Sharps and flats are at the back: strike them on the front edge of the bar, which is closer to you.","Escalas en todas las tonalidades":"Scales in every key","Do, Sol y Fa mayor primero, luego las dem\xE1s. Una octava, despu\xE9s dos, siempre alternando manos.":"C, G and F major first, then the rest. One octave, then two, always alternating hands.","Cuatro baquetas":"Four mallets","Los marimbistas usan dos baquetas en cada mano para tocar acordes. Empieza con terceras en la mano derecha.":"Marimba players use two mallets in each hand to play chords. Start with thirds in the right hand.","Lectura a primera vista":"Sight-reading","Mira la armadura, el comp\xE1s y los saltos grandes antes de empezar. Al tocar, mant\xE9n el pulso aunque falles una l\xE1mina.":"Look at the key signature, the time signature and the big leaps before you start. While playing, keep the beat even if you miss a bar.",Repertorio:"Repertoire","Ragtimes, marchas y piezas de orquesta tienen solos de xil\xF3fono famosos. Esc\xFAchalos y elige uno para preparar.":"Ragtimes, marches and orchestral pieces have famous xylophone solos. Listen to them and choose one to prepare.","Decide las manos de los pasajes dif\xEDciles, m\xE1rcalas en la partitura y gr\xE1bate para escucharte.":"Decide the sticking for the hard passages, mark it in the music and record yourself to listen back.","{D5}: la 4.\xAA cuerda al aire y el dedo 1 en el traste 2 de la 3.\xAA. {C5}: dedo 1 en el traste 3 de la 5.\xAA y dedo 3 en el traste 5 de la 4.\xAA. La misma forma que {G5}, una cuerda m\xE1s aguda.":"{D5}: the open 4th string and finger 1 on fret 2 of the 3rd. {C5}: finger 1 on fret 3 of the 5th and finger 3 on fret 5 of the 4th. The same shape as {G5}, one string higher.","El mismo camino empezando en {Dm}: {Dm}, {C}, {Bb} y {A}. Lo llaman \xABpor medio\xBB porque descansa en La. {Bb} es la forma de {A} en el traste 1 con cejilla del dedo 1: si cuesta, toca solo las cuatro cuerdas agudas.":"The same path starting on {Dm}: {Dm}, {C}, {Bb} and {A}. It is called \u201Cpor medio\u201D because it comes to rest on A. {Bb} is the {A} shape on fret 1 with a finger-1 barre: if it is hard, play only the four high strings.","Es {C} con un Si\u266D a\xF1adido: Do, Mi, Sol y Si\u266D. Suena a blues y pide ir a {F}.":"It is {C} with an added B\u266D: C, E, G and B\u266D. It sounds bluesy and wants to move to {F}.","Mi, Sol\u266F y Si: la tecla negra del medio es el Sol\u266F. En La menor, {E} es el acorde que vuelve a {Am}.":"E, G\u266F and B: the black key in the middle is the G\u266F. In A minor, {E} is the chord that leads back to {Am}.","Sopla despacito, como si dijeras \xABduuu\xBB para calentarte las manos, no para apagar una vela. Si la flauta pita, est\xE1s soplando demasiado fuerte.":"Blow very gently, as if you were saying \u201Cdooo\u201D to warm your hands, not to blow out a candle. If the recorder squeaks, you are blowing too hard.","Lo vas a encontrar en las canciones de esta unidad: trastes 2, 2 y 1 en las cuerdas 4, 3 y 2 (la 1.\xAA al aire). Es {F} con un dedo m\xE1s.":"You will find it in the songs of this unit: frets 2, 2 and 1 on strings 4, 3 and 2 (the 1st open). It is {F} with one more finger.","En Do, en las cuerdas Do, Mi y La":"In C, on the C, E and A strings","Balada en La menor":"Ballad in A minor"};export{u as CONTENT};
